insert into public.transaction_municipal_requirements
  (municipality_code, municipality_name, county, requirement_key, requirement_state, title, requirements, fees, application_url, department_url, source_urls, source_excerpt, source_hash, last_verified_at, metadata, curated_note, curated_override)
values
  ($t$0101$t$, $t$Absecon$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO)$t$, $j$["Issued by: City of Absecon Construction & Code Enforcement Office","Contact: Leigh Gadd, Code Enforcement Officer · 609-641-0663 ext. 113 · lgadd@abseconnj.org","Apply: Fees are payable before the inspection is scheduled; no minimum number of days is stated.","How to apply: Fill out the Application for a Certificate of Continued Occupancy (Code Enforcement page, Documents) and submit it with the fee to the Construction & Code Enforcement Office, 500 Mill Road, Absecon, NJ 08201. Fees are non-refundable and must be paid before the inspection is scheduled. Also file the Certification for Resale (smoke/CO/extinguisher) form.","Valid for: The application expires six months from the date received.","Inspection for compliance with the City property maintenance code (Chapter 266; the form cites the 1990 BOCA Property Maintenance Code)","Smoke alarms on every level (basement, first and second floors) and outside each separate sleeping area","Carbon monoxide alarms by every separate sleeping area","Portable fire extinguisher within 10 feet of the kitchen, in the exit path, visible, top no more than 5 feet above the floor, mounted on the maker's hanger or bracket","Extinguisher at least 2A:10B:C and no more than 10 lb, with owner's manual or instructions","Extinguisher serviced and tagged by a DCA-certified contractor within the past 12 months, or a recent purchase receipt"]$j$::jsonb, $j$[{"label":"CCO inspection, single-family residence (includes initial inspection and one re-inspection)","amount":"$75"},{"label":"Each additional re-inspection, starting with the third inspection (payable before scheduling)","amount":"$35"},{"label":"Certification of Smoke Alarm, CO Alarm and Portable Fire Extinguisher Compliance (1-2 family)","amount":"$75"}]$j$::jsonb, $t$https://abseconnj.gov/wp-content/uploads/2026/06/Certificate-of-Continued-Occupancy-Application.pdf$t$, $t$https://abseconnj.gov/code-enforcement/$t$, $j$[{"url":"https://abseconnj.gov/code-enforcement/","label":"Official source (abseconnj.gov)"},{"url":"https://abseconnj.gov/wp-content/uploads/2026/06/Certificate-of-Continued-Occupancy-Application.pdf","label":"Official source (abseconnj.gov)"},{"url":"https://abseconnj.gov/construction/","label":"Official source (abseconnj.gov)"},{"url":"https://abseconnj.gov/wp-content/uploads/2026/06/Certification-for-Resale.pdf","label":"Official source (abseconnj.gov)"}]$j$::jsonb, $t$Chapter 160 of the Code of Absecon requires all properties having a change in owner, tenant or occupant receive a certificate of continuing occupancy stating the property is in compliance with the Chapter 266, property maintenance code. Residential properties must also comply with N.J.A.C.5:70-2.3 for smoke alarms, co alarms and fire extinguisher.$t$, $t$2dc6af9c6dd3c94b1e51609de431e80a7df4972a5adfedc4ab254f6be2480c43$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":13,"q_ok":3,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/0101.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0101.json$t$, true),
  ($t$0101$t$, $t$Absecon$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Absecon Construction & Code Enforcement Office (resale smoke/CO/extinguisher certification) (town fire bureau)","Contact: Leigh Gadd, Code Enforcement Officer · 609-641-0663 ext. 113 · lgadd@abseconnj.org","How to apply: Complete the Certification for Resale form (owner or authorized representative inspects and certifies), have it notarized, give the email address the certificate should go to, and submit it with the $75 fee to the City of Absecon Municipal Complex, 500 Mill Road (Code Enforcement, ext. 113).","Fire official in the NJ state directory, updated 2/6/2026: Tom Flynn · (609) 646-7382 · tflynn@abseconnj.org","Owner self-certification, signed before a notary, on the City's Certification for Resale form","Built 1978 and before: 10-year sealed battery smoke alarms on each level and outside each sleeping area","Built 1979 to 1987: AC-powered alarms near each sleeping area and in the basement, plus 10-year sealed battery alarms on each other level","Built 1987 to 1991: AC-powered, interconnected alarms on each level and outside each sleeping area","Built 1991 to present: AC-powered interconnected alarms with battery backup in all bedrooms, outside each sleeping area and on every level","Carbon monoxide alarm near the sleeping area(s), UL 2034 listed","Portable fire extinguisher, 2.5 to 10 lb ABC dry chemical, within 10 feet of the kitchen, mounted no higher than 5 feet and visible (2020 form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certification of Smoke Alarm, CO Alarm and Portable Fire Extinguisher Compliance (1-2 family)","amount":"$75"}]$j$::jsonb, $t$https://abseconnj.gov/wp-content/uploads/2026/06/Certification-for-Resale.pdf$t$, $t$https://abseconnj.gov/code-enforcement/$t$, $j$[{"url":"https://abseconnj.gov/wp-content/uploads/2026/06/Certification-for-Resale.pdf","label":"Official source (abseconnj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://abseconnj.gov/fire-prevention/","label":"Official source (abseconnj.gov)"}]$j$::jsonb, $t$Application for One and Two Family Dwelling Certification of Smoke Alarm, Carbon Monoxide Alarm and Portable Fire Extinguisher Compliance$t$, $t$86d584f0c99bad10c1ca91c8034df8b4c9628c3927ae4594115af25b49321600$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":13,"q_ok":3,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/0101.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0101.json$t$, true),
  ($t$0107$t$, $t$Egg Harbor City$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Occupancy Transfer Certificate (Occupancy Transfer Inspection)$t$, $j$["Issued by: Egg Harbor City Code Enforcement Officer (applications go to the City Construction Office / Building Department)","Contact: Donna Heffley, Land Use and Building Department Office Manager · 609-965-1616 · donnah@eggharborcity.org","How to apply: Download the Occupancy Transfer Inspection Form from Forms & Documents, mark it SALE, and submit it with the Smoke and Carbon Monoxide Alarm Certificate Application to the Egg Harbor City Construction Office, 500 London Ave., Egg Harbor City, NJ 08215 ($75.00 per unit). Pay with exact cash, money order or check made out to City of Egg Harbor City, or online through the City's WIPP portal (2.95% fee).","Occupancy transfer certificate needed before a dwelling is sold, transferred or rented (City Code Section 213-6H, PM-107.6)","Inspection covers cleanliness, walls and ceilings, doors and hardware, windows, storm windows and screens, exterior paint and maintenance, a visual roof check, basement, kitchen, bathrooms, smoke detectors, carbon monoxide detector, electrical outlets, switches, covers and fuse box cover, sidewalks, lawn, shrubs and trees, maximum bedroom occupancy and all City code, zoning and planning ordinances","Submit the Smoke and Carbon Monoxide Alarm Certificate Application together with the Occupancy Transfer Inspection form","Form asks for owner, purchaser, tenant and lock box details and the building type, bedrooms, heat, sewer/septic and water/well"]$j$::jsonb, $j$[{"label":"Occupancy transfer certificate inspection, per dwelling unit (covers the first inspection and one follow-up)","amount":"$75"},{"label":"Each additional inspection after one follow-up","amount":"$25"}]$j$::jsonb, $t$https://app.membershipware.com/api/blob/viewBlob?rf=t&i=rw1asl38m%252BrXS5Vw72pTaPeCCtbucN6tPpPtqA%2FZ3wOk67lJc0pLvULrgKxm9TvE$t$, $t$https://www.eggharborcity.org/building$t$, $j$[{"url":"https://ecode360.com/8035021","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/8032087","label":"Official source (ecode360.com)"},{"url":"https://app.membershipware.com/api/blob/viewBlob?rf=t&i=rw1asl38m%252BrXS5Vw72pTaPeCCtbucN6tPpPtqA%2FZ3wOk67lJc0pLvULrgKxm9TvE","label":"Official source (app.membershipware.com)"},{"url":"https://app.membershipware.com/api/public/mwjsResources?tn=eggharborcityorg&et=DsEBpLP32xQDf9SDjaU%252BKg%3d%3d&pi=TToDIgI7usSeZfigcPBGFg%3d%3d&eb=KpjeAhPgzh3BNBSf%252BZdFBg%3d%3d&tg=YihSMzUNwfZ0WRShR9VMgw%3d%3d&xtg=","label":"Official source (app.membershipware.com)"},{"url":"https://app.membershipware.com/api/public/mwjsPeople?et=DsEBpLP32xQDf9SDjaU%252BKg%3d%3d&eb=u32SQFY7Pxg4KbW4ofECYQ%3d%3d","label":"Official source (app.membershipware.com)"}]$j$::jsonb, $t$No owner or leaseholder or his agent shall rent, sell, transfer, grant, lease, let, mortgage with right of occupancy or otherwise dispose of the ownership or occupancy$t$, $t$fdfee297e4ecfd57c94748945d7f5d190c5ce6352e10a159999d484c73fe97bc$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":4,"fee_bad":0,"fee_unchecked":2,"quotes":15,"q_ok":10,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0107.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0107.json$t$, true),
  ($t$0107$t$, $t$Egg Harbor City$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Egg Harbor City Fire Official (Fire Marshal), Fire Prevention (town fire bureau)","Contact: Stephen Buchhofer, Fire Marshal (also Construction Official and Electric, Plumbing, Fire & Mechanical Subcode Official) · 609-965-0081 · EHCFirePrevention@eggharborcity.org","Apply: Fee depends on how many days before the Certificate of Occupancy must be issued: more than 10 days, 4 to 10 days, or fewer than 4 days. Inspections are available Tuesdays and Thursdays from 2 to 6 pm.","How to apply: Fill out the Smoke and Carbon Monoxide Alarm Certificate Application (Forms & Documents) and submit it with the Occupancy Transfer Inspection form to the City, 500 London Ave., Egg Harbor City, NJ 08215. Questions: EHCFirePrevention@eggharborcity.org. After a failed reinspection the process starts over with a new fee.","Fire official in the NJ state directory, updated 1/27/2026: Stephen Buchhofer · (856) 656-5456 · swb6203@comcast.net","10-year sealed battery smoke alarm in every bedroom (depending on construction year)","Basement smoke alarm at the bottom of the stairwell at ceiling level (not between joists)","Hallway smoke alarms within 10 feet of all bedroom doors","Electric smoke alarms required by the building code cannot be replaced with battery alarms","Smoke detectors at least 3 feet from ceiling fan blade tips and air ducts; none in kitchens, bathrooms, dead air space, crawl spaces or attics","CO alarm in the hallway within 10 feet of all bedrooms; not plugged into a switched outlet","Fire extinguisher: residential 2A:10B:C, no larger than 10 lb, mounted within 10 feet of the kitchen (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO inspection, requested more than 10 days before the certificate is needed (per unit)","amount":"$55"},{"label":"Smoke/CO inspection, requested 4 to 10 days before the certificate is needed (per unit)","amount":"$90"},{"label":"Smoke/CO inspection, requested fewer than 4 days before the certificate is needed (per unit)","amount":"$160"},{"label":"First reinspection when more than one follow-up inspection is needed","amount":"$50"}]$j$::jsonb, $t$https://app.membershipware.com/api/blob/viewBlob?rf=t&i=mTuJlzExhzyqK3vbZ8XeAem7FEXaIzBDyP97NWQK82S%2FQ20zdH6b2vNSD%252BZxqSv7$t$, $t$https://www.eggharborcity.org/building$t$, $j$[{"url":"https://app.membershipware.com/api/blob/viewBlob?rf=t&i=mTuJlzExhzyqK3vbZ8XeAem7FEXaIzBDyP97NWQK82S%2FQ20zdH6b2vNSD%252BZxqSv7","label":"Official source (app.membershipware.com)"},{"url":"https://app.membershipware.com/api/public/mwjsPeople?et=DsEBpLP32xQDf9SDjaU%252BKg%3d%3d&eb=u32SQFY7Pxg4KbW4ofECYQ%3d%3d","label":"Official source (app.membershipware.com)"},{"url":"https://www.eggharborcity.org/building","label":"Official source (eggharborcity.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Thereafter, the inspection process shall be considered to have recommenced with the fees of $55, $90, or $160 due depending upon the timing of the application as outlined above.$t$, $t$530bdfddf9ff9e4d76f775d78abf9d18dcc88a3536993dea6c289836684a5a9a$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":4,"fee_bad":0,"fee_unchecked":2,"quotes":15,"q_ok":10,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0107.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0107.json$t$, true),
  ($t$0117$t$, $t$Mullica Township$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale Certificate (Maintenance Code certificate)$t$, $j$["Issued by: Mullica Township Zoning and Code Enforcement Office (Code Officer)","Contact: Steven Hadley, Zoning Officer / Code Enforcement Official · 609-561-7070 x 133 · zoning@mullicatownship.org","Apply: The Township code says the certificate is granted or denied within 10 days of the application.","How to apply: Download the Resale Certificate Application from the Township Forms page ('RESALE APPLICATION'). Fill in block, lot, zone, property address, lock box number and location, homeowner, buyer and realtor details, and return it with the $75.00 fee (cash or check), a copy of approved well and septic testing and, in a flood zone, the elevation certificate. The form does not say whether to mail, email or drop it off, so ask the office (609-561-7070 x 133, zoning@mullicatownship.org). The Township then schedules the inspection. Office hours are Tuesday, Wednesday and Thursday, 8:30 am to 4 pm; an appointment is recommended. The certificate is granted or denied within 10 days of the application.","Township inspection; the certificate is marked passed or failed (inspection checklist not published)","Certificate shows the building and premises comply with all Township ordinances (Chapter 177 Property Maintenance, Section 177-12)","Copy of approved well and septic testing submitted with the application","Copy of the elevation certificate if the home is in a flood zone","A conditional certificate is possible if the buyer acknowledges the violations noted by the Code Officer and agrees to fix them within 90 days of the sale (extensions of 90 more days if work is in progress)","Also: Well and septic test results: A copy of approved well and septic testing is needed to process the resale certificate.","Also: Flood zone elevation certificate: A copy of the elevation certificate is needed if the home is in a flood zone.","Also: Construction permits: Since February 9, 2026 the Uniform Construction Code in Mullica is enforced by the NJ DCA Southern Regional Office (DCA SRO contact 609 567-3653), so open construction permits are handled there."]$j$::jsonb, $j$[{"label":"Resale certificate application","amount":"$75.00"},{"label":"Certificate issued on another reliable agency's preoccupancy inspection (Township code)","amount":"$25"}]$j$::jsonb, $t$https://mullicatownship.org/wp-content/uploads/2026/03/RESALE-certificate-application-NEW.pdf$t$, $t$https://www.mullicatownship.org/departments/development-housing/code-enforcement/$t$, $j$[{"url":"https://mullicatownship.org/wp-content/uploads/2026/03/RESALE-certificate-application-NEW.pdf","label":"Official source (mullicatownship.org)"},{"url":"https://www.mullicatownship.org/forms/","label":"Official source (mullicatownship.org)"},{"url":"https://www.mullicatownship.org/departments/development-housing/code-enforcement/","label":"Official source (mullicatownship.org)"},{"url":"https://ecode360.com/9424366","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$RESALE CERTIFICATE APPLICATION$t$, $t$55edcb27e0a27aafcbb2dc3b8b79cf77094027712cc4dbd77d5b26d145626147$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":3,"fee_bad":0,"fee_unchecked":2,"quotes":19,"q_ok":9,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/0117.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0117.json$t$, true),
  ($t$0117$t$, $t$Mullica Township$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (NJ DCA, state)","Contact: Louis Kilmer, Bureau Chief, Bureau of Fire Code Enforcement · 609-633-6106","Apply: More than 10 business days before the change of occupant for the lowest fee","How to apply: Apply online through the NJ DCA Fire Safety service portal ('Start Your Smoke Certification Application'), choosing change of ownership, the closing date and the property location, and pay online. For questions call the Bureau of Fire Code Enforcement at (609) 633-6106.","Fire official in the NJ state directory (NJ DCA, state), updated 2/6/2026: Louis Kilmer · (609)633-6132","State certificate of smoke alarm and carbon monoxide alarm compliance from NJ DCA (state-enforced town)","Smoke alarms and carbon monoxide alarms as required by N.J.A.C. 5:70-4.19; the portable fire extinguisher was dropped from the sale certificate by P.L.2025, c.19","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received more than 10 business days before the change of occupant","amount":"$45.00"},{"label":"Request received 4 to 10 business days before the change of occupant","amount":"$90.00"},{"label":"Request received fewer than 4 business days before the change of occupant","amount":"$161.00"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/offices/bfce.shtml","label":"Official source (nj.gov)"},{"url":"https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/codes/regulations/r.2018%20d.074%20(50%20n.j.r.%20729(a)).pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$S Mullica Township$t$, $t$a71da176049143bd0a8f421c758b65b192fdc1064281dec70b5156c88b877f7d$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":3,"fee_bad":0,"fee_unchecked":2,"quotes":19,"q_ok":9,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/0117.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0117.json$t$, true),
  ($t$0301$t$, $t$Bass River Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale / Rental Inspection (Rental/Resale Application)$t$, $j$["Issued by: Tuckerton Borough Construction and Code Enforcement Office, serving Bass River under an interlocal service agreement","Contact: Joseph Ventresca, Housing Official / Code Enforcement Officer (Tuckerton Borough) · 609-296-4916 · LCranmer@TuckertonBorough.com","How to apply: Download the Resale - Rental Application from the Bass River Forms page, check Resale Inspection, and submit it with payment (cash, check or money order) to the Tuckerton Borough Construction Office, 420 East Main Street, Tuckerton, NJ 08087. Inspections are done on Fridays only. Attach any required certifications (well water, chimney, woodstove, fireplace, heat and hot water, elevation, lead paint).","Yard free of debris and weeds, sheds empty; waterfront lots need bulkhead in good condition","Home clean and move-in ready, trash and hazardous material removed; paint, flooring, siding, roof, windows and screens in good condition","Attached garage walls and attic ceilings finished with 1/2 inch drywall (two layers of Type X under living space); rated doors","Stairs with graspable handrails and closed risers; decks and landings 30 inches or more above grade need 36 inch guardrails with openings under 4 inches","Smoke alarms to code (see fire certificate) and carbon monoxide alarm within 10 feet of all bedrooms","Anti-tip device on the range","Electrical: no exposed wires, panel labeled, all boxes covered","Water heater relief valve piped to within 6 inches of the floor; heating equipment properly vented","House numbers at least 4 inches near the front door (not on the door), contrasting","Well water test by the Board of Health if on well water","Flood elevation certificate in special flood hazard areas","Chimney caps on all fireplaces","Certificates by professionals for chimneys, woodstoves, fireplaces, heat and hot water systems, elevation, bulkhead, and lead paint for homes built before 1978","Portable fire extinguisher, minimum 2A:10BC, 2.5 to 10 lb dry chemical, within 10 feet of the kitchen (still listed on the May 2026 form)","Also: Well water test: The form says a well water test must be completed by the Board of Health for homes on well water.","Also: Professional certifications: Attach certifications for well and septic, chimneys, woodstoves, fireplaces, heat and hot water systems, elevation, and lead paint if the home was built before 1978.","Also: Rental certificate of occupancy (rentals only): Rental units need a township certificate of occupancy before each new occupancy, applied for through the municipal clerk (Chapter 5.16). Not a resale requirement."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://bassriver-nj.org/site_files/Forms/Property_Resale_Rental_Application.pdf$t$, $t$https://bassriver-nj.org/offices/$t$, $j$[{"url":"https://bassriver-nj.org/offices/","label":"Official source (bassriver-nj.org)"},{"url":"https://bassriver-nj.org/forms/","label":"Official source (bassriver-nj.org)"},{"url":"https://bassriver-nj.org/site_files/Forms/Property_Resale_Rental_Application.pdf","label":"Official source (bassriver-nj.org)"},{"url":"https://tuckertonborough.com/government/departments/construction-and-code-enforcement/","label":"Official source (tuckertonborough.com)"},{"url":"https://bassriver-nj.org/site_files/Commission/Agenda_Minutes/2023/february_6_2023_minutes.pdf","label":"Official source (bassriver-nj.org)"}]$j$::jsonb, $t$The Township of Bass River has an Interlocal Service Agreement with Tuckerton Borough for building, electrical, and plumbing services. All three services are coordinated through the Tuckerton Borough Construction Office located in the Administrative Building, 420 East Main Street Tuckerton, New Jersey 08087.$t$, $t$9f3fedc507de7061357d85c0ed8f8b30101e7b919f9a7bdf81d048159bd9e4c3$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":18,"q_ok":11,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0301.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0301.json$t$, true),
  ($t$0301$t$, $t$Bass River Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Tuckerton Borough Fire Prevention / Construction and Code Enforcement Office (for Bass River under interlocal agreement) (town fire bureau)","Contact: Joseph Ventresca, Housing Official / Code Enforcement Officer (Tuckerton Borough) · 609-296-4916 · LCranmer@TuckertonBorough.com","Apply: Fee depends on how soon the inspection is needed: more than 10 business days, 4 to 10 business days, or 1 to 4 business days after the application is received.","How to apply: Use the Resale - Rental Application on Bass River's Forms page. Submit it with the non-refundable fee (cash, check or money order only) to the Tuckerton Borough Construction Office, 420 East Main Street, Tuckerton, NJ 08087. Inspections are done on Fridays only.","Fire official in the NJ state directory (NJ DCA, state), updated 5/18/2026: Louis Kilmer · (609)633-6132","Ten-year sealed battery smoke alarms required where alarms are battery powered (effective January 1, 2019); hardwired alarms from original construction must stay hardwired","Smoke alarm rules by year built (1978 and before, 1979-1981, 1981-1987, 1987-1991, 1991 to present), with hardwired and interconnected alarms required for newer homes","Carbon monoxide alarm within 10 feet of the sleeping areas","Portable fire extinguisher, minimum 2A:10BC, 2.5 to 10 lb dry chemical, within 10 feet of the kitchen (form dated May 2026 still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO/extinguisher certificate, inspection more than 10 business days after application","amount":"$75.00"},{"label":"Smoke/CO/extinguisher certificate, inspection 4 to 10 business days after application","amount":"$150.00"},{"label":"Smoke/CO/extinguisher certificate, inspection 1 to 4 business days after application","amount":"$225.00"}]$j$::jsonb, $t$https://bassriver-nj.org/site_files/Forms/Property_Resale_Rental_Application.pdf$t$, $t$https://tuckertonborough.com/government/departments/construction-and-code-enforcement/$t$, $j$[{"url":"https://bassriver-nj.org/site_files/Forms/Property_Resale_Rental_Application.pdf","label":"Official source (bassriver-nj.org)"},{"url":"https://bassriver-nj.org/site_files/Commission/Agenda_Minutes/2023/february_6_2023_minutes.pdf","label":"Official source (bassriver-nj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Certification of smoke detector, carbon monoxide alarm and portable fire extinguisher compliance.$t$, $t$1d781f94a421834f9b180122390e24c8f681474aa55de331d0bb260a5bdba714$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":18,"q_ok":11,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0301.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0301.json$t$, true),
  ($t$0303$t$, $t$Bordentown City$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy / Certificate of Approval (Change of Occupancy housing inspection)$t$, $j$["Issued by: City of Bordentown Department of Housing, Zoning & Code Enforcement (Housing Inspector)","Contact: Charles Latini, Housing/Code Enforcement · 609-298-0604 · planning@cityofbordentown.com","Apply: Apply at least 14 days but not more than 30 days before the change in occupancy; the FAQ says allow at least 2 weeks to get the first inspection appointment.","How to apply: Fill out the Change of Occupancy Application (Certificate of Occupancy Application in the city's Application & Forms folder), pay the fee, and send it to the Department of Housing, Zoning & Code Enforcement, 101 E. Park Street, Bordentown, NJ 08505 (planning@cityofbordentown.com). The next available inspection is scheduled once the form is filed and paid. Vacant homes can use a lock box; otherwise someone 18 or older must let the inspector in.","Valid for: Until the next change in ownership or occupancy (City Code 124-1B(6)); no temporary certificates are issued","Smoke alarms on every level and outside each sleeping area; replace alarms older than 10 years; battery units must be 10-year sealed","Carbon monoxide alarm near the bedrooms if there are fuel-burning appliances or an attached garage","Fire extinguisher at least 2A:10B:C (see fire certificate details)","Electrical: 100-amp minimum service, outlets grounded with cover plates, GFI outlets in bathrooms, panel door and no open slots","Plumbing: no leaks, J-bend sink drains, water heater relief pipe to 6 inches above floor, hot water 120 to 140 degrees F, backflow devices, water meter installed","Sump pump works and opening is covered","Floors, walls and ceilings sound and free of holes, trip hazards and peeling paint","Kitchen: stove, oven and broiler work; anti-tip bracket on range; cabinets intact","Windows open, stay open, lock and have intact screens; doors latch, exterior and bathroom doors lock","Graspable handrails on 3 or more steps; porch and deck railings with openings no more than 4 inches","Roofing certification if there are signs of active leaks; Level II chimney certification for wood stoves or wood fireplaces","Exterior, gutters, fences, sidewalks, driveways and patios in safe repair; trip hazards on adjacent sidewalks must be fixed","Visible structural defects fixed; yard mowed and cleared of junk and debris","Work done without permits must be permitted and inspected before the CO is issued","House number visible from the street (front and back if on an alley)","Also: Open permits: Work done without required permits must be permitted and inspected before the CO is issued. Open permits and violations can be checked with an OPRA request to the Municipal Clerk.","Also: As-is purchase: Buyer can request a 'No Occupancy' letter for closing; the application and fee, signed as-is contract and a signed buyer letter are required, and the buyer signs the letter at the Housing Inspection Office.","Also: Chimney certification: Level II chimney inspection by a qualified chimney sweep for solid fuel stoves or wood burning fireplaces.","Also: Roofing certification: Required from a licensed roofer if there is interior evidence of active leaks."]$j$::jsonb, $j$[{"label":"Resale inspection","amount":"$125.00"},{"label":"Re-inspection","amount":"$50.00"},{"label":"Rental inspection (for comparison, rentals only)","amount":"$75.00"}]$j$::jsonb, $t$https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4658/Bordentown/c744b606-0a0d-4ae2-a805-cf8ea0b38705/CO-APP.pdf?disposition=inline$t$, $t$https://www.cityofbordentown.com/documents/application-%26-forms/597539$t$, $j$[{"url":"https://ecode360.com/13169303","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/13169311","label":"Official source (ecode360.com)"},{"url":"https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4658/Bordentown/3f01d2a8-840c-4602-a4b0-7ae1e78ed4c6/Frequently_Asked_Questions.pdf?disposition=inline","label":"Official source (files-backend.assets.thrillshare.com)"},{"url":"https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4658/Bordentown/36ca67e8-58db-4c60-8e1f-68ff29cda6e2/Important_Housing_Inspection_Information.pdf?disposition=inline","label":"Official source (files-backend.assets.thrillshare.com)"},{"url":"https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4658/Bordentown/c744b606-0a0d-4ae2-a805-cf8ea0b38705/CO-APP.pdf?disposition=inline","label":"Official source (files-backend.assets.thrillshare.com)"},{"url":"https://thrillshare-cmsv2.services.thrillshare.com/api/v2/s/366850/directories?page_no=1","label":"Official source (thrillshare-cmsv2.services.thrillshare.com)"},{"url":"https://web.archive.org/web/20240620180801/https://cityofbordentown.com/wp-content/uploads/2022/10/CO-Application-rev-9-2022.pdf","label":"Official source (web.archive.org)"}]$j$::jsonb, $t$a certificate of approval shall first have been obtained from the Building Official of the City of Bordentown$t$, $t$c383a33fa1dbc8040a40a52bc1428da597ef0f1bb74bd700f2b3795546be197b$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":16,"q_ok":12,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0303.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0303.json$t$, true),
  ($t$0303$t$, $t$Bordentown City$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Bordentown Department of Housing, Zoning & Code Enforcement (smoke, CO and extinguisher checked in the city housing inspection) (town fire bureau)","Contact: Charles Latini, Housing/Code Enforcement · 609-298-0604 · planning@cityofbordentown.com","Apply: Apply 14 to 30 days before the change in occupancy","How to apply: Part of the city Change of Occupancy Application; no separate smoke certificate application was found.","Fire official in the NJ state directory (fire district), updated 7/31/2025: Mark Mezger · (609) 298-5375 · mmezger@missionfire.org","Smoke alarms must be replaced after 10 years; battery alarms must be 10-year sealed (ANSI/UL 217); hardwired alarms from original construction stay hardwired","Required alarm type depends on the year the house was built (for example 1984-1990 electric interconnected on all levels; 1992 to present electric interconnected in all bedrooms with battery backup)","Carbon monoxide alarm near the bedrooms if fuel-burning appliances or an attached garage (UL 2034)","Fire extinguisher at least 2A:10B:C, no more than 10 lb, within 10 feet of the kitchen, top no higher than 5 feet, on the maker's bracket, near an exit path","Extinguisher must be tagged by a Division of Fire Safety certified contractor within 12 months or have a recent purchase receipt; leave the owner's manual; do not remove the tamper seal","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Combined resale housing inspection including smoke/CO/extinguisher (paid once)","amount":"$125.00"},{"label":"Combined re-inspection","amount":"$50.00"}]$j$::jsonb, $t$https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4658/Bordentown/c744b606-0a0d-4ae2-a805-cf8ea0b38705/CO-APP.pdf?disposition=inline$t$, $t$https://www.cityofbordentown.com/documents/application-%26-forms/597539$t$, $j$[{"url":"https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4658/Bordentown/20494142-8d92-4c65-b53c-83e27bd9568b/Inspection_Guidelines.pdf?disposition=inline","label":"Official source (files-backend.assets.thrillshare.com)"},{"url":"https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4658/Bordentown/a24fbf43-2648-48d7-87f9-19375ba92f53/Smoke_Detector_Information.pdf?disposition=inline","label":"Official source (files-backend.assets.thrillshare.com)"},{"url":"https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4658/Bordentown/22e0f63e-a3a2-45b7-815f-23d4ef758fb7/Fire_Extinguisher_Information.pdf?disposition=inline","label":"Official source (files-backend.assets.thrillshare.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.missionfire.org/prevention.php","label":"Official source (missionfire.org)"},{"url":"https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4658/Bordentown/c744b606-0a0d-4ae2-a805-cf8ea0b38705/CO-APP.pdf?disposition=inline","label":"Official source (files-backend.assets.thrillshare.com)"}]$j$::jsonb, $t$Required in all buildings that contain fuel burning appliances or that have an attached garage.$t$, $t$8637b5f76a961c00d8756918762ab7284baabea1d6059dcd695208ae0a4c6ada$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":16,"q_ok":12,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0303.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0303.json$t$, true),
  ($t$0304$t$, $t$Bordentown Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Conformity for Resale / Change of Occupancy$t$, $j$["Issued by: Bordentown Township Construction Department (inspection by the fire district serving the block)","Contact: Reyan Frank, Technical Assistant to the Construction Official · 609-298-2800 ext. 2121 · r.frank@bordentowntownship.org","Apply: Request at least 10 business days before the change in ownership or occupancy","How to apply: Fill out page 2 (Request for Certificate of Conformity) of the fillable form, check the fire district for the property's block, and return it to the Bordentown Township Construction Department, 1 Municipal Drive, with exact cash or a check payable to Bordentown Township. The fire district then calls the contact person to schedule; the homeowner, realtor or maintenance staff must be present.","Valid for: 60 days","Smoke detectors on all floors (Township Code 274-5); battery units must be 10-year sealed","Carbon monoxide alarm within 10 feet of sleeping areas (UL 2034) if there is a fuel-burning appliance or attached garage","Portable fire extinguisher, 2A:10BC residential, no more than 10 lb, within 10 feet of the kitchen (form still lists it)","House numbers in Arabic numerals, at least 3 inches, on the front wall or porch and visible from the street (Township Code 200-7)","Open construction permits and violations must be closed first","Also: Open permits and violations: Open construction permits and violations must be closed before the Certificate of Conformity is issued."]$j$::jsonb, $j$[{"label":"Single family home, townhouse, duplex, or apartment in a single family home","amount":"$100.00"},{"label":"House resale re-inspection","amount":"$65.00"},{"label":"Apartment in an apartment complex","amount":"$80.00"},{"label":"Apartment re-inspection","amount":"$55.00"}]$j$::jsonb, $t$https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4427/Bordentown/dfb58020-382a-46f3-ab06-b2b90f5c8736/COC_RESALE__fillable_.pdf.pdf?disposition=inline$t$, $t$https://www.bordentowntownship.com/documents/departments/construction/resale-housing-%2F-change-of-occupancy-%2F-change-of-commercial-tenancy/563317$t$, $j$[{"url":"https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4427/Bordentown/dfb58020-382a-46f3-ab06-b2b90f5c8736/COC_RESALE__fillable_.pdf.pdf?disposition=inline","label":"Official source (files-backend.assets.thrillshare.com)"},{"url":"https://thrillshare-cmsv2.services.thrillshare.com/api/v2/s/339998/documents?folder_id=563317","label":"Official source (thrillshare-cmsv2.services.thrillshare.com)"},{"url":"https://web.archive.org/web/20240620031242/https://www.bordentowntownship.com/documents/departments/construction/548482","label":"Official source (web.archive.org)"},{"url":"https://thrillshare-cmsv2.services.thrillshare.com/api/v2/s/339996/directories?page_no=1","label":"Official source (thrillshare-cmsv2.services.thrillshare.com)"}]$j$::jsonb, $t$Inspection requests must be made at least TEN (10) BUSINESS DAYS prior to the change in ownership or occupancy of the dwelling.$t$, $t$de6e2b76c40a9b162c4f1d27e0f8e818f77913c4e31a8a9358fbea328bb0bfdc$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":14,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0304.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0304.json$t$, true),
  ($t$0304$t$, $t$Bordentown Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Blocks 1 through 61: issued by Bordentown Township Fire District #1 (Mission Fire Company) Fire Prevention Bureau (fire district)","Blocks 1 through 61 contact: Mark Mezger, Fire Marshal · 609-298-5375 ext. 105 · dutyfm@missionfire.org","Blocks 1 through 61, apply: 10 business days","Blocks 1 through 61, how to apply: Apply through the township Construction Department using the Certificate of Conformity form and check Fire District #1 (Mission). The district calls to schedule.","Block 62 and up: issued by Bordentown Township Fire District #2 (Derby) (fire district)","Block 62 and up contact: Scully, Captain · 609-298-8527 · inspections@btfd2.org","Block 62 and up, apply: 10 business days","Block 62 and up, how to apply: Apply through the township Construction Department using the Certificate of Conformity form and check Fire District #2 (Derby). The district calls to schedule.","Fire official in the NJ state directory (fire district), updated 3/5/2026: Mark Mezger · (609) 298-5375 · mmezger@missionfire.org","All battery smoke alarms must be 10-year sealed units; alarms on each level and outside each sleeping area; alarms need not be interconnected; hardwired alarms from original construction cannot be replaced with battery units","Smoke/CO combination units are acceptable but must have the 10-year sealed battery","Fire extinguisher at least 2A:10BC, no more than 10 lb, within 10 feet of the kitchen, top no higher than 60 inches, on the maker's bracket, near an exit path, with the owner's manual; proof of purchase accepted instead of a service tag (form created March 2024 still lists it)","House numbers at least 3 inches, Arabic numerals, contrasting and visible from the street","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Blocks 1 through 61: Combined Certificate of Conformity inspection, house (paid once, to Bordentown Township)","amount":"$100.00"},{"label":"Blocks 1 through 61: Combined re-inspection, house","amount":"$65.00"},{"label":"Block 62 and up: Combined Certificate of Conformity inspection, house (paid once, to Bordentown Township)","amount":"$100.00"},{"label":"Block 62 and up: Combined re-inspection, house","amount":"$65.00"}]$j$::jsonb, $t$https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4427/Bordentown/dfb58020-382a-46f3-ab06-b2b90f5c8736/COC_RESALE__fillable_.pdf.pdf?disposition=inline$t$, $t$https://www.missionfire.org/prevention.php$t$, $j$[{"url":"https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4427/Bordentown/dfb58020-382a-46f3-ab06-b2b90f5c8736/COC_RESALE__fillable_.pdf.pdf?disposition=inline","label":"Official source (files-backend.assets.thrillshare.com)"},{"url":"https://www.missionfire.org/prevention.php","label":"Official source (missionfire.org)"},{"url":"https://www.missionfire.org/","label":"Official source (missionfire.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.btfd2.org/contact-information.html","label":"Official source (btfd2.org)"}]$j$::jsonb, $t$FIRE DISTRICT #1 (Mission) Block 1 through 61 (609) 298-5375 ext. 105 or email dutyfm@missionfire.org$t$, $t$ad16c22b31247156a13d2115b7f2d106a2d27e2fc4b3ecc15b3a9e44e8529fd6$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":14,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0304.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0304.json$t$, true),
  ($t$0305$t$, $t$Burlington City$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale Certificate of Inspection / Housing Clear Certificate (certificate of continued occupancy)$t$, $j$["Issued by: City of Burlington Code Enforcement (Resales)","Contact: Autumn Harley, Resales, Code Enforcement · 609-386-0200 ext. 132 · Resales@burlingtonnj.us","Apply: Apply at least 30 business days before closing, as soon as the seller decides to sell. No same-day inspections.","How to apply: Once there is a buyer, the seller or agent submits the Resale Certificate of Inspection Application to resales@burlingtonnj.us (or by mail to Code Enforcement, 525 High Street) with the $100 fee. Pay online through the city's Pay Here link on the Code Enforcement page, using the property address as the reference number. Code Enforcement emails the appointment to the agent; inspections are Monday, Wednesday and Friday 9 AM to 1 PM. A lock box code is used only if the home is vacant.","Valid for: 60 days","Ten-year sealed battery smoke alarm on each level of living space, in every bedroom and in the basement","Carbon monoxide alarm within 10 feet of the sleeping areas","Fire extinguisher 2A-10B:C under 10 lb within 10 feet of the kitchen, visible, not behind a door or cabinet, top no more than 5 feet above the floor","Chimney certification for fossil fuel burning fireplaces and appliances","Handrails on 4 or more risers; guardrails on porches and decks 30 inches or more above grade","GFCI outlets within 6 feet of water; circuit breaker panel in order; no bare-wire fixtures","Ceilings, walls and floors without holes, chipped paint, severe cracks or water stains","Key locks on entry doors only","Heat, appliances, hot and cold water and toilets working; anti-tip device on range","Water heater bonding strap and relief valve pipe extended to 6 inches from the floor","Bathroom has a window or exhaust fan","Utilities on at the time of inspection","Yard free of trash, motor vehicles and debris; no exterior damage or roof leaks; code violations abated","No work without permits, no illegal apartments or illegally rented rooms","Also: Open permits: All open construction permits must be closed out with the Construction Office, and any work needing permits must pass permit inspection, before the city issues the final clear housing certificate.","Also: Permits for water heaters and HVAC: The application asks that permits be pulled and closed for all water heaters, HVAC equipment and any other work before the inspection.","Also: Chimney certification: Needed for fossil fuel burning fireplaces and appliances."]$j$::jsonb, $j$[{"label":"Resale processing and inspection","amount":"$100.00"},{"label":"Each additional re-inspection","amount":"$75.00"},{"label":"No one present / missed inspection","amount":"$100"}]$j$::jsonb, $t$https://www.burlingtonnj.us/wp-content/uploads/2026/02/Resale-Application.pdf$t$, $t$https://www.burlingtonnj.us/code-enforcement/$t$, $j$[{"url":"https://www.burlingtonnj.us/wp-content/uploads/2026/02/RESALE-PROCESS-with-Checklist-2-3-26.pdf","label":"Official source (burlingtonnj.us)"},{"url":"https://www.burlingtonnj.us/wp-content/uploads/2026/02/Resale-Application.pdf","label":"Official source (burlingtonnj.us)"},{"url":"https://www.burlingtonnj.us/code-enforcement/","label":"Official source (burlingtonnj.us)"},{"url":"https://ecode360.com/14736083","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Homes that are sold in the City of Burlington must be inspected. The seller must receive a Housing Clear Certificate before transferring ownership.$t$, $t$77ba05eeef8a12a4a19f8d0d9c076aef83ca72aacd0f40c109511db1e9e1d606$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":10,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0305.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0305.json$t$, true),
  ($t$0305$t$, $t$Burlington City$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Burlington Code Enforcement (resale inspection issues the Housing Clear Certificate and the NJ Division of Fire Safety certificate) (town fire bureau)","Contact: Autumn Harley, Resales, Code Enforcement · 609-386-0200 ext. 132 · Resales@burlingtonnj.us","Apply: At least 30 business days before closing","How to apply: Part of the city Resale Certificate of Inspection application; no separate smoke certificate application.","Fire official in the NJ state directory (town), updated 8/13/2026: Corey Towner · (609) 386-0200 · ctowner@burlingtonnj.us","Ten-year sealed battery smoke alarm on each level, in every bedroom and in the basement","Carbon monoxide alarm within 10 feet of the sleeping areas","Fire extinguisher 2A-10B:C, under 10 lb, within 10 feet of each kitchen, visible and accessible, on the maker's bracket, top no more than 5 feet above the floor (Resale Process dated February 2026 still requires it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Combined resale inspection including smoke/CO/extinguisher (paid once)","amount":"$100.00"},{"label":"Combined re-inspection","amount":"$75.00"}]$j$::jsonb, $t$https://www.burlingtonnj.us/wp-content/uploads/2026/02/Resale-Application.pdf$t$, $t$https://www.burlingtonnj.us/code-enforcement/$t$, $j$[{"url":"https://www.burlingtonnj.us/wp-content/uploads/2026/02/RESALE-PROCESS-with-Checklist-2-3-26.pdf","label":"Official source (burlingtonnj.us)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.burlingtonnj.us/division-of-fire-prevention/","label":"Official source (burlingtonnj.us)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The inspection conducted by City of Burlington is the basis for the issuance of a Housing Clear Certificate & New Jersey Division Fire Safety (NJDFS) Certificate as required by Chapter 195 -15A, City Ordinance.$t$, $t$acaa666ceb8ee3f1063c4f22caeb977f5a4c83234b5a1fe6505c51d7972217dc$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":10,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0305.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0305.json$t$, true),
  ($t$0306$t$, $t$Burlington Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (resale housing inspection)$t$, $j$["Issued by: Burlington Township Licenses & Inspections (Housing Inspector)","Contact: Anthony Trappanese, Housing Inspector/Zoning Officer/Property Maintenance Inspector · 609-239-5845 · HousingInspection@twp.burlington.nj.us","Apply: No minimum lead time published. The owner must notify Licenses and Inspections within 7 calendar days of a resale (Code 318-6); an expedited inspection within 5 days of the request costs $200.","How to apply: Fill out the Housing Inspection Request (listed as Residential CO Application on the Licenses & Inspections page) and return it to Caitlyn Bryant or Anthony Trappanese by email to HousingInspection@twp.burlington.nj.us or fax 609-239-6293. Licenses & Inspections is at 851 Old York Road.","Valid for: 60 days from issuance","Smoke detector on each level","Carbon monoxide detector in the hallway outside the bedrooms, within 10 feet of each bedroom (one per hallway on each bedroom floor)","Fire extinguisher 2A 10 BC mounted no higher than 5 feet, within 10 feet of the kitchen","All windows open, close and lock; screens on windows and patio doors without rips","Outlets grounded; GFCI outlets working near water sources","Toilets flush properly, no leaks under sinks","Oven and stove working with an anti-tilt bracket","Overflow pipe on the water heater","Heater certification and chimney certification before the CO is issued","Railings for 4 or more steps or 30 inches and above","House number on the home; exterior maintained","No active, open or unpaid permits","Also: Heater and chimney certifications: Required on single family, townhouse and condo resales before the CO is issued; they expire with the CO.","Also: Open permits: Call Licenses and Inspections (609-239-5847) to make sure there are no active, open or unpaid permits for the home."]$j$::jsonb, $j$[{"label":"Resale inspection, single family house, townhouse or condo","amount":"$100.00"},{"label":"Resale re-inspection, single family house, townhouse or condo","amount":"$50.00"},{"label":"Resale inspection, low-mod (affordable housing) unit","amount":"$50.00"},{"label":"Resale re-inspection, low-mod (affordable housing) unit","amount":"$20.00"},{"label":"Expedited inspection (within 5 days of request)","amount":"$200.00"}]$j$::jsonb, $t$https://www.twp.burlington.nj.us/filestorage/279/714/753/HousingInspectionRequestForm.pdf$t$, $t$https://www.twp.burlington.nj.us/licenses-and-inspections/$t$, $j$[{"url":"https://ecode360.com/7630306","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/7630313","label":"Official source (ecode360.com)"},{"url":"https://www.twp.burlington.nj.us/licenses-and-inspections/","label":"Official source (twp.burlington.nj.us)"},{"url":"https://www.twp.burlington.nj.us/filestorage/279/714/753/CO_Inspection_Fees.pdf","label":"Official source (twp.burlington.nj.us)"},{"url":"https://www.twp.burlington.nj.us/filestorage/279/714/753/HousingInspectionRequestForm.pdf","label":"Official source (twp.burlington.nj.us)"},{"url":"https://www.twp.burlington.nj.us/filestorage/279/714/753/HousingInspectionItems.pdf","label":"Official source (twp.burlington.nj.us)"}]$j$::jsonb, $t$The owner or occupant of a rooming, multifamily, rental or residential unit may not rent, resell or occupy such unit without a certificate of continued occupancy.$t$, $t$e65c09f48511c7b58bfc15f521938c7eecd40a816dd579dee524902b3ff03e2a$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":12,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0306.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0306.json$t$, true),
  ($t$0306$t$, $t$Burlington Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Burlington Township Licenses & Inspections (housing inspector checks smoke, CO and extinguisher in the resale inspection) (town fire bureau)","Contact: Caitlyn Bryant, Technical Assistant, Licenses & Inspections · 609-239-5846 · cbryant@twp.burlington.nj.us","How to apply: Part of the township Housing Inspection Request; no separate smoke certificate application was found.","Fire official in the NJ state directory (fire district), updated 7/22/2026: Ashley L Johnson · (609) 239-5850 · ajohnson@btfd.org","Smoke detector on each level","Carbon monoxide detectors in the bedroom hallway, within 10 feet of each bedroom","Fire extinguisher 2A 10 BC mounted in the kitchen no more than 5 feet above the floor (still listed on the township page and 2018 items sheet)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Combined resale housing inspection including smoke/CO/extinguisher, single family house, townhouse or condo (paid once)","amount":"$100.00"},{"label":"Combined re-inspection","amount":"$50.00"}]$j$::jsonb, $t$https://www.twp.burlington.nj.us/filestorage/279/714/753/HousingInspectionRequestForm.pdf$t$, $t$https://www.twp.burlington.nj.us/licenses-and-inspections/$t$, $j$[{"url":"https://www.twp.burlington.nj.us/licenses-and-inspections/","label":"Official source (twp.burlington.nj.us)"},{"url":"https://ecode360.com/7630354","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://btfd.org/fire-safety-prevention/","label":"Official source (btfd.org)"},{"url":"https://www.twp.burlington.nj.us/filestorage/279/714/753/CO_Inspection_Fees.pdf","label":"Official source (twp.burlington.nj.us)"}]$j$::jsonb, $t$The housing inspector also checks smoke detectors(one on each level), carbon monoxide detector(s) and fire extinguisher.$t$, $t$f85b9d5ab59b4ee63435226c65a284c9892615fe0d8f096f9c18d412620e3074$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":12,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0306.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0306.json$t$, true),
  ($t$0307$t$, $t$Chesterfield Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Inspection / Continued Certificate of Occupancy (Certificate of Compliance under Chapter 90), resales or rentals$t$, $j$["Issued by: Chesterfield Township Construction Office (Code Enforcement Officer, acting as Township Housing Official)","Contact: Glenn McMahon, Code Enforcement Officer · 609-298-2311 ext. 140","Apply: The Township has 10 working days after a complete application to inspect; after all repairs and certifications are in, the certificate takes 3 business days to generate, so apply well before closing.","How to apply: Submit the online Application for Certificate of Inspection (linked from the Township's Certificate Of Inspection page and Forms list), choose the sale application type, and pay the $75 fee. Then call the Construction Office at 609-298-2311 (Code Enforcement ext. 140) to request the inspection; voice mail requests are accepted. Turn in original heater/chimney certifications and the well water form if needed. Fees are payable to the Township of Chesterfield.","Physical inspection of the home; smoke and carbon monoxide detectors are tested by the Township inspector (or certification from the monitoring company if the system is monitored)","Working smoke detectors in each bedroom and smoke/carbon monoxide detectors on each floor; carbon monoxide detectors near the bedrooms","Original certifications (no copies or faxes) that the heater is operating correctly, for the heater chimney, for any wood burning fireplaces or woodstoves, and for their chimneys","Well water test by a certified testing agency if on well water; the buyer or tenant certifies they were told the results","GFI protection for outside outlets, outlets within 6 feet of the kitchen sink and bathroom/powder room outlets; three-prong outlet for the washer; no open spaces in the electrical panel","Guardrails and handrails on all stairways; halls and stairways lighted","Heater and water heater safety blow-off valve within 6 to 8 inches of the floor","Gutters, downspouts, second story window screens, broken windows, decks and porches in repair; no exposed exterior insulation","Large interior wall holes, missing tub and shower tiles and leaking faucets repaired; toilets working; no mold","No trash or rubbish on the property; house number visible on the front of the house or on the mailbox at the street","Also: Well water test: If the home is on well water, the water must be tested by a certified testing agency and the buyer must certify they were told the results.","Also: Heater and chimney certifications: Original certifications that the heater is operating correctly, for the heater chimney, and for any wood burning fireplaces or woodstoves and their chimneys are required before the certificate is issued.","Also: New owner notice: Township Code 90 says the new owner must notify the Housing Official in writing of the change in ownership within 10 days after receiving the deed (this appears in the rental registration article)."]$j$::jsonb, $j$[{"label":"Resale inspection, initial inspection plus one reinspection","amount":"$75"},{"label":"Each additional inspection after the included reinspection","amount":"$50.00"}]$j$::jsonb, $t$https://www.chesterfieldtwpnj.gov/media/5586$t$, $t$https://www.chesterfieldtwpnj.gov/construction/page/certificate-inspection$t$, $j$[{"url":"https://www.chesterfieldtwpnj.gov/construction/page/certificate-inspection","label":"Official source (chesterfieldtwpnj.gov)"},{"url":"https://ecode360.com/12288975","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/14790524","label":"Official source (ecode360.com)"},{"url":"https://www.chesterfieldtwpnj.gov/Directory","label":"Official source (chesterfieldtwpnj.gov)"},{"url":"https://www.chesterfieldtwpnj.gov/construction/page/common-violations","label":"Official source (chesterfieldtwpnj.gov)"}]$j$::jsonb, $t$Requirements For Continued Certificate Of Inspection$t$, $t$19a73a121517a6d006582f8e1fb497ddfa0d87dbcafecb8b61cbd151ac74f1b3$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":14,"q_ok":3,"q_bad":0,"q_unchecked":11},"source":"property/data/municipal-requirements/checked/0307.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0307.json$t$, true),
  ($t$0307$t$, $t$Chesterfield Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Chesterfield Township Construction Office (smoke and CO checked in the township Certificate of Inspection; NJ DCA is the fire code enforcing agency) (town fire bureau)","Contact: Glenn McMahon, Code Enforcement Officer · 609-298-2311 ext. 140","Apply: Same as the Certificate of Inspection; allow 3 business days after all requirements are met.","How to apply: Part of the Township Certificate of Inspection application; no separate smoke certificate application was found.","Fire official in the NJ state directory (NJ DCA, state), updated 6/16/2026: Louis Kilmer · (609)633-6132","Working smoke detectors in each bedroom and smoke/carbon monoxide detectors on each floor; carbon monoxide detectors in the vicinity of the bedrooms (tested by the Township inspector during the Certificate of Inspection)","Monitored systems: certification from the monitoring company that the system is operating correctly","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Combined resale Certificate of Inspection including the smoke/CO check (paid once, same fee as above)","amount":"$75"}]$j$::jsonb, $t$https://www.chesterfieldtwpnj.gov/media/5586$t$, $t$https://www.chesterfieldtwpnj.gov/construction/page/certificate-inspection$t$, $j$[{"url":"https://www.chesterfieldtwpnj.gov/construction/page/certificate-inspection","label":"Official source (chesterfieldtwpnj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Smoke detectors and carbon monoxide detectors will be tested by the Township Inspector during the physical inspection of your property, unless you have a monitored system.$t$, $t$29d117d54aa6b0807620ce9abd41eb87e59b82d2aeda51ab0c877008ae34839f$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":14,"q_ok":3,"q_bad":0,"q_unchecked":11},"source":"property/data/municipal-requirements/checked/0307.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0307.json$t$, true),
  ($t$0308$t$, $t$Cinnaminson Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Cinnaminson Township. Confirm with the office if the buyer's lender or title company asks.","Contact: 856-829-6000 ext. 2379","How to apply: No town resale CO is needed. The Township says to contact the Cinnaminson Sewerage Authority (856-829-5287) for the sewer compliance inspection and the Fire District (856-829-5220) for the smoke and CO alarm inspection.","Also: Sewer compliance inspection (Cinnaminson Sewerage Authority): All properties require a sewer compliance inspection before settlement. Call 856-829-5287 to schedule. Title companies can submit the online form to get the open balance and recommended escrow. The inspection fee is collected at the time of inspection; the amount is not published."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://cinnaminsonnj.org/office-of-community-and-economic-development/$t$, $j$[{"url":"https://cinnaminsonnj.org/office-of-community-and-economic-development/","label":"Official source (cinnaminsonnj.org)"}]$j$::jsonb, $t$Do I need a Certificate of Occupancy Inspection to sell my home? No, Cinnaminson Township does not require CO inspections for resale of a residential home. They do require an inspection from the Sewerage Authority (856)829-5287 and the Fire District (856)829-5220. Please contact them directly for scheduling and fees.$t$, $t$4d2f05917db4260826bc4d5d7d64e6a965595c2b3939968f5e0fdd507fb9c6b0$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":10,"q_ok":7,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0308.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0308.json$t$, true),
  ($t$0308$t$, $t$Cinnaminson Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Cinnaminson Fire District No. 1, Fire Marshal's Office (Bureau of Fire Prevention) (fire district)","Contact: Jesse Nickum, Fire Marshal (Lieutenant) · 856-829-5220 · jnickum@cinnaminsonfire.org","Apply: At least one week advance notice to schedule the inspection","How to apply: Submit the online Application for Home Inspection on the fire department website (property address, block and lot, seller and agent contacts, settlement date). Pay by check or money order payable to Cinnaminson Fire District, or through the district's online payment link. Give at least one week notice.","Fire official in the NJ state directory (fire district), updated 1/12/2026: Jesse Nickum · (856) 829-5220 · jnickum@cinnaminsonfire.org","Battery smoke alarms must be 10-year sealed lithium battery units","Smoke alarms cannot be older than 10 years from the manufacture date","Smoke alarms on each level and outside each sleeping area; hardwired alarms must stay hardwired with battery backup and cannot be swapped for battery units","CO alarm near all sleeping areas (within 10 feet of all bedrooms) if there are fuel burning appliances or an attached garage","The district's current forms still list a portable fire extinguisher: at least 2-A:10-B:C, no more than 10 pounds, within 10 feet of the kitchen in the path of exit, not next to the stove, mounted on the maker's bracket with the top no more than 5 feet above the floor, with the manual left for the buyer, and a service tag from a state-certified contractor within 12 months or a purchase receipt under 12 months old","House numbers visible from the street: Arabic numerals, contrasting color, at least 3 inches tall, mounted at least 30 inches above grade","Owner or representative 18 or older must be present at the inspection","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Initial inspection","amount":"$80.00"},{"label":"Re-inspection","amount":"$55.00"},{"label":"Missed appointment","amount":"$45.00"},{"label":"Senior citizen discount (ID required)","amount":"$10.00"}]$j$::jsonb, $t$https://cinnafire.org/fire-marshal/application-for-home-inspection/$t$, $t$https://cinnafire.org/fire-marshal/home-inspection-information/$t$, $j$[{"url":"https://cinnafire.org/fire-marshal/home-inspection-information/","label":"Official source (cinnafire.org)"},{"url":"https://cinnafire.org/fire-marshal/application-for-home-inspection/","label":"Official source (cinnafire.org)"},{"url":"https://cinnafire.org/cfd/staff/","label":"Official source (cinnafire.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://ecode360.com/10008685","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$The New Jersey Fire Code requires that whenever a home is being sold, or a rental unit changes occupant, that a Certificate of Smoke and Carbon Monoxide Detector Compliance be obtained from the local fire code enforcing agency, which in Cinnaminson is the Cinnaminson Fire Marshal's Office.$t$, $t$6bb840b09afd70903fbe08111b5753c23aaf3825ff58623fd72edac1f0a86083$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":10,"q_ok":7,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0308.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0308.json$t$, true),
  ($t$0309$t$, $t$Delanco Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Habitability (COH)$t$, $j$["Issued by: Delanco Township (Rental/COH Coordinator, Municipal Building)","Contact: Jessica Husband, Rental / COH Coordinator · 856-461-0561 ext. 222","Apply: No set lead time published. The applicant must schedule the inspection, and any violations must be corrected within 90 days.","How to apply: Fill out the Certificate of Habitability Application (Buying or Selling a Home) and return it with $100 cash or a check payable to Delanco Township to the Municipal Building, 770 Coopertown Rd., Delanco, NJ 08075. Then call Jessica Husband at 856-461-0561 ext. 222 to set up the inspection; the applicant must schedule it.","Valid for: 90 days or until the next change in ownership, whichever comes first","Walls and ceilings free of cracks or holes in every room","Floor coverings, windows and doors in good condition","Electrical wiring, fixtures and receptacles working; enough outlets in bedrooms","Entrance locks on front, rear and side doors cannot need a key from the inside","Kitchen counter, sink, dishwasher, exhaust and stove anti-tip device","Bathroom tile, sink, tub, toilet and ventilation fan","Handrails, guards and stairs sound","Exterior: roof, gutters and downspouts, paint, windows, foundation, siding, chimney cap","Fence and gate, lawn and landscaping kept up, no rubbish or debris","House number visible, driveway cracks and holes, front light working","Heating, electrical or plumbing certifications if the inspector asks for them","Also: Sewer inspection (Delanco Sewerage Authority): SEWER INSPECTION: $25 cash or check payable to Delanco Sewerage Authority may accompany the COH application. Call Delanco Sewer at 856-461-6876 to set up the appointment."]$j$::jsonb, $j$[{"label":"Home inspection (COH application)","amount":"$100"},{"label":"Each re-inspection after the first free one","amount":"$50"}]$j$::jsonb, $t$https://www.delancotownship.com/filestorage/5328/5330/10714/Certificate_of_Habitability_Application_REVISED_06-02-2025.pdf$t$, $t$https://www.delancotownship.com/onlineforms$t$, $j$[{"url":"https://www.delancotownship.com/filestorage/5328/5330/10714/Certificate_of_Habitability_Application_REVISED_06-02-2025.pdf","label":"Official source (delancotownship.com)"},{"url":"https://www.delancotownship.com/content/5300/7041/default.aspx","label":"Official source (delancotownship.com)"},{"url":"https://www.delancotownship.com/filestorage/5328/5330/10714/Certificate_of_Habitability_-COH-_Inspection_Guidelines.pdf","label":"Official source (delancotownship.com)"},{"url":"https://ecode360.com/10021757","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$CERTIFICATE OF HABITABILITY APPLICATION ... Buying or Selling a Home$t$, $t$aa399ca8477053a2e0238e2ec94aa256d5f979e342d1811efb54aaf85f2f04d8$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":11,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0309.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0309.json$t$, true),
  ($t$0309$t$, $t$Delanco Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Delanco Fire District No. 1, Bureau of Fire Prevention & Inspection (fire district)","Contact: Randy Johnson, Fire Official · 856-764-8176 · fm@delancofire.com","Apply: Submit the form and payment at least 10 business days before settlement. Inspections are scheduled on the first available Monday after all information and payment are received. If settlement is less than 10 business days away, email and call the Fire Official.","How to apply: Download the Application for Certification of Smoke Alarm and Carbon Monoxide Alarm Compliance, complete the self-inspection form, and mail it with a check or money order payable to Delanco Fire District #1 to Delanco Fire Official, P.O. Box 5021, Delanco, NJ 08075. Payment must be received before the inspection is scheduled.","Fire official in the NJ state directory (fire district), updated 6/16/2026: Randy Johnson · (856) 764-8176 · rjjohnson@comcast.net","All smoke and CO alarms must be less than 10 years old","All non-AC (battery) smoke alarms must be the 10-year sealed battery type","Smoke alarm type and locations depend on the year the home was built (for example, 1991 and newer: interconnected AC alarms with battery backup on each level and in each bedroom)","CO alarms near sleeping areas if the home has a fuel-burning device or attached garage","House number easily visible from the street","Homes with a secondary power source (generator, solar panels, battery storage) need printed warning labels such as 'CAUTION: MULTIPLE SOURCES OF POWER' within 18 inches of the main electrical panel and within 18 inches of the electric meter (ANSI Z535.4 label accepted); hand-written labels not allowed","Seller must complete and sign a self-inspection certification on the form before the inspection is scheduled","A separate application and fee is required for each dwelling unit on the property","The current form (August 2025) does not list a portable fire extinguisher","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, application received 10+ business days before settlement (per dwelling unit)","amount":"$45.00"}]$j$::jsonb, $t$https://www.delancofire.com/_files/ugd/6a69cf_4e8f084c80ef4ec28cc09d33bdc48ff7.pdf$t$, $t$https://www.delancofire.com/fire-marshall$t$, $j$[{"url":"https://www.delancofire.com/fire-marshall","label":"Official source (delancofire.com)"},{"url":"https://www.delancofire.com/_files/ugd/6a69cf_4e8f084c80ef4ec28cc09d33bdc48ff7.pdf","label":"Official source (delancofire.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$This includes the Residential Resale-Smoke/CO Detector Inspection.$t$, $t$d63a983404f7c5cd63b746617618a73ec2235cf92dd8e3949b849f099491dabc$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":11,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0309.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0309.json$t$, true),
  ($t$0310$t$, $t$Delran Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$verify$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not confirmed yet: Watchdog found signs that Delran Township does not require a resale certificate for sales, but no clear, current written statement. Call the office before closing.","Contact: Bill Lunemann, Construction Official · 856-461-8667 · constructioninspections@delrantownship.org","How to apply: The Township's Construction Office page tells sellers that the Fire District Office handles resale inspections; no separate township resale certificate is described. See the fire certificate section."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://delrantownship.org/construction-office/$t$, $j$[{"url":"https://delrantownship.org/construction-office/","label":"Official source (delrantownship.org)"},{"url":"https://delrantownship.org/fire-department/","label":"Official source (delrantownship.org)"},{"url":"https://ecode360.com/10024870","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Selling Your House? The Fire District Office handles inspections for resale. You will need to have your house inspected before you go to settlement;$t$, $t$8c3f165fcba34792298e34fc23bba625bc85db0f806a65958f8e8a88ce61903e$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["probably not required, but not clearly stated in writing"],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":10,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0310.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0310.json. Red flag: probably not required, but not clearly stated in writing$t$, true),
  ($t$0310$t$, $t$Delran Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Delran Township Fire District No. 1, Bureau of Fire Prevention (Local Enforcing Agency) (fire district)","Contact: Joseph Cunningham Jr., Fire Marshal / Fire Official · 856-461-5474 · LEA@delranfire.org","Apply: Apply more than 10 business days (excluding holidays) before the change of occupant for the lowest fee. Payment is due before the inspection.","How to apply: Fill out the Application for Inspection (Smoke Detector and CO Detector) and email it to LEA@delranfire.org or drop it off at the Fire District office in the Municipal Building, 900 S. Chester Avenue, Delran. Pay before the inspection by check payable to Delran Fire District #1 or online (list the inspection address as the invoice number).","Fire official in the NJ state directory (fire district), updated 3/5/2026: Joseph Cunningham, Jr · (856) 577-1077 · joseph.cunninghamjr@delranfire.org","Older homes need 10-year sealed battery smoke alarms (or AC powered alarms) on each level and outside sleeping areas","Homes built with hardwired, battery backup, interconnected alarms (for example Summer Hill, Forest Hill, Waters Edge, The Grande, the Orchard) must keep them on each level and in each bedroom, and they must be less than 10 years old","Carbon monoxide detectors must be less than 5 years old (check the manufacture or replace-by date) and installed outside each sleeping area","All smoke and CO detectors must be UL listed","House number: Arabic numerals, contrasting color, at least 3 inches tall, at least 30 inches above ground, visible from the street (Township Code Chapter 95)","The current form (February 2025) does not list a portable fire extinguisher","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received more than 10 business days before closing","amount":"$45.00"},{"label":"Request received 4 to 10 business days before closing","amount":"$90.00"},{"label":"Request received fewer than 4 business days before closing","amount":"$161.00"}]$j$::jsonb, $t$https://www.delranfire.org/content/forms/file/APPLICATION%20FOR%20SD%20INSPECTION%202025.pdf$t$, $t$https://www.delranfire.org/content/prevention$t$, $j$[{"url":"https://www.delranfire.org/content/forms/file/APPLICATION%20FOR%20SD%20INSPECTION%202025.pdf","label":"Official source (delranfire.org)"},{"url":"https://www.delranfire.org/content/prevention","label":"Official source (delranfire.org)"},{"url":"https://www.delranfire.org/content/payment","label":"Official source (delranfire.org)"},{"url":"https://delrantownship.org/fire-department/","label":"Official source (delrantownship.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$N.J. State Fire Code N.J.A.C. 5:70-2.3 requires the inspection of One & Two Family Dwellings and R-2 Occupancies for smoke detectors and carbon monoxide detectors before it is sold or leased.$t$, $t$c7ffeecb487ee0be4890790afce32d895180f93648fb07f77804ce0b24eae9ad$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["probably not required, but not clearly stated in writing"],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":10,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0310.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0310.json. Red flag: probably not required, but not clearly stated in writing$t$, true),
  ($t$0311$t$, $t$Eastampton Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO), Resale/Rental Inspection$t$, $j$["Issued by: Eastampton Township Resale/Rental Inspections office","Contact: Vincent Knott, Resale/Rental Inspector (also Danny Ernst, Resale/Rental Inspector, same number) · 609-267-5723 ext. 200","Apply: Schedule the inspection at least 5 calendar days before settlement; requests 4 calendar days or less before settlement pay the higher fee.","How to apply: Submit the online CCO Application on GovPilot (choose Resale) and pay the fee. Schedule the inspection at least 5 calendar days before settlement; requests 4 calendar days or less before settlement cost $125. Questions: Resale/Rental Inspectors at 609-267-5723 ext. 200.","House numbers: numerals at least 4 inches high, contrasting color, fixed to the house and visible from the street (mailbox or lamp post numbers not accepted)","Smoke alarm on every level, including the bottom of the basement stairs at the ceiling","Smoke alarm within 10 feet of all bedroom doors and one on the ceiling of every bedroom","Hardwired smoke alarms cannot be replaced with battery alarms","Smoke alarms under 10 years old and working; battery alarms must be 10-year sealed type","CO alarm in the hallway within 10 feet of all bedrooms, under 10 years old and working","Fire extinguisher (2019 checklist): 2A-10B:C, under 10 pounds, mounted on its bracket within 10 feet of the kitchen in the path of exit","Homes with a monitored low-voltage fire alarm system need a test certificate from an alarm contractor at the inspection","Owner certifies all structures meet zoning and no rubbish, debris or bulk trash is left before the new occupant moves in"]$j$::jsonb, $j$[{"label":"CCO inspection, more than 4 calendar days before settlement (per dwelling unit, includes one reinspection)","amount":"$75"},{"label":"CCO inspection requested 4 calendar days or less before settlement","amount":"$125"},{"label":"Each additional reinspection after the one included (Ordinance 2019-9)","amount":"$25"}]$j$::jsonb, $t$https://main.govpilot.com/web/public/f108198f-fab_CCO-Application-eastampton?uid=7272&ust=NJ&pu=1&id=0$t$, $t$https://www.eastampton.com/rental$t$, $j$[{"url":"https://www.eastampton.com/rental","label":"Official source (eastampton.com)"},{"url":"https://www.eastampton.com/rental/directory-listing/vincent-knott","label":"Official source (eastampton.com)"},{"url":"https://web.archive.org/web/20211231133235/https://www.eastampton.com/sites/default/files/fileattachments/resale/rental_inspections/page/1891/ordinance_2019-9.pdf","label":"Official source (web.archive.org)"},{"url":"https://main.govpilot.com/web/public/f108198f-fab_CCO-Application-eastampton?uid=7272&ust=NJ&pu=1&id=0","label":"Official source (main.govpilot.com)"},{"url":"https://web.archive.org/web/20211231172247/https://www.eastampton.com/sites/default/files/fileattachments/resale/rental_inspections/page/4301/inspection_checklist.pdf","label":"Official source (web.archive.org)"}]$j$::jsonb, $t$Per Ordinance 2010-4; 385-4 a Certificate of Continued Occupancy inspection is required for all property resales or rental units whenever there is a change of occupancy and/or ownership.$t$, $t$ca8479009d3c273f81b5434cf5900adb35fbdca6b2f4e93dc6e65ccd3d36829d$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":16,"q_ok":2,"q_bad":0,"q_unchecked":14},"source":"property/data/municipal-requirements/checked/0311.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0311.json$t$, true),
  ($t$0311$t$, $t$Eastampton Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Eastampton Township Local Enforcing Agency (Fire Prevention Bureau, Office of the Fire Marshal) (town fire bureau)","Contact: Yunus Boduroglu, Fire Marshal / Fire Official · 609-267-5723 ext. 203 · firemarshal@eastampton.com","How to apply: No separate resale smoke/CO certificate application or fee was found. The smoke, CO and extinguisher items are on the Township's resale CCO checklist; ask the Resale/Rental Inspector or the Fire Marshal whether the CCO inspection also issues the smoke/CO certificate.","Fire official in the NJ state directory (fire district), updated 5/18/2026: Yunus Bodugroglu · (609) 267-5723 · firemarshal@eastampton.com","The Township's CCO inspection checklist (November 2019) covers smoke alarms, CO alarms and a mounted 2A-10B:C fire extinguisher within 10 feet of the kitchen, so these are checked at the resale inspection","Smoke and CO alarms must be under 10 years old; battery smoke alarms must be 10-year sealed type","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.eastampton.com/fm$t$, $j$[{"url":"https://www.eastampton.com/fm","label":"Official source (eastampton.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://web.archive.org/web/20211231172247/https://www.eastampton.com/sites/default/files/fileattachments/resale/rental_inspections/page/4301/inspection_checklist.pdf","label":"Official source (web.archive.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The Eastampton LEA is administered by Eastampton Township, and is outside of the Fire Department command structure.$t$, $t$8f7578ec3ce0be1877a4c25dc02a8cea1966b36b482598b14011460c8a745cbe$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":16,"q_ok":2,"q_bad":0,"q_unchecked":14},"source":"property/data/municipal-requirements/checked/0311.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0311.json$t$, true),
  ($t$0312$t$, $t$Edgewater Park Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Inspection (C/I), formerly Certificate of Occupancy$t$, $j$["Issued by: Edgewater Park Township Inspections Department, Code Enforcement","Contact: Yakup Koksaldi, Code Enforcement · 609-877-2050 ext. 314 · code-enforcement@edgewaterpark-nj.com","Apply: No set lead time published. Payment must be received before the inspection is scheduled; inspections are given the next available slot. A failed resale inspection gets a Temporary C/I good for 30 days.","How to apply: Fill out the Certificate of Inspection Application Report (check Re-Sale Inspection), including seller and buyer contacts and a requested inspection date, and submit it with payment. Pay by check or money order mailed to or left in the drop box at 400 Delanco Road, Edgewater Park, NJ 08010, or in person (cash accepted). The form can also be submitted through the Township's SDL citizen portal (account required). Inspections are not scheduled until payment is received. Call 609-877-2050 ext. 314 or email code-enforcement@edgewaterpark-nj.com to reserve a time.","Valid for: Temporary C/I after a failed resale inspection: 30 days from the first inspection","All open construction permits (old or new) must be closed; work done without a permit must be permitted and inspected","Exterior walls, roof, gutters, foundation, stairs, decks, porches, fences and accessory structures sound and in good repair","House number at least 3 inches high, readable from the street","Driveways and sidewalks level with no tripping hazards; yard maintained","Guardrails on landings and porches 30 inches or higher (balusters no more than 4 inches apart)","No double-keyed deadbolts on exit doors","Pool fence with self-closing, self-latching gate (48 inches; 6 feet for in-ground pools); no stagnant pool water","All utilities on at the time of inspection","Smoke detector on each level and within 10 feet outside sleeping areas; battery units must be 10-year sealed type; existing hardwired units stay","CO detector on all levels with bedrooms","2A-10B:C fire extinguisher mounted on the wall within 10 feet of the kitchen, about 5 feet high, on the way to the exit","Stove anti-tip device; GFCI outlets at kitchen counters and bathrooms; no extension-cord wiring or open splices","No plumbing leaks; heat to all habitable rooms; water heater bonding strap and relief valve pipe to 6 inches off the floor","Electrical, plumbing, roofing or heating certification may be required at the inspector's discretion","A blue recycling cart must be on the property at the inspection","Also: Open construction permits must be closed: Any old or new outstanding construction permits must be closed before a final Certificate of Inspection is issued; unpermitted work must be permitted and inspected by the Construction Department (609-877-2217, inspections@edgewaterpark-nj.com).","Also: Blue recycling cart: A blue recycling cart must be on the premises at the time of inspection and must stay with the property.","Also: Heating system certification: At the inspector's discretion a heating system certification form may be required."]$j$::jsonb, $j$[{"label":"Resale inspection (includes 1 re-inspection)","amount":"$120.00"},{"label":"Each additional re-inspection for a temporary or expired C/O","amount":"$50.00"},{"label":"Re-inspection fee when the Temporary C/I passes its 30-day expiration or after 2 failed inspections in a row","amount":"$50"},{"label":"Emergency inspection status report within 72 hours (Township Code 240-18C; ask whether it applies to rush resale inspections)","amount":"$150"},{"label":"Emergency inspection status report within 24 hours (Township Code 240-18D; ask whether it applies to rush resale inspections)","amount":"$200"}]$j$::jsonb, $t$https://www.edgewaterpark-nj.com/filestorage/173/360/430/432/Certificate_of_Occupancy_Form.pdf$t$, $t$https://www.edgewaterpark-nj.com/content/163/338/4749.aspx$t$, $j$[{"url":"https://www.edgewaterpark-nj.com/content/163/338/4749.aspx","label":"Official source (edgewaterpark-nj.com)"},{"url":"https://www.edgewaterpark-nj.com/filestorage/173/360/430/432/Certificate_of_Occupancy_Form.pdf","label":"Official source (edgewaterpark-nj.com)"},{"url":"https://www.edgewaterpark-nj.com/content/163/338/default.aspx","label":"Official source (edgewaterpark-nj.com)"},{"url":"https://ecode360.com/33437489","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$is always required when selling or purchasing a property in Edgewater Park Township (this includes purchasing a bank owned/foreclosed parcel), and when a property is to be rented out.$t$, $t$072230c675ff2d134bfe95e514cbea0fd7405c6549b6cecff026df8a5ae065d6$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":3,"fee_bad":0,"fee_unchecked":2,"quotes":15,"q_ok":12,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0312.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0312.json$t$, true),
  ($t$0312$t$, $t$Edgewater Park Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Edgewater Park Township Fire District No. 1 (Fire Official / Bureau of Fire Safety) (fire district)","Contact: Matt Augustino, Fire Official · 609-877-8812 · epfdfi14@gmail.com","How to apply: No resale smoke/CO certificate application or fee is posted on the Township or fire district pages. Call the Fire Official's office at 609-877-8812 to request the certificate and confirm the fee.","The Township's resale C/I checklist also covers smoke detectors on each level (10-year sealed battery type if battery powered), CO detectors on levels with bedrooms, and a wall-mounted 2A-10B:C extinguisher within 10 feet of the kitchen (form dated September 2026, after P.L.2025, c.19)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.edgewaterpark-nj.com/content/161/330/907/default.aspx$t$, $j$[{"url":"https://www.edgewaterpark-nj.com/content/161/330/907/default.aspx","label":"Official source (edgewaterpark-nj.com)"},{"url":"https://www.edgewaterpark-nj.com/filestorage/161/330/907/Beverly-EP_Smoke-Detectors_revised.pdf","label":"Official source (edgewaterpark-nj.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The Township has one Fire District, with its own publicly elected Board of Fire Commissioners. The Fire Commissioners are the legal governing body of the Fire Companies, the Bureau of Fire Safety, and the Training Center.$t$, $t$0d4927d430aadb192c90f1a8d917ce011e071406906e2889e4b04f24750e0a5f$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":3,"fee_bad":0,"fee_unchecked":2,"quotes":15,"q_ok":12,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0312.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0312.json$t$, true),
  ($t$0313$t$, $t$Evesham Township (Marlton)$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Evesham Township (Marlton). Confirm with the office if the buyer's lender or title company asks.","Contact: 856-983-2914","How to apply: No township resale CO or CCO. The Township says all home resales and rentals must get an inspection from the fire department (Evesham Fire-Rescue); see the fire certificate section."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://evesham-nj.org/departments/construction$t$, $j$[{"url":"https://evesham-nj.org/construction-page-list/791-construction-faq","label":"Official source (evesham-nj.org)"},{"url":"https://evesham-nj.org/departments/construction","label":"Official source (evesham-nj.org)"}]$j$::jsonb, $t$What if I am selling my house? Is an inspection required? The Township of Evesham does not currently inspect existing residential homes for Certificate of Occupancy or Continuing Certificate of Occupancy. All home resales and rentals are required to obtain an inspection from the Township fire department.$t$, $t$80546f4e4427c39bd2ccb080a72da6a36c5d6de62710fdf443e33bcf1951b5e3$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":9,"q_ok":8,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0313.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0313.json$t$, true),
  ($t$0313$t$, $t$Evesham Township (Marlton)$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Evesham Township Fire District No. 1 (Evesham Fire-Rescue), Division of Fire Prevention (fire district)","Contact: Scott Freedman, Deputy Chief, Fire Marshal / Fire Official / Fire Subcode Official · 856-983-2750 · sfreedman@eveshamfire.org","Apply: Apply more than 10 business days before the change of occupant for the lowest fee. Inspections are given a block of time; missing it requires a new non-refundable application fee.","How to apply: Start the online Smoke/CO Certificate application on the fire district's Muniverse portal (linked from the Home Smoke/CO Alarm Inspections page). All fees are non-refundable. Questions: Fire Prevention Office, 984 Tuckerton Road, Suite 205, Marlton (Municipal Building 2nd floor), 856-983-2750, open Monday to Thursday 7:30 a.m. to 5:30 p.m. Short sales and foreclosures: call the Division of Fire Prevention to schedule.","Fire official in the NJ state directory (fire district), updated 3/5/2026: Scott L Freedman · (856) 983-2750 · sfreedman@eveshamfire.org","Smoke alarm type and locations depend on the year the home was built (before 1977: 10-year sealed battery alarm on each level including basement; 1992 to present: interconnected hardwired alarms with battery backup in all bedrooms, near bedrooms and on all levels)","Hardwired smoke alarms older than 10 years must be replaced with new hardwired alarms with battery backup","All smoke alarms must be less than 10 years old; if no date is stamped, replace the alarm","Each level needs an AC (hardwired) or 10-year sealed battery smoke alarm; hardwired alarms must be interconnected","CO alarm outside and near all sleeping areas if the home has a fuel-burning appliance, fireplace or garage","House numbers: 3-inch Arabic numerals, contrasting color, at least 30 inches off the ground, visible from the street","Low-voltage fire alarm systems must be tested and approved by an alarm contractor before the inspection; give the certificate to the inspector","Homes with residential fire sprinklers need a licensed sprinkler contractor inspection within 30 days before the fire inspection","Portable fire extinguisher is required for RENTALS ONLY (2A:10BC, kitchen, visible, mounted no higher than 5 feet, tagged within 12 months or new with receipt); not required for sales","No change of ownership or occupancy before a successful inspection and certificate; violators face a $500 penalty per occurrence","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received more than 10 business days before the change of occupant","amount":"$70"},{"label":"Request received 4 to 10 business days before the change of occupant","amount":"$115"},{"label":"Request received fewer than 4 business days before the change of occupant","amount":"$160"},{"label":"Each required re-inspection (a third visit needs a new application and fee)","amount":"$35"}]$j$::jsonb, $t$https://geo.muniverse.us/prod1/portal/portal.jsp?c=596833708&p=557152673&g=557273727$t$, $t$https://eveshamfire.org/inspections-forms/smoke-alarm-certficate/$t$, $j$[{"url":"https://eveshamfire.org/inspections-forms/smoke-alarm-certficate/","label":"Official source (eveshamfire.org)"},{"url":"https://geo.muniverse.us/prod1/portal/portal.jsp?c=596833708&p=557152673&g=557273727","label":"Official source (geo.muniverse.us)"},{"url":"https://eveshamfire.org/facilities/fire-administration-fire-prevention-office/","label":"Official source (eveshamfire.org)"},{"url":"https://eveshamfire.org/organization/contact/","label":"Official source (eveshamfire.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Any change of ownership or occupancy/tenancy may not occur prior to a successful inspection and possession of a CSACMAPFEC Certification. Changes without this inspection will result in a $500 penalty per occurrence (N.J.S.A 52:27D-198.3).$t$, $t$d91184c577585350d70dcb57de0f88db81bd5a6d35989efc77723a1a0a186a55$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":9,"q_ok":8,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0313.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0313.json$t$, true),
  ($t$0315$t$, $t$Florence Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Continued Certificate of Occupancy (CCO), Residential Change of Tenant/Occupancy/Ownership inspection$t$, $j$["Issued by: Florence Township Housing Department (Construction and Code Enforcement)","Contact: Michael Perna, Housing Inspector · 609-499-2130 ext. 124 · housing@florence-nj.gov","Apply: Allow at least 2 weeks to get the first inspection appointment; in busy times it can be up to 4 weeks out.","How to apply: Fill out page 1 of the Housing Inspection Application form (check Buyer, give owner and buyer contact details) and submit it with the fee to the Florence Township Housing Department, 711 Broad Street, Florence. The inspection is booked for the next open slot once the form is complete and paid. A lock box is allowed for vacant homes; otherwise an adult must let the inspector in. Give at least 24 hours notice to cancel or reschedule. For an as-is sale where the buyer will not move in, ask for a notarized \"No Occupancy\" letter (needs the paid application, the as-is contract and a signed buyer letter).","Smoke alarms on every level and outside each sleeping area; replace alarms older than 10 years; battery units must be 10-year sealed (UL 217)","Carbon monoxide alarm near the bedrooms if the home has fuel-burning appliances or an attached garage","Portable fire extinguisher (Township Code 116-4.B(1)(d)), see fire certificate section","Electrical: 100 amp minimum service, grounded outlets with cover plates, GFI outlets in bathrooms, panel door with no open slots","Plumbing: no leaks, J-bend sink drains, water heater relief pipe to 6 inches above floor, hot water 120 to 140 degrees, backflow devices where needed","Sump pump works, drains properly and opening is covered","Floors, walls and ceilings sound with no holes, trip hazards or loose paint","Kitchen: stove, oven and broiler work; anti-tilt bracket on range","Windows open, stay open and lock; screens on all windows; no broken glass","Doors latch; exterior and bathroom doors lock; garage door and opener work safely","Graspable handrails on stairs; deck and porch railings at 30 inches or more with no more than 4 inch openings","Roof certification from a licensed roofer if there are signs of active leaks","Exterior, gutters, downspouts, fences, sidewalks and driveway in good repair; yard mowed and cleared","Heating system certification on the Township form, original with raised seal (not needed for Florence Tollgate condos); inactive oil fill pipes and tanks removed","Level II chimney certification for wood-burning fireplaces or solid fuel stoves; any work done without permits must be permitted and inspected","Also: Open permits and unpermitted work: Property records are checked. Any work done without a permit must get a permit and pass inspection, and outstanding construction permits must be closed, before the CCO is issued.","Also: Heating system certification: Original Township Heating System Certification form signed by a licensed contractor with raised seal; copies or faxes not accepted.","Also: Chimney certification: Level II chimney certification for wood-burning fireplaces or solid fuel stoves.","Also: Age Restricted Development form: Required if applicable, listed with the CCO application.","Also: Underground oil tank: Township FAQ says a tank in use and not leaking, or properly abandoned in place with permits, may stay; removal is a buyer/seller negotiation.","Also: Sidewalk repairs before sale: Township Code 116-13B(9) says deteriorated, uprooted, cracked or dilapidated sidewalks must be repaired by the owner prior to sale or rental (sidewalks are also on the CCO checklist)."]$j$::jsonb, $j$[{"label":"Initial CCO inspection, per unit (new fees from November 1, 2024, Ordinance 2024-16)","amount":"$165"},{"label":"1st re-inspection","amount":"$35"},{"label":"2nd re-inspection","amount":"$50"},{"label":"3rd re-inspection","amount":"$75"},{"label":"4th and each later re-inspection","amount":"$100"},{"label":"\"No Occupancy\" letter for an as-is purchase (application and inspection fee must be paid first)","amount":"$165.00"},{"label":"Administrative fee for amending a CCO (Township fee schedule, Chapter 2)","amount":"$20"}]$j$::jsonb, $t$https://www.florence-nj.gov/wp-content/uploads/Housing-Inspection-Application-Form-7-2-25.pdf$t$, $t$https://florence-nj.gov/departments/housing/housing-application/$t$, $j$[{"url":"https://florence-nj.gov/departments/housing/","label":"Official source (florence-nj.gov)"},{"url":"https://florence-nj.gov/departments/housing/housing-faqs/","label":"Official source (florence-nj.gov)"},{"url":"https://florence-nj.gov/departments/housing/housing-application/","label":"Official source (florence-nj.gov)"},{"url":"https://www.florence-nj.gov/wp-content/uploads/Housing-Inspection-Application-Form-7-2-25.pdf","label":"Official source (florence-nj.gov)"},{"url":"https://ecode360.com/10061017","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/14792522","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$All residential units must be inspected by the Housing Department and a Continued Certificate of Occupancy issued PRIOR to a change in occupancy or a transfer of property$t$, $t$b2515243b1184a7a06700c93f42a853540cfec28cc261f9788d22cfd56a97734$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":6,"fee_bad":0,"fee_unchecked":2,"quotes":16,"q_ok":11,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0315.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0315.json$t$, true),
  ($t$0315$t$, $t$Florence Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Florence Township Housing Department / Construction Office (smoke, CO and extinguisher checked on the CCO housing inspection) (town fire bureau)","Contact: Michael Perna, Housing Inspector · 609-499-2130 ext. 124 · housing@florence-nj.gov","Apply: Same as the CCO: allow at least 2 weeks, up to 4 weeks in busy times.","How to apply: No separate application found. The smoke alarm, CO alarm and extinguisher check is part of the Housing Inspection Application for the CCO, submitted with the fee to the Housing Department at 711 Broad Street.","Fire official in the NJ state directory (fire district), updated 3/5/2026: Brian Richardson · (609) 499-1393 · brichardson@ftfd40.org","Smoke alarms on every level (including habitable attic and basement) and outside each sleeping area; alarms must be replaced after 10 years","Battery smoke alarms must be 10-year sealed, single station, listed to UL 217; hard-wired alarms from original construction may not be swapped for battery units","Carbon monoxide alarm (UL 2034) in the immediate vicinity of the bedrooms when the home has fuel-burning appliances or an attached garage","Portable fire extinguisher still required by Township Code 116-4.B(1)(d) (re-adopted in the December 2025 amendment) and the July 2025 form: at least 2A:10B:C, residential rated, 10 lb or less","Extinguisher mounted with the maker's bracket, within 10 feet of the kitchen, top no more than 5 feet above the floor, visible, near an exit path","Extinguisher serviced and tagged by a certified contractor within 12 months, or a receipt for a newly bought unit; owner's manual present; do not remove the tamper seal","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"No separate fire certificate fee published; smoke, CO and extinguisher are items 1 to 3 of the CCO housing inspection, which costs this per unit","amount":"$165"}]$j$::jsonb, $t$https://www.florence-nj.gov/wp-content/uploads/Housing-Inspection-Application-Form-7-2-25.pdf$t$, $t$https://florence-nj.gov/departments/housing/$t$, $j$[{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.florence-nj.gov/wp-content/uploads/Housing-Inspection-Application-Form-7-2-25.pdf","label":"Official source (florence-nj.gov)"},{"url":"https://florence-nj.gov/departments/housing/","label":"Official source (florence-nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://ftfd40.org/fire-prevention/","label":"Official source (ftfd40.org)"},{"url":"https://ecode360.com/10061017","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$SMOKE DETECTOR COMPLIANCE Name: Florence Twp Constr Dept Addr: 711 Broad Street Florence NJ 08518 Phone (609) 499-2130$t$, $t$3676f36d8c1bcbf8e57f8e86358e2fbfd307f138bd810d93a9ec539fba3c9df1$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":6,"fee_bad":0,"fee_unchecked":2,"quotes":16,"q_ok":11,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0315.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0315.json$t$, true),
  ($t$0319$t$, $t$Maple Shade Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Certificate of Occupancy (Certificate of Inspection / Certificate of Continued Occupancy), Housing Code Chapter 155$t$, $j$["Issued by: Maple Shade Township Housing Inspection (Land Use / Community Development; Housing Inspector or Code Enforcement Officer)","Contact: Kyle Wagner, Director of Community Development (Zoning Officer / Planning Administration) · 856-779-9610 ext. 151 · zoning@mapleshade.com","Apply: No lead time published. Violations found at the first inspection must be fixed and re-inspected within 90 days (extendable once to 120 days if asked before day 90), or a new application and fee are needed.","How to apply: Fill out the Application for Residential Certificate of Occupancy (property, block and lot, seller, buyer, agent, rooms per floor, access contact), signed by owner and buyer, and submit it with the $125.00 fee by cash or check to Maple Shade Township Housing Inspection, 200 Stiles Avenue, Maple Shade, NJ 08052 (fax 856-779-2524, email Zoning@MapleShade.com). For an as-is sale where the buyer will not move in until repairs are done, use the Transfer of Title application instead ($75, one battery smoke detector per level); the buyer must then apply for the full CO within 120 days.","Valid for: Valid until the next sale, transfer or change of occupancy; not transferable to a new owner except between spouses or family members.","House numbers visible from the street, 4 inches high, contrasting color","Sidewalks, driveways and curbs without raised cracks over 1/2 inch or damage","Roof sound; signs of leaks need a licensed roofer's certification","Gutters and downspouts draining away from the building; front and rear exterior lights","Handrail on front steps with more than 3 risers; guardrails on decks and porches over 30 inches with balusters under 4 inches apart","Peeling paint scraped and painted; rotted wood, loose siding and broken glass repaired; screens on all windows","Yard cut and cleared; trash and recycling cans stored out of view from the street","10-year sealed battery smoke detector on every level and in every bedroom, none more than 10 years old; CO detectors within 10 feet of all sleeping areas","2A:10B:C fire extinguisher mounted in the kitchen area per NJ fire code","Graspable handrails on all stairs including basement; guards on open sides","Outlets, switches and fixtures working with covers; GFCI at kitchen counters, within 6 feet of sinks, bathrooms and washer","Windows open, close, lock and stay up; exterior door locks not keyed from inside; no infestation","Fireplaces and chimneys certified by a licensed contractor; termite damage needs an exterminator's certificate","Basement: water heater relief pipe within 6 inches of floor, emergency heater switch, sump pump to the outside (not the sewer), 60 amp minimum service with labeled breakers, hard-piped dryer vent, abandoned oil tanks removed with a permit","Stove anti-tip device; bedrooms need proper egress, and no basement bedrooms without egress; work done without permits must be permitted","Also: Work done without permits: Permits are needed for new wiring, plumbing, electrical service or panel, heater, A/C, water heater and similar work. A buyer of a home with unpermitted improvements takes on getting and closing those permits.","Also: As-is (rehab / fixer upper) sales: The home must stay vacant until permits and CO approvals are done. A Certificate for Transfer of Property Title ($75, valid 120 days) allows the closing; the full CO application must be filed before it expires."]$j$::jsonb, $j$[{"label":"Residential CO, initial inspection and first re-inspection","amount":"$125"},{"label":"Each later re-inspection","amount":"$65"},{"label":"Residential CO application fee on the form (cash or check)","amount":"$125.00"},{"label":"As-is sale where no one will move in: Certificate for Transfer of Property Title (smoke detector inspection only; valid 120 days)","amount":"$75"}]$j$::jsonb, $t$https://mapleshade.com/wp-content/uploads/2026/01/Residential-CO-Form.pdf$t$, $t$https://mapleshade.com/certificate-of-occupancy/$t$, $j$[{"url":"https://mapleshade.com/certificate-of-occupancy/","label":"Official source (mapleshade.com)"},{"url":"https://mapleshade.com/wp-content/uploads/2025/12/ORDINANCE-2025-18.pdf","label":"Official source (mapleshade.com)"},{"url":"https://mapleshade.com/wp-content/uploads/2026/01/Residential-CO-Form.pdf","label":"Official source (mapleshade.com)"},{"url":"https://mapleshade.com/wp-content/uploads/2026/03/Maple-Shade-Township-Housing-Inspection-Checklist.pdf","label":"Official source (mapleshade.com)"}]$j$::jsonb, $t$Effective immediately, properties within the Township of Maple Shade are required to obtain a Certificate of Occupancy Inspection & Approvals prior to: The Sale of a Property whether Residential or Commercial.$t$, $t$6a67ac571d49fd5e7231456bafd9ac4835f8103c260d08b149a4d98ee08a9941$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":12,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0319.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0319.json$t$, true),
  ($t$0319$t$, $t$Maple Shade Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Maple Shade Township Fire Official / Housing Inspection (the Resale Smoke Alarm Application was replaced by the Residential CO Form) (town fire bureau)","Contact: Matthew Orsini, Interim Fire Official · (856) 779-9610 ext. 179 · firemarshal@mapleshade.com","Apply: Not published.","How to apply: Use the Residential CO Form (it replaced the Resale Smoke Alarm Application) and submit it with the fee to Maple Shade Township Housing Inspection, 200 Stiles Avenue (Zoning@MapleShade.com). For an as-is sale with no occupancy, use the Transfer of Title form. Fire Official staff can answer fire safety questions.","Fire official in the NJ state directory (town), updated 9/10/2025: Matthew Orsini · (856) 779-9610 · firemarshal@mapleshade.com","Smoke detectors: 10-year sealed battery units, one on each level and one in each bedroom; no detector more than 10 years old (Township checklist, March 2026)","Carbon monoxide detectors within 10 feet of all sleeping areas","Fire extinguisher still listed on the March 2026 Township checklist: 2A:10B:C, mounted per NJ fire code in the kitchen area","For an as-is Transfer of Title sale (no one moving in): at least one battery smoke detector on each level, inspected before the transfer certificate is issued","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"No separate smoke certificate fee; the resale smoke/CO check is now part of the Residential CO application","amount":"$125.00"},{"label":"As-is Transfer of Title (vacant sale) with smoke detector inspection","amount":"$75.00"}]$j$::jsonb, $t$https://mapleshade.com/wp-content/uploads/2026/01/Residential-CO-Form.pdf$t$, $t$https://mapleshade.com/new-fire-official/$t$, $j$[{"url":"https://mapleshade.com/new-fire-official/","label":"Official source (mapleshade.com)"},{"url":"https://mapleshade.com/land-use-community-development/","label":"Official source (mapleshade.com)"},{"url":"https://mapleshade.com/wp-content/uploads/2026/03/Transfer-of-Title-Form.pdf","label":"Official source (mapleshade.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://mapleshade.com/wp-content/uploads/2026/01/Residential-CO-Form.pdf","label":"Official source (mapleshade.com)"}]$j$::jsonb, $t$The “Resale Smoke Alarm Application” has been replaced with the “Residential CO Form”.$t$, $t$15fa0d0bbffbbf4272448024d20395441ef436b40277340b9d8b77dfec707077$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":12,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0319.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0319.json$t$, true),
  ($t$0320$t$, $t$Medford Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continuing Occupancy on sale or transfer$t$, $j$["Issued by: Medford Township (sewer inspection scheduled through Utility Billing / Sewer and Water); smoke and CO part by Medford Township Fire & EMS Department","Contact: (609) 654-2608 ext 303","How to apply: For homes on public water and/or sewer, call Utility Billing at (609) 654-2608 ext 303 to schedule the final water reading and the sewer inspection for settlement. For the smoke and CO certificate (the 'Certificate of Occupancy' on the Township's closing list), apply online with the Fire Department's Smoke Detector Inspection Application (see the fire certificate).","Valid for: Sump pump Certificate of Continuing Occupancy: 180 days from issue (Township Code 71-10E(1))","Homes on public sewer: inspection before closing; no sump pumps, roof drains or other drainage devices may be connected directly or indirectly to the Township sanitary sewer (Township Code 121-8)","If a bad connection cannot be removed right away, a $2,000 cash bond can be posted so the certificate can issue; it is released after the work passes inspection","Homes on public water: final water meter reading before closing","Smoke and CO certificate from the Fire Department (see the fire certificate)","Homes on wells and septic systems: handled by the Burlington County Health Department, not the Township","Also: Final water meter reading and sewer inspection: Homes on public water and/or sewer: call Billing at (609) 654-2608 ext 303 to schedule a final water reading or a sewer inspection for settlement.","Also: Sump pump / roof drain disconnection: Township Code 121-8 bars sump pumps, roof drains and other drainage from the sanitary sewer; they must be disconnected (or a $2,000 cash bond posted) before the sale certificate issues.","Also: Wells and septic systems: Handled by the Burlington County Health Department, 15 Pioneer Boulevard, Westampton, 609-265-5515."]$j$::jsonb, $j$[{"label":"Certificate of continuing occupancy for sump pumps (sewer inspection on sale)","amount":"$50"}]$j$::jsonb, null, $t$https://medfordtownship.com/construction/$t$, $j$[{"url":"https://medfordtownship.com/construction/","label":"Official source (medfordtownship.com)"},{"url":"https://medfordtownship.com/utilities/","label":"Official source (medfordtownship.com)"},{"url":"https://ecode360.com/9110050","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/9109167","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$To obtain a Certificate of Occupancy please contact the Fire Department . For those units with public water and/or sewer, please contact the Utility Billing office for final meter readings and sewer inspections.$t$, $t$c528246417102c5ea22f4cbd95d8d0e07e032ee19e95ced7553ba6bef95c3704$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":4,"fee_bad":0,"fee_unchecked":1,"quotes":16,"q_ok":10,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0320.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0320.json$t$, true),
  ($t$0320$t$, $t$Medford Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Medford Township Fire & EMS Department (Fire Marshal / fire inspections) (town fire bureau)","Contact: Brian Widmann, Fire Marshall (Township spelling); Fire Official in the state directory · (609) 953-3291 · bwidmann@medfordfire.org","Apply: Apply more than 10 business days before the change of occupant for the lowest fee.","How to apply: Fill out the online Smoke Detector Inspection Application linked from medfordfire.org (property address, settlement date, time until settlement, owner, phone to set up the inspection, email for the certificate) and check each compliance box; all boxes must be checked before an inspection is scheduled. When paying by credit card, the fee amount is entered on the MuniPay form. The certificate is emailed. Inspection line (609) 953-3291.","Fire official in the NJ state directory (town), updated 7/30/2026: Brian D Widmann · (609) 953-3291 · bwidmann@medfordfire.org","Smoke alarm on each level including basements (not attic or crawl space), and smoke and CO alarms outside each sleeping area within 10 feet of bedrooms","Homes built before 1977: 10-year sealed battery smoke alarms; later homes: AC hard-wired alarms by year built, interconnected where required, kept in working order","Interconnected systems cannot be replaced with stand-alone battery detectors","Homes with a monitored NFPA 72 system instead of AC alarms need a certificate of compliance from a certified alarm contractor or electrician","CO alarm in the common hall outside of, and within 10 feet of, the bedroom doors; battery or plug-in is acceptable","House number visible from the public road, contrasting and bright or reflective (Township Code 51-3)","Leave alarm instruction manuals for the next owner","The online form does not list a fire extinguisher (the code article title still mentions one)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, request received more than 10 business days before the change of occupant","amount":"$50"},{"label":"Request received 5 to 9 business days before the change of occupant","amount":"$90"},{"label":"Request received 4 or fewer business days before the change of occupant","amount":"$161"},{"label":"Second re-inspection or later, each (first re-inspection is free)","amount":"$35"}]$j$::jsonb, $t$https://hipaa.jotform.com/221363427572152$t$, $t$https://medfordtownship.com/fire-ems-department/$t$, $j$[{"url":"https://www.medfordfire.org/","label":"Official source (medfordfire.org)"},{"url":"https://hipaa.jotform.com/221363427572152","label":"Official source (hipaa.jotform.com)"},{"url":"https://medfordtownship.com/fire-ems-department/","label":"Official source (medfordtownship.com)"},{"url":"https://ecode360.com/9109167","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Smoke Detector Inspection Application$t$, $t$be29733f939e300baba0d5485c0b56724d3e9ca901811417d260a9759078e4c8$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":4,"fee_bad":0,"fee_unchecked":1,"quotes":16,"q_ok":10,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0320.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0320.json$t$, true),
  ($t$0321$t$, $t$Medford Lakes Borough$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continuing Occupancy (CCO), issued after the extraneous flow (sump pump / roof drain / floor drain) inspection$t$, $j$["Issued by: Borough of Medford Lakes (Wastewater Department inspection; Office of Construction handles CCO questions)","Contact: Tom Boyd, Construction Official · 609-654-8898, ext. 128 · construction@medfordlakes.com","Apply: Inspections are scheduled based on availability. Fees are lowest when the application is filed more than 10 business days before settlement.","How to apply: File the Application for Certificate of Extraneous Flow Elimination Compliance with the Wastewater Department (14 Stokes Road, 609-654-2013, office hours Monday to Friday 7 a.m. to 2:30 p.m.) with the fee; the inspector contacts the applicant once the paid application is received. The Borough code says the property owner is responsible for scheduling this inspection. File the Fire Inspection Application at the same time. For other CCO questions contact the Office of Construction, 1 Cabin Circle, 609-654-8898 ext. 128, construction@medfordlakes.com.","Sump pumps, roof drains, floor drains and other drainage devices must not be connected directly or indirectly to the Borough sanitary sewer; a CCO is issued only after any such connections are permanently removed (Code 190-26)","Disconnected sump pumps and drains must discharge at least 10 feet from any structure with a basement, cellar or crawl space, not into a street, storm sewer, neighbor's property or lake without approval","Smoke alarm, CO alarm and fire extinguisher inspection done together with the CCO inspection (see the fire certificate)","Also: Extraneous flow elimination certificate (sump pump, roof and floor drains): This Wastewater Department inspection is the basis for the Borough's certificate of continuing occupancy on a sale (see the town certificate). Same fee tiers as the fire certificate; $35 re-inspection. Wastewater Department, 14 Stokes Road, 609-654-2013."]$j$::jsonb, $j$[{"label":"Extraneous flow (sump pump / roof / floor drain) inspection, Wastewater Department, more than 10 business days before settlement (no separate CCO fee was found)","amount":"$50"},{"label":"Extraneous flow inspection, 4 to 10 business days before settlement","amount":"$70"},{"label":"Extraneous flow inspection, less than 4 business days before settlement","amount":"$125"},{"label":"Extraneous flow re-inspection","amount":"$35"},{"label":"Cash bond if the work cannot be finished before closing (Borough then issues a temporary CCO; bond returned after approval)","amount":"$2,000"}]$j$::jsonb, $t$https://www.medfordlakes.com/DocumentCenter/View/28/Extraneous-Flow-Application$t$, $t$https://www.medfordlakes.com/157/Rentals-Change-of-Occupancy$t$, $j$[{"url":"https://ecode360.com/8278679","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/8276702","label":"Official source (ecode360.com)"},{"url":"https://www.medfordlakes.com/157/Rentals-Change-of-Occupancy","label":"Official source (medfordlakes.com)"},{"url":"https://www.medfordlakes.com/149/Construction-Building","label":"Official source (medfordlakes.com)"},{"url":"https://www.medfordlakes.com/DocumentCenter/View/28/Extraneous-Flow-Application","label":"Official source (medfordlakes.com)"}]$j$::jsonb, $t$A certificate of continuing occupancy is required upon any sale or transfer of property to ensure that extraneous flow is not entering the sanitary sewer system.$t$, $t$7b7a423efe40a3392427a42609b9347466406d7247205877238a1640cde372df$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":8,"fee_bad":0,"fee_unchecked":1,"quotes":16,"q_ok":10,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0321.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0321.json$t$, true),
  ($t$0321$t$, $t$Medford Lakes Borough$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Medford Lakes Fire Department, Bureau of Fire Prevention (LEA #03321) (town fire bureau)","Contact: Vincent Knott, Fire Official · (856) 316-8584 · vincent.knott@mlfd371.org","Apply: Submit to the Borough Office more than 10 business days before settlement to avoid higher fees. The Fire Official contacts the applicant once the paid application is received. The October 2024 form says certificates are valid for 90 days; the Borough web page says six months.","How to apply: Fill out the Application for Certificate of Smoke Alarm, Carbon Monoxide Alarm and Portable Fire Extinguisher Compliance (address, block and lot, owner, occupant, sales agent and firm, settlement date) and submit it with the fee, payable to the Borough of Medford Lakes, to the Borough Office at 1 Cabin Circle. The form records cash or check; the web page says cash or money order. The Fire Official then calls to schedule.","Fire official in the NJ state directory (town), updated 5/18/2026: Craig Farnsworth II · (609) 654-8898 · craig.farnsworth@mlfd371.org","House numbers: numerals at least 4 inches high, contrasting color, permanently fixed to the house and visible from the street; light post or mailbox numbers are not accepted","Smoke alarm on every level; basement alarm at the bottom of the stairwell at ceiling level (not between joists); hallway alarm within 10 feet of all bedroom doors","Smoke alarm on the ceiling of every bedroom in homes built 1991 to present","Hard-wired smoke alarms cannot be replaced with battery alarms; all smoke alarms under 10 years old and working; battery alarms must be the 10-year battery type","CO alarm in the hallway within 10 feet of all bedrooms, under 10 years old, installed per the maker; plug-in, battery or hard-wired accepted, but not in switched outlets or against floor molding","Fire extinguisher still on the October 2024 form: minimum 2A-10B:C, under 10 pounds, mounted on its bracket within 10 feet of the kitchen in the exit path, visible and reachable","Homes with a low voltage fire alarm system must have it tested and approved by the alarm company before the inspection and show the alarm certification at the inspection","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"More than 10 business days before settlement","amount":"$50"},{"label":"4 to 10 business days before settlement","amount":"$70"},{"label":"Less than 4 business days before settlement","amount":"$125"},{"label":"Re-inspection","amount":"$35"}]$j$::jsonb, $t$https://www.medfordlakes.com/DocumentCenter/View/119/Fire-Inspection-Application-PDF$t$, $t$https://www.medfordlakes.com/157/Rentals-Change-of-Occupancy$t$, $j$[{"url":"https://www.medfordlakes.com/157/Rentals-Change-of-Occupancy","label":"Official source (medfordlakes.com)"},{"url":"https://www.medfordlakes.com/DocumentCenter/View/119/Fire-Inspection-Application-PDF","label":"Official source (medfordlakes.com)"},{"url":"https://ecode360.com/8276702","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The cost of the Smoke Detector/CO Detector Compliance Certificate is $50 if scheduled 10 days prior to change of occupancy, $70 if scheduled 4 to 10 days prior to change or $125 if scheduled less than 4 days prior.$t$, $t$ddb123db1184f2ce1d11867b0009c5703397cb94f2474557d24ba7f91a2f0230$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":8,"fee_bad":0,"fee_unchecked":1,"quotes":16,"q_ok":10,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0321.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0321.json$t$, true),
  ($t$0322$t$, $t$Moorestown Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate for Change in Occupancy/Ownership (Township page calls it Certificate of Continuing Occupancy)$t$, $j$["Issued by: Moorestown Township Department of Public Works (inspection); Director of Community Development reviews surveys","Contact: Don Lloyd, Director, Public Works · 856-235-3520, option 2 · dlloyd@moorestown.nj.us","Apply: Get it before the real estate closing; the seller schedules the inspection with Public Works.","How to apply: Call Public Works at 856-235-3520, option 2, to schedule the inspection. The fee is noted on the tax search and collected at closing. If the property is on the Township's list of properties adjoining Township land, give a survey (no more than 90 days old) to the Department of Community Development.","Valid for: 60 days from issue; if closing does not happen within 60 days a new certificate is needed","No sump pumps, roof drains or other drainage connected to the sanitary sewer (must be permanently disconnected)","Water meter working and reading accurately; the Township replaces a bad meter, but any plumbing changes needed are at the owner's cost by a licensed plumber","Sidewalks free of trip hazards or other hazards; owner repairs or replaces as directed","No open construction permits; all improvements inspected and passed so permits can be closed","No encroachment on Township-owned land","If the property adjoins Township-owned property: a survey no more than 90 days old, with corner flags left in place until closing","Also: Open permits must be closed before settlement: 'Property cannot settle until all open permits are closed.' Construction Office: (856) 235-0914, Ext. 3018 or 3069 (per the selling sheet); the Construction Office page lists 856-235-0912, ext. 3018.","Also: Final water meter reading: Call Public Works 856-235-3520, option 2. Final figures are available after 2 p.m. the day before settlement at (856) 235-0912 ext. 3008, 3009, 3010.","Also: Survey for properties adjoining Township land: Needed to settle if the property adjoins Township-owned land; survey dated no more than 90 days before, flags left in place until closing.","Also: Buyer water/sewer account: Buyers contact Tax / Water & Sewer Billing (856) 235-0912 ext. 3008, 3009, 3010 with name, address, settlement date and mailing address."]$j$::jsonb, $j$[{"label":"Inspection, all residential and commercial properties (noted on tax search, collected at closing)","amount":"$75.00"},{"label":"Inspection, second floor condominium (noted on tax search, collected at closing)","amount":"$50.00"}]$j$::jsonb, null, $t$https://www.moorestown.nj.us/641/Certificate-of-Continuing-Occupancy$t$, $j$[{"url":"https://www.moorestown.nj.us/DocumentCenter/View/6678/05-2022","label":"Official source (moorestown.nj.us)"},{"url":"https://www.moorestown.nj.us/641/Certificate-of-Continuing-Occupancy","label":"Official source (moorestown.nj.us)"},{"url":"https://www.moorestown.nj.us/DocumentCenter/View/6604/Buying_-Selling_Renting-_Change-of-Mailing-Address","label":"Official source (moorestown.nj.us)"},{"url":"https://www.moorestown.nj.us/162/Water-Sewer","label":"Official source (moorestown.nj.us)"},{"url":"https://ecode360.com/10345310","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$The Township of Moorestown requires the Seller of any property in the Township to obtain a Certificate for Change in Occupancy/Ownership prior to the real estate closing$t$, $t$b4ba41de1b669eb2060e59064e35f6f846e4e36e5f2cea12d5817f8ff0d8403a$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":10,"fee_bad":0,"fee_unchecked":0,"quotes":34,"q_ok":19,"q_bad":0,"q_unchecked":15},"source":"property/data/municipal-requirements/checked/0322.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0322.json$t$, true),
  ($t$0322$t$, $t$Moorestown Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Fire District No. 1: issued by Moorestown Fire District No. 1 (Moorestown Fire Department), served by Moorestown Fire Prevention (Bureau of Fire Prevention) (fire district). Covers: Fire District 1 part of the township (the Township says to find your district on the NJ Division of Elections 'Find Your Polling Location' page, 'Fire' row)","Fire District No. 1 contact: Matthew Orsini, Fire Official (Bureau of Fire Prevention) · 856-234-1222 · fm@fireprevention31.org","Fire District No. 1, apply: Certificates are only good for 30 days, so requests for inspections more than 30 days before settlement/move-in are denied. Apply more than 10 business days before the change of occupant for the lowest fee.","Fire District No. 1, how to apply: Apply online with the Moorestown Fire Prevention Jotform application (linked from the Township's Certificate of Continuing Occupancy page). Upload a copy of the contract of sale or lease. Pick a requested inspection date; inspections are Tuesdays and Thursdays, 9 to 11 AM, excluding holidays. The bureau emails a confirmation with the fee and who to make the check payable to. Pay by check or money order to the inspector at the inspection; not paying on arrival is an automatic failure. If you need an inspection within 24 hours, call the office after submitting.","Fire District No. 2: issued by Moorestown Fire District No. 2 (Lenola Fire Company), served by Moorestown Fire Prevention (Bureau of Fire Prevention) (fire district). Covers: Fire District 2, the western portion of the township (Lenola area); confirm with the polling-location lookup","Fire District No. 2 contact: Matthew Orsini, Fire Official (Bureau of Fire Prevention) · 856-234-1222 · fm@fireprevention31.org","Fire District No. 2, apply: Certificates are only good for 30 days, so requests for inspections more than 30 days before settlement/move-in are denied. Apply more than 10 business days before the change of occupant for the lowest fee.","Fire District No. 2, how to apply: Apply online with the Moorestown Fire Prevention Jotform application (linked from the Township's Certificate of Continuing Occupancy page). Upload a copy of the contract of sale or lease. Pick a requested inspection date; inspections are Tuesdays and Thursdays, 9 to 11 AM, excluding holidays. The bureau emails a confirmation with the fee and who to make the check payable to. Pay by check or money order to the inspector at the inspection; not paying on arrival is an automatic failure. If you need an inspection within 24 hours, call the office after submitting.","Fire official in the NJ state directory (fire district), updated 5/18/2026: Matthew M Orsini · (856) 234-6660 · fireofficial313@gmail.com","All smoke detectors must be within 10 years of the manufacture date","All CO detectors must be within 7 years of the manufacture date","CO detector within 10 feet outside all sleeping areas if the home has a fuel-burning appliance, fireplace or garage (CO detectors only in bedrooms fail)","Pre-1975 homes: 10-year sealed battery smoke detector on each level, within 10 feet of each bedroom, including basement","AC smoke detectors must be interconnected; smoke detector at the bottom of basement stairs and top of walk-up attic stairs","Hardwired low-voltage fire alarm system must be tested and approved by a NJ licensed fire alarm contractor before the inspection; show or upload the certification","Smoke detector circuit located and labeled at the panel before the inspector arrives; panel circuits properly labeled","Homes with a generator, solar panels or battery storage need a permanent (not handwritten) 'CAUTION: MULTIPLE SOURCES OF POWER' type label within 18 inches of the main panel and the electric meter","House numbers permanently affixed, Arabic numerals about 3 inches high and 1 inch wide, contrasting background, visible from the street, not on a door","Upload a copy of the contract of sale or lease with the application","The Construction Office is notified of each application to check for open permits or violations","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Fire District No. 1: Smoke/CO certificate, request received more than 10 business days before change of occupant","amount":"$45.00"},{"label":"Fire District No. 1: Smoke/CO certificate, request received 4 to 10 business days before change of occupant","amount":"$90.00"},{"label":"Fire District No. 1: Smoke/CO certificate, request received fewer than 4 days before change of occupant","amount":"$161.00"},{"label":"Fire District No. 1: Second or later reinspection","amount":"$45.00"},{"label":"Fire District No. 2: Smoke/CO certificate, request received more than 10 business days before change of occupant","amount":"$45.00"},{"label":"Fire District No. 2: Smoke/CO certificate, request received 4 to 10 business days before change of occupant","amount":"$90.00"},{"label":"Fire District No. 2: Smoke/CO certificate, request received fewer than 4 days before change of occupant","amount":"$161.00"},{"label":"Fire District No. 2: Second or later reinspection","amount":"$45.00"}]$j$::jsonb, $t$https://form.jotform.com/fireofficial313/smokeinspection$t$, $t$https://www.fireprevention31.org/$t$, $j$[{"url":"https://www.moorestown.nj.us/696/Fire-Department","label":"Official source (moorestown.nj.us)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.moorestown.nj.us/641/Certificate-of-Continuing-Occupancy","label":"Official source (moorestown.nj.us)"},{"url":"https://form.jotform.com/fireofficial313/smokeinspection","label":"Official source (form.jotform.com)"},{"url":"https://web.archive.org/web/20260411081752/https://www.bureauoffireprevention.com/_files/ugd/42b6a6_44bdd1b5d1164a1a8102b8dd30d9ef6f.pdf?index=true","label":"Official source (web.archive.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.fireprevention31.org/contact","label":"Official source (fireprevention31.org)"},{"url":"https://www.fireprevention31.org/","label":"Official source (fireprevention31.org)"}]$j$::jsonb, $t$Moorestown Township is home to two volunteer fire districts.$t$, $t$455f02f348f70564d2bdcd0dce743ec504a1e9517ebe3de1fb4f1a2b17a74c2c$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":10,"fee_bad":0,"fee_unchecked":0,"quotes":34,"q_ok":19,"q_bad":0,"q_unchecked":15},"source":"property/data/municipal-requirements/checked/0322.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0322.json$t$, true),
  ($t$0323$t$, $t$Mount Holly Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Approval (resale inspection by the Housing Office)$t$, $j$["Issued by: Mount Holly Township Housing Code Enforcement Officer (Code Enforcement and Housing Department / Housing Office)","Contact: Carolyn Youngbean, Housing · 609-864-1203 or 609-864-2464 · cyoungbean@twp.mountholly.nj.us","Apply: The Township code says the inspection is made within five business days of a complete application. The Fire District page says sellers should call within 60 days of settlement.","How to apply: Fill out the Resale Inspection Application (all fields required, including settlement date, heater certification date and fire certification date) and submit it to the Township Housing Office, 17 Pine Street, Mount Holly, NJ 08060. The form lists payment by check, money order, cash or credit card. Call 609-864-1203 or 609-864-2464 with questions.","Valid for: Until the next change in ownership or occupancy (or a later inspection that finds violations), per Township Code 90-2H","Required before any change in ownership or occupancy, including transfer of title; violations must be fixed before closing or (except safety violations) assumed by the buyer and fixed within 30 days (no more than 60 days with an extension)","Heating system certification by an HVAC-R contractor or master plumber (form expires 1 year after the inspection date); the application asks for its date","Fire (smoke/CO) certification date is asked on the application","At least one working 10-year sealed battery smoke detector on each level including the basement; CO detectors within 10 feet of sleeping areas","Handrails on stairs with 4 or more risers; guard rails on porches/decks 30 inches or more above grade","GFCI within 6 feet of water sources; circuit breaker panel in order; no bare-wire fixtures","Ceilings, walls and floors with no holes, chipped paint, severe cracks or water stains; no ripped or old carpet","Interior doors sound, fit the frame and close properly; no keyed locks or deadbolts on interior doors","Heat working; appliances working with anti-tip bracket on the range","Hot and cold water; toilets flush","Bathroom has a window or exhaust fan","Utilities on at the time of inspection","Yard free of trash, debris and motor vehicles; all code violations fixed","Roof, chimney, siding, gutters and downspouts intact; windows and screens work","Driveway, sidewalks and aprons in safe condition; no trip hazards","No work done without permits","Also: Heating system certification: A licensed HVAC-R contractor or master plumber must fill out the Township Heating System Certification; it expires one year from the inspection date.","Also: Trash and recycling escrow: The Housing Office verifies trash compliance and recycling carts at closing; the 2016 fee sheet lists a $250.00 trash escrow and $100.00 recycling cart escrow.","Also: Work without permits: The inspection checklist includes 'Work without Permits'. Construction Office: inspections@twp.mountholly.nj.us."]$j$::jsonb, $j$[{"label":"Resale inspection (fee sheet effective May 5, 2016)","amount":"$150.00"},{"label":"3rd or more inspection, per unit (2016 fee sheet)","amount":"$30.00/unit"},{"label":"Trash escrow (2016 fee sheet)","amount":"$250.00"},{"label":"Recycling cart escrow (2016 fee sheet)","amount":"$100.00"}]$j$::jsonb, $t$https://storage.googleapis.com/juniper-media-library/560/2026/05/RESALE_INSPECTION_APPLICATION_2026.pdf$t$, $t$https://twp.mountholly.nj.us/departments/code-enforcement-housing-department$t$, $j$[{"url":"https://twp.mountholly.nj.us/departments/code-enforcement-housing-department","label":"Official source (twp.mountholly.nj.us)"},{"url":"https://storage.googleapis.com/juniper-media-library/560/2026/05/RESALE_INSPECTION_APPLICATION_2026.pdf","label":"Official source (storage.googleapis.com)"},{"url":"https://storage.googleapis.com/juniper-media-library/560/2026/05/Property_Inspections_List_2025_MH.pdf","label":"Official source (storage.googleapis.com)"},{"url":"https://storage.googleapis.com/juniper-media-library/560/2026/05/Fees_for_Housing_Inspections.pdf","label":"Official source (storage.googleapis.com)"},{"url":"https://ecode360.com/10357279","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Resale and Rental Inspections : Conducts mandatory health and safety property checks required for residential resales and tenancy turnovers.$t$, $t$74ee1845dadb4ec2593f7a5654a742f56d117a7e557e23ffa7d67a3bd4b38b09$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":6,"fee_bad":0,"fee_unchecked":1,"quotes":18,"q_ok":13,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0323.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0323.json$t$, true),
  ($t$0323$t$, $t$Mount Holly Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Mount Holly Fire District No. 1, Bureau of Fire Prevention (fire district)","Contact: Thomas Mason, Jr., Fire Official / Fire Chief · (609) 864-2464 (Smoke Detector Certifications); Fire Official office (609) 518-8911 · tmason@mounthollyfire.org","Apply: Within 60 days of settlement, the seller contacts the Township Bureau of Housing and Code Enforcement to schedule the resale inspection.","How to apply: Call (609) 864-2451 or email the Township Bureau of Housing and Code Enforcement to schedule, giving the property address and settlement date (the district page lists kscelba@twp.mountholly.nj.us, which may be out of date; the district's current contact page lists Smoke Detector Certifications at (609) 864-2464). Pay the inspector with a certified check, money order or business check made payable to MOUNT HOLLY FIRE DISTRICT No.1. Cash and personal checks are not accepted. If the home is not accessible or fails, reschedule and pay again.","Fire official in the NJ state directory (fire district), updated 6/18/2025: Thomas Mason, Jr · (609) 261-7233 · Tmason@mounthollyfire.org","Smoke and CO detectors must be 10-year sealed battery (lithium) or hardwired, no more than 10 years old, and UL listed; at least one on each level including the basement","Hardwired smoke/CO detectors may not be replaced with battery units","Basement detector on the ceiling at the bottom of the basement stairs","CO alarm within 10 feet of every bedroom","Portable fire extinguisher: new within 12 months with receipt, or serviced by a NJ-certified extinguisher contractor; at least 2A-10:BC and not over 10 pounds; mounted on the manufacturer's bracket within 10 feet of the kitchen in the exit path; top no more than 5 feet and bottom at least 4.5 inches above the floor; not hidden in a cabinet or behind a door (per the district page last updated January 2024)","House numbers at least 4 inches high, contrasting color, permanently affixed, visible from the street","Monitored central alarm systems need an NFPA 72 inspection report from a NJ-licensed fire protection company at or before the inspection","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Resale fire inspection, per dwelling unit","amount":"$85.00"},{"label":"Apartment house common area (in addition to $85.00 per apartment)","amount":"$85.00"},{"label":"Reinspection after noncompliance, per occurrence","amount":"$50"}]$j$::jsonb, null, $t$https://home.mounthollyfire.org/featured/covid-19-information-fire-inspections-annual-resale/$t$, $j$[{"url":"https://home.mounthollyfire.org/featured/covid-19-information-fire-inspections-annual-resale/","label":"Official source (home.mounthollyfire.org)"},{"url":"https://home.mounthollyfire.org/contact-directory/","label":"Official source (home.mounthollyfire.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://ecode360.com/10357766","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Mount Holly Township, Bureau of Housing and Code Enforcement is currently scheduling residential resale inspections for the purpose of issuance of certification for resale.$t$, $t$f93da34fb22bd6baa017ef4816e946717533c1e901abd841588e0a6e383816b9$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":6,"fee_bad":0,"fee_unchecked":1,"quotes":18,"q_ok":13,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0323.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0323.json$t$, true),
  ($t$0324$t$, $t$Mount Laurel Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO)$t$, $j$["Issued by: Mount Laurel Township Department of Community Development (Construction / Code)","Contact: Jennifer Parks, CCO questions and scheduling contact · 856-234-0001 ext. 1227 · jparks@mountlaurel.com","Apply: Fees are tiered by how early you apply: 11 or more days before closing is the lowest fee, and the Township does not guarantee scheduling within 10 days of closing. The application must be submitted with payment before the inspection is scheduled; the office calls you to set the time. Give 24 hours' notice to cancel or reschedule or the fee is charged.","How to apply: Fill out the CCO application (Ordinance 2021-8 form) and mail it or drop it off with payment at Mount Laurel Township, Attn: Jennifer Parks, 750 Centerton Road, 2nd Floor, Mount Laurel, NJ 08054. Emailed applications are NOT accepted. Payment by cash, check or money order only. The office calls to schedule the inspection (Monday to Friday, 8:30 to 11:30 AM or 11:30 AM to 2:30 PM).","Valid for: Must be obtained within 90 days of the closing date (extension possible from the Construction Code Official if closing is delayed). A home that passed its annual rental inspection can get a certificate valid to the end of the calendar year without a second inspection.","All permits closed before approval (decks, pools, sheds, water heaters, furnace/HVAC, finished basements, electrical, plumbing, structural work)","Electric, gas and water on; panels, furnace and water heater accessible; furnace and water heater working and properly vented","Yard free of debris, high grass and hazards; roof, chimney, siding, gutters in good condition","Sidewalks, stairs, patios, walkways and driveways free of trip hazards","House numbers visible from the street, at least 4 inches high","Windows work with no broken or missing glass; entry doors have a working lockset and deadbolt; no double-key deadbolts or slide bolts","Handrail on stairs with 4 or more risers; guards where a walking surface is more than 30 inches above grade","Plumbing works with no leaks; hot and cold water; water temperature not over 120F","Bathroom has a working window or exhaust fan vented outside","Range anti-tip device where required","GFCI protection within 6 feet of sinks and at laundry sinks, garage and exterior outlets; covers on outlets, switches, junction boxes; panel cover with no open breaker spaces","Garage-to-house door solid wood, solid-core, steel or 20-minute rated; garage door opener plugged directly into an outlet (no extension cords); garage attic access fire rated (permit required)","Dryer vented outside with 4-inch rigid or semi-rigid metal duct (no plastic or foil); washer drains to approved drain","Pool barriers maintained; gates self-closing and self-latching, latch at least 54 inches high, opening away from pool","Any other health or safety hazard found by the inspector must be fixed","Also: Open permits must be closed: All required permits must be obtained and closed before CCO approval. Construction Department 856-234-9686.","Also: Rental registration if the buyer will rent: If the property will be a rental, it must be registered with the Township within 14 days of the closing date (Code Chapter 121).","Also: Fire department smoke/CO certificate: Smoke certificate required from the Fire Department; schedule at mlfd.org."]$j$::jsonb, $j$[{"label":"Initial inspection, requested 11 or more days before closing","amount":"$75.00"},{"label":"Inspection requested 4 to 10 days before closing","amount":"$100"},{"label":"Inspection requested 3 days or less before closing","amount":"$125"},{"label":"Discount: low/moderate income deed-restricted home or primary owner aged 65+","amount":"fifty percent (50%)"},{"label":"Re-inspection (waived if within 30 days and all items fixed)","amount":"$25.00"}]$j$::jsonb, $t$https://www.mountlaurel.com/CCO%20APPLICATION%202nd%20floor.pdf?t=202603171035570$t$, $t$https://www.mountlaurel.com/department/community_development___construction/new_page.php$t$, $j$[{"url":"https://www.mountlaurel.com/Document%20Center/Department/Community%20Development%20Construction/Forms/Housing%20Inspection%20List%20final.pdf?t=202106251245530","label":"Official source (mountlaurel.com)"},{"url":"https://www.mountlaurel.com/CCO%20APPLICATION%202nd%20floor.pdf?t=202603171035570","label":"Official source (mountlaurel.com)"},{"url":"https://www.mountlaurel.com/Mount_Laurel_Municipal_CCO_Checklist.pdf?t=202606101127590","label":"Official source (mountlaurel.com)"},{"url":"https://www.mountlaurel.com/department/community_development___construction/new_page.php","label":"Official source (mountlaurel.com)"},{"url":"https://ecode360.com/10362874","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$REQUIREMENTS FOR CERTIFICATE OF CONTINUED OCCUPANCY (C.C.O.) For Resale of ALL Residential Homes$t$, $t$55146c28181a32aed489d51c68f7d78f7c5bf482a247e1ecd7b82c9848abe887$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":9,"fee_bad":0,"fee_unchecked":0,"quotes":20,"q_ok":16,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0324.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0324.json$t$, true),
  ($t$0324$t$, $t$Mount Laurel Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Mount Laurel Fire Department (Mount Laurel Fire District #1), Bureau of Fire Prevention (fire district)","Contact: Bill Glassman, Fire Marshal · (856) 234-6053 · wglassman@mlfd.org","Apply: Fee tiers are counted back from the inspection date: more than 10 days before the inspection date is the lowest fee. Inspections are each Wednesday, by appointment only; the appointment is made when the application and payment are made.","How to apply: Apply and pay online through the Mount Laurel Fire Department's Muniverse portal (linked from mlfd.org under Inspections / Forms, Residential Smoke Alarm Inspections), or in person at Fire Headquarters, 69 Elbo Lane, Mount Laurel (office hours Monday to Friday, 8 AM to 12 PM and 1 PM to 4 PM). Have the buyer's and seller's names, property address, settlement date and year built. Payment by exact change, check or charge. All fees are non-refundable; a missed time block or a failed inspection needs a new application and a new fee. Communication is by email.","Fire official in the NJ state directory (fire district), updated 3/5/2026: William J Glassman, Jr · (856) 234-6053 · wglassman@mlfd.org","All smoke alarms must be less than 10 years old (Mount Laurel Township Ordinance 2021-19, Chapter 81, Section 81-24); take each alarm down and check the date on the back; replace any with no date","Each level needs an AC (hardwired) alarm or a DC 10-year sealed battery alarm, based on year built; all AC alarms must be interconnected","Pre-1975 homes: 10-year sealed battery alarm on each level including basement","CO alarm outside of, but near, all sleeping areas if the home has a fuel-burning appliance, fireplace or garage (CO alarms only in bedrooms fail)","Hardwired low-voltage fire alarm systems (alarm company) must be tested by an alarm contractor before the inspection; bring the contractor's certification","Breaker for the smoke alarms must be found and labeled before the inspector arrives; owner or agent turns it on and off","Homes with a generator, solar panels or battery storage need a permanent (not handwritten) 'CAUTION: MULTIPLE SOURCES OF POWER' type label within 18 inches of the main panel and the electric meter","House numbers: Arabic numerals at least 3 inches high, securely mounted, contrasting color, at least 30 inches above ground, visible from the street","No recalled smoke or CO alarms","Everything must be done before the inspector arrives; inspectors cannot install or repair anything","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO inspection, applied more than 10 days before the inspection date","amount":"$65"},{"label":"Smoke/CO inspection, applied 4 to 10 days before the inspection date","amount":"$100"},{"label":"Smoke/CO inspection, less than 4 days before the inspection date (based on availability)","amount":"$140"},{"label":"Change of ownership or occupancy without the certificate (penalty)","amount":"$500"}]$j$::jsonb, $t$https://geo.muniverse.us/prod1/portal/portal.jsp?c=596835512&p=556560486&g=556589337$t$, $t$https://mlfd.org/residential-smoke-alarm-inspections/$t$, $j$[{"url":"https://geo.muniverse.us/prod1/portal/portal.jsp?c=596835512&p=556560486&g=556589337","label":"Official source (geo.muniverse.us)"},{"url":"https://mlfd.org/faqs/","label":"Official source (mlfd.org)"},{"url":"https://mlfd.org/governance-responsibilities/","label":"Official source (mlfd.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Any change of ownership or occupancy (including the storage of personal property) may not occur, prior to a successful inspection AND possession of a Smoke Alarm and Carbon Monoxide Alarm Inspection (CSACMAI) Certification (passed inspection).$t$, $t$edf623e874eaac843c8827d079ec0401818d445dcb2863dead56a342231e1207$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":9,"fee_bad":0,"fee_unchecked":0,"quotes":20,"q_ok":16,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0324.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0324.json$t$, true),
  ($t$0325$t$, $t$New Hanover Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale inspection (Township Code 137-2, inspection prior to rental and/or resale)$t$, $j$["Issued by: New Hanover Township (code names the Construction Official; the Township site says the Zoning Officer oversees local rental and resale processes)","Contact: Aiden DeMarsey, Zoning Officer (Interim); also Deputy Clerk · 609-758-7149 x10 · ademarsey@newhanovertwp.com","Apply: The code says the inspection is made within 48 hours after the written request is received.","How to apply: No application form is posted. Send a written request (property location, buyer's name and the date the buyer takes occupancy) to the Township; the website says the Zoning Officer, Aiden DeMarsey, handles local rental and resale processes (Municipal Complex, 2 Hockamick Road, Cookstown, NJ 08511).","Written request before the sale giving the property location, the date the buyer will take occupancy and the buyer's name","Home must meet the ICC International Property Maintenance Code; a written inspection report goes to the owner, the buyer and the Township Clerk","If the home is found unfit and is sold without the corrections, both the owner and the new occupant are subject to penalties"]$j$::jsonb, $j$[{"label":"Resale inspection (Township Code 137-6)","amount":"$75"},{"label":"Reinspection when the home is not ready or violations are not corrected","amount":"$25"}]$j$::jsonb, null, $t$https://www.newhanovertwp.com/construction$t$, $j$[{"url":"https://ecode360.com/7053849","label":"Official source (ecode360.com)"},{"url":"https://www.newhanovertwp.com/construction","label":"Official source (newhanovertwp.com)"},{"url":"https://www.newhanovertwp.com/departments","label":"Official source (newhanovertwp.com)"}]$j$::jsonb, $t$No person shall rent and/or resell to another person for occupancy any dwelling or dwelling unit for the purpose of living therein, nor shall any person rent and/or resell to another person for commercial purposes any commercial property for the purpose of conducting business therein, without first having had the premises to be let inspected by the Construction Official of the Township.$t$, $t$ea6cebc427dcf30fa2449fef0a28eb868d5d27fab17e1376f1bbc6dbe380bcb3$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-10-14","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":0,"fee_bad":0,"fee_unchecked":5,"quotes":13,"q_ok":6,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0325.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-10-14. Source: property/data/municipal-requirements/checked/0325.json$t$, true),
  ($t$0325$t$, $t$New Hanover Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Wrightstown Borough Bureau of Fire Prevention (the fire code enforcing agency for New Hanover Township) (town fire bureau)","Contact: James H Ingling, Fire Official (listed on the Township site as Fire Inspector, by appointment only) · 609-723-4450 x14 · wrightstownfirebureau@comcast.net","Apply: Request 10 or more days before the date the certificate is needed for the lowest fee.","How to apply: No form is posted online. Call the fire inspector, James Ingling, at 609-723-4450 x14 (by appointment only), or email the Wrightstown fire bureau. Fees under the Township fire code are paid to the Wrightstown Borough Bureau of Fire Prevention.","Fire official in the NJ state directory (town), updated 6/16/2026: James H Ingling · (609) 723-4450 · wrightstownfirebureau@comcast.net","Smoke alarm, carbon monoxide alarm (and, in the code text, portable fire extinguisher) certificate required under N.J.A.C. 5:70-2.3 before the change of occupant","Township Code 148 requires smoke detectors within 10 feet of sleeping areas","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, request received 10 days or more before needed (Township Code 98-9C)","amount":"$35"},{"label":"Request received 4 to 9 days before needed","amount":"$70"},{"label":"Request received 3 days or less before needed","amount":"$100"}]$j$::jsonb, null, $t$https://www.newhanovertwp.com/construction$t$, $j$[{"url":"https://ecode360.com/8144206","label":"Official source (ecode360.com)"},{"url":"https://www.newhanovertwp.com/construction","label":"Official source (newhanovertwp.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The local enforcing agency shall be the Wrightstown Borough Bureau of Fire Prevention and shall hereafter be referred to as the "Bureau" or "local enforcing agency."$t$, $t$a16846fb3410e79bf1247d63c762ab5ac21449ea188ed2dd18e5e48c2192c0d0$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-10-14","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":0,"fee_bad":0,"fee_unchecked":5,"quotes":13,"q_ok":6,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0325.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-10-14. Source: property/data/municipal-requirements/checked/0325.json$t$, true),
  ($t$0326$t$, $t$North Hanover Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per North Hanover Township. Confirm with the office if the buyer's lender or title company asks.","Contact: Robert Gancarz, Fire Official (Office of the Fire Marshal) · (609) 209-8345 · fireofficial@northhanovertwp.com","How to apply: No Township resale CO/housing inspection. The only resale inspection is the smoke and CO certificate from the Fire Official (see fire certificate).","Also: Rental only: landlord registration, insurance and lead-safe certificate: Rentals also need a Landlord Registration Form, proof of liability insurance, and a lead-safe certificate (lead inspection fee $200.00 + $20.00 through the Township). Not required for a sale to an owner-occupant."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://northhanovertwp.com/Fire%20Marshal/fire_marshal.html$t$, $j$[{"url":"https://northhanovertwp.com/Fire%20Marshal/Resale_and_Rental_Requirements_Rev_10-26_clean.pdf","label":"Official source (northhanovertwp.com)"},{"url":"https://northhanovertwp.com/Fire%20Marshal/fire_marshal.html","label":"Official source (northhanovertwp.com)"}]$j$::jsonb, $t$Only one inspection is required for a resale in North Hanover Township:$t$, $t$e3061e76a1043d65967179f3f32c79ba49e0027bb0f6336036e7666908cc5752$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":12,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0326.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0326.json$t$, true),
  ($t$0326$t$, $t$North Hanover Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: North Hanover Township Office of the Fire Marshal (Fire Official) (town fire bureau)","Contact: Robert Gancarz, Fire Official / Fire Marshal · (609) 209-8345 · fireofficial@northhanovertwp.com","Apply: Apply more than 10 business days before the change of occupant for the lowest fee.","How to apply: Fill out the 'Application for Certificate of Smoke Detector, Carbon Monoxide and Fire Extinguisher Compliance' (in the Resale & Rental Requirements packet, Rev 10/26) and submit it with the fee to schedule. Check or cash, payable to North Hanover Township. Office of the Fire Marshal, 41 Schoolhouse Road, Wrightstown, NJ 08562. A failed inspection means a reinspection and an additional fee.","Fire official in the NJ state directory (town), updated 7/22/2026: Robert E Gancarz · (609) 758-2522 · Rgancarz@jacobstownfire.org","All detectors must be less than 10 years old","Smoke alarms on every level including the basement, and within 10 feet of sleeping room doors","Homes built before 1978: battery alarms must be 10-year sealed units or the inspection fails","Do not replace hardwired smoke alarms with battery alarms; replace bad interconnected alarms with compatible ones","Test all smoke detectors before the inspection date","CO alarm required if the home has any fuel-burning appliance or an attached garage: on each sleeping level, in hallways near bedrooms (electric or battery)","No fire extinguisher required (form says the State and the Township no longer require one)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received more than 10 business days before change of occupant","amount":"$45.00"},{"label":"Request received 4 to 10 business days before change of occupant","amount":"$90.00"},{"label":"Request received fewer than 4 business days before change of occupant","amount":"$161.00"}]$j$::jsonb, $t$https://northhanovertwp.com/Fire%20Marshal/Resale_and_Rental_Requirements_Rev_10-26_clean.pdf$t$, $t$https://northhanovertwp.com/Fire%20Marshal/fire_marshal.html$t$, $j$[{"url":"https://northhanovertwp.com/Fire%20Marshal/Resale_and_Rental_Requirements_Rev_10-26_clean.pdf","label":"Official source (northhanovertwp.com)"},{"url":"https://northhanovertwp.com/Fire%20Marshal/fire_marshal.html","label":"Official source (northhanovertwp.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Fill out the application form and submit along with the $45.00 fee to schedule the Smoke & CO certification.$t$, $t$8a1a2c6ef6f967566a482669b86332ab9ea1fff08b2f3e2739b7a665efafad85$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":12,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0326.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0326.json$t$, true),
  ($t$0327$t$, $t$Palmyra Borough$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy for Sale (Sales C.O.), resale Housing Code inspection$t$, $j$["Issued by: Borough of Palmyra Department of Housing (Housing Official)","Contact: Tracy Kilmer, Housing Official (also Fire Marshal) · 856-829-1096 · tkilmer@boroughofpalmyra.com","Apply: Pay the fee before the inspection is scheduled. By ordinance the Borough schedules the inspection no later than 7 business days after the application and fee; an inspection within 5 business days costs $50 extra and within 3 business days $100 extra. Allow 48 hours after the inspection for the report.","How to apply: Fill out the Resale Inspection Application for Certificate of Occupancy (one per unit) and turn it in at Borough Hall, 20 W. Broad Street, with the $125.00 fee payable to the Borough of Palmyra (check or cash). Then call (856) 829-1096 to schedule. Palmyra Harbour condominiums use a separate application.","Valid for: Not stated. If the home fails, a Temporary Sales C.O. may allow occupancy for up to 60 days (extendable by up to 30 days) when the violations do not threaten health or safety.","Review of required permits along with the inspection","Interior: structural members, interior surfaces, lead-based paint, stairs, railings (including attic and basement), handrails and guards","Anti-tip bracket on the oven","Exterior: paint, street numbers (Arabic numerals at least 3 inches high), foundation, walls, roof, gutters and downspouts, chimneys, porches, decks and stairs (sidewalks not inspected)","Windows open and stay open; no broken glass; insect screens; deadbolt locks on doors; basement hatch and basement window guards","Yard: sanitation, grading and drainage, weeds under 6 inches, no rodent harborage, no unregistered or junk vehicles, firewood stored off the ground, fences in good condition","Plumbing fixtures, water heater, exhaust fan and drainage in working order","Heat, HVAC, washer and dryer, flue and combustion air; electrical hazards, GFCI outlets where required, covers and switch plates, no open junction boxes","Borough green trash carts; no rubbish, no infestation","Means of egress, locked doors, emergency escape","Smoke detectors on each level including basement and walk-up attic, outside each sleeping area within 10 feet, not in the kitchen; 10-year sealed lithium battery type","CO detectors within 10 feet of sleeping areas","One 2A:10B:C fire extinguisher in the kitchen (not mounted), bought within a year with receipt or tagged (January 2022 checklist still lists it)","Smoke/CO certificate under N.J.A.C. 5:70-2.3 is also required before any sale (separate Fire Marshal inspection)","Also: Flood risk disclosure: The Borough's 'Resale/Rental Additional Requirements' form: since March 20, 2024 sellers must give the buyer the flood risk information (Property Condition Disclosure Statement: Flood Risk Notice, N.J.S.A. 46:8-50) before the buyer is bound by the contract.","Also: Open permits: A review of required permits is done with the CO inspection.","Also: Seller age or disability exception: If a seller is 65 or older, totally disabled, or has been in a care facility at least 30 days before the sale, the buyer may occupy for up to 180 days before the Sales C.O. is issued; the smoke/CO certificate is still needed first."]$j$::jsonb, $j$[{"label":"Resale inspection for Certificate of Occupancy, per unit","amount":"$125.00"},{"label":"Per unit (separate application for each unit)","amount":"$125"},{"label":"Certificate of Occupancy inspection on home resale (Borough web page)","amount":"$125.00"},{"label":"Expedited inspection within five business days (added to the base fee)","amount":"$50"},{"label":"Expedited inspection within three business days (added to the base fee)","amount":"$100"},{"label":"Each additional inspection after the first reinspection","amount":"$25"}]$j$::jsonb, $t$https://boroughofpalmyra.com/Documents/Government/Forms/Resale-Inspection-App.pdf?t=202502101114010$t$, $t$https://boroughofpalmyra.com/government/rental_unit_certificate_of_occupancy.php$t$, $j$[{"url":"https://boroughofpalmyra.com/government/rental_unit_certificate_of_occupancy.php","label":"Official source (boroughofpalmyra.com)"},{"url":"https://boroughofpalmyra.com/departments/code_enforcement.php","label":"Official source (boroughofpalmyra.com)"},{"url":"https://boroughofpalmyra.com/Documents/Government/Forms/Resale-Inspection-App.pdf?t=202502101114010","label":"Official source (boroughofpalmyra.com)"},{"url":"https://boroughofpalmyra.com/Documents/Government/Forms/CO-Checklist-2022.pdf?t=202502101113570","label":"Official source (boroughofpalmyra.com)"},{"url":"https://ecode360.com/30610412","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Attention Homeowners: thinking of selling your home? Effective April 1, 2014, Certificate of Occupancy inspections (on existing home re-sales) are now required.$t$, $t$4067afac33c2ec99159db2472f77a3f2b551d6ace1488c2033e48a4477812b30$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":6,"fee_bad":0,"fee_unchecked":3,"quotes":24,"q_ok":14,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/0327.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0327.json$t$, true),
  ($t$0327$t$, $t$Palmyra Borough$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Palmyra Bureau of Fire Prevention (Borough Fire Marshal) (town fire bureau)","Contact: Tracy Kilmer, Fire Marshal (Fire Official; also Housing Official and Fire Sub Code Official) · (856) 829-1096 · tkilmer@boroughofpalmyra.com","Apply: Fee depends on how many days before settlement/change of occupancy the inspection is requested: more than 10 days for the lowest fee. Inspections Monday to Thursday, 9:00am to 12 noon. A new application is needed if the change of occupancy does not happen within six months (Borough Code).","How to apply: There is no written application. Call the Fire Marshal's Office at (856) 829-1096 to schedule the smoke/CO inspection (Monday to Thursday, 9:00am to 12 noon). No fee is charged for a second reinspection. This is separate from the $125 Sales C.O. housing inspection.","Fire official in the NJ state directory (town), updated 1/23/2023: Tracy L Kilmer · (856) 829-1096 · tkilmer@boroughofpalmyra.com","Battery or hard-wired smoke detector on each level (minimum); hard-wired systems must work","Smoke detectors over 10 years old will not pass; resale/rental battery alarms must be 10-year sealed units","No detector in the kitchen area","Smoke detector and carbon monoxide detector outside each sleeping area","Third floor or attic with walk-up steps needs a smoke and CO detector, used or not","One ABC 2A:10B:C portable fire extinguisher in the kitchen, tagged within the year or with a receipt showing purchase within a year; need not be mounted (Borough page still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, requested more than 10 days before settlement","amount":"$45.00"},{"label":"Requested 4 to 10 days before settlement","amount":"$90.00"},{"label":"Requested less than 4 days before settlement","amount":"$161.00"}]$j$::jsonb, null, $t$https://boroughofpalmyra.com/government/rental_unit_certificate_of_occupancy.php$t$, $j$[{"url":"https://boroughofpalmyra.com/government/rental_unit_certificate_of_occupancy.php","label":"Official source (boroughofpalmyra.com)"},{"url":"https://ecode360.com/11283250","label":"Official source (ecode360.com)"},{"url":"https://boroughofpalmyra.com/departments/fire_marshal.php","label":"Official source (boroughofpalmyra.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$If you are selling or changing occupancy of your one- or two-family dwelling then a Certificate of Smoke Detector/Carbon Monoxide Alarm and Fire Extinguisher is required.$t$, $t$83ef39de602d590fec0410a5df1f29c1ab57f739814013cfe5a6db977f90b3a5$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":6,"fee_bad":0,"fee_unchecked":3,"quotes":24,"q_ok":14,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/0327.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0327.json$t$, true),
  ($t$0328$t$, $t$Pemberton Borough$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy (resale / change of ownership), Borough Code Chapter 117 Article II$t$, $j$["Issued by: Borough of Pemberton Code Enforcement Official (Department of Inspections)","Contact: 609-894-8222","Apply: By ordinance the certificate is granted or denied within 10 business days of the application.","How to apply: Download the Re-Sale Inspection Form (Certificate of Occupancy Inspection Application, a Word file) from the Borough Forms page, fill in block, lot, location, owner and buyer, and submit it with the fee to the Department of Inspections, Borough Hall, 50 Egbert St., Pemberton, NJ 08068. The office-use box lists check, cash or credit card. The fee is nonrefundable and is paid when the application is filed. Call the Borough at 609-894-8222.","Valid for: 60 days (Borough Code §117-12)","Home and premises must comply with the current International Property Maintenance Code and the Borough's health, sanitation, maintenance and occupancy ordinances"]$j$::jsonb, $j$[{"label":"Initial resale CO inspection (application form, created November 2024)","amount":"$100"},{"label":"Re-inspection (application form, created November 2024)","amount":"$75"}]$j$::jsonb, $t$https://www.pembertonborough.us/uploads/3/4/2/1/34215036/resale_inspection_application.docx$t$, $t$https://www.pembertonborough.us/forms.html$t$, $j$[{"url":"https://www.pembertonborough.us/forms.html","label":"Official source (pembertonborough.us)"},{"url":"https://www.pembertonborough.us/uploads/3/4/2/1/34215036/resale_inspection_application.docx","label":"Official source (pembertonborough.us)"},{"url":"https://ecode360.com/11295499","label":"Official source (ecode360.com)"},{"url":"https://www.pembertonborough.us/contact-us.html","label":"Official source (pembertonborough.us)"}]$j$::jsonb, $t$Re-Sale Inspection Form$t$, $t$bdafdb7a4717a0ea15104b0ca782b155a9603b02c783e3abcb34d4d16403a8e8$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":8,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0328.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0328.json$t$, true),
  ($t$0328$t$, $t$Pemberton Borough$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (State is the fire code enforcing agency for Pemberton Borough) (NJ DCA, state)","Contact: Louis Kilmer, Deputy Division Director · (609) 633-6106 · BFCE_CSDCMAC@dca.nj.gov","Apply: Apply more than 10 business days before the closing date for the lowest fee.","How to apply: Apply online through the NJ DCA Division of Fire Safety smoke certificate application (Fire Solutions portal). Pay by e-check or credit card when applying; the certificate is emailed once the fee is paid and any required inspection is done. Questions: Bureau of Fire Code Enforcement, (609) 633-6106.","Fire official in the NJ state directory (NJ DCA, state), updated 8/17/2026: Louis Kilmer · (609)633-6132","Smoke alarms and carbon monoxide alarms as required by N.J.A.C. 5:70-4.19 (state certificate, now called the Certificate of Smoke Alarm, Carbon Monoxide Alarm, and Secondary Power Source Identification Label Compliance); homes with a generator, solar or battery storage need the power source label","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"More than 10 business days before the change of occupant (state fee, N.J.A.C. 5:70-2.9(d))","amount":"$45.00"},{"label":"4 to 10 business days before the change of occupant (state fee)","amount":"$90.00"},{"label":"Fewer than 4 business days before the change of occupant (state fee)","amount":"$161.00"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/offices/bfce.shtml","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/codes/regulations/r.2018%20d.074%20(50%20n.j.r.%20729(a)).pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$S Pemberton Borough$t$, $t$acfa4b6ae8d8217ee8d3e3ee6b80866c4475e83df61510244a0f983533583840$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":8,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0328.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0328.json$t$, true),
  ($t$0329$t$, $t$Pemberton Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy Transfer (Resale Application / housing inspection)$t$, $j$["Issued by: Pemberton Township Code Enforcement Division (Housing Code Official), Department of Community Development","Contact: Wendy Jones, Code Enforcement Division (title not published) · 609-894-3376 · wjones@pemberton-twp.com","Apply: By ordinance the Housing Officer inspects within 10 working days of a complete application with the fee. Nothing is scheduled until the application is complete and paid.","How to apply: Download the Resale Application (dated 04.29.26) from the Code Enforcement/Housing Forms page. Fill it out completely and submit it with the $150 fee to the Housing Code Official's office in the Municipal Building, 500 Pemberton-Browns Mills Road (the checklist says payment goes to the cashier's office). Inspectors in the field do not accept applications or fees, and nothing is scheduled until the application is complete and paid. If the buyer is taking responsibility for the certificate, notify the office in writing before it is issued.","Valid for: The application expires 60 days after it is filed and cannot be transferred. A temporary certificate for 60 days may be issued when only non-life-threatening repairs remain. How long the certificate itself is valid is not stated.","House number on the dwelling, reflective, at least 3.5 inches high and readable from the street","Fences and pool areas with self-latching, outward-swinging gates (fence at least 48 inches, latch at least 54 inches)","Landings and porches 30 inches or higher need a guard rail at least 36 inches high with openings no wider than 4 inches","Stairways, decks, porches and balconies structurally sound; handrail on any stair with 4 or more risers","No broken or missing glass; windows open, lock and have screens; egress windows open easily","Basement outside entrances kept tight against pests and water","Anti-tilt device on the stove; all utilities on at the time of inspection","Smoke alarm on every level, in every bedroom and outside each sleeping area (form says battery operated)","Carbon monoxide alarm near sleeping areas if the home has a fuel-burning appliance or attached garage","ABC fire extinguisher, 5 to 10 lb, mounted in a visible, convenient spot (April 2026 form still lists it)","Bathroom window or exhaust fan vented outside","Mechanical equipment (exhaust fans, sump pumps, wood stoves, fireplaces) safe and working","No electrical hazards: no open junction boxes, taped splices or extension-cord wiring; service wire in sound condition","GFCI protection for pools, spas, exterior and garage outlets, within 5 feet of water, and at kitchen and bath counters","Certifications may be required for roof, electrical, structural or heating items","Septic: report from a NJ licensed independent inspection company showing the septic system meets Burlington County Health Department / NJDEP standards (properties on septic)","Private well: compliance with the Private Well Testing Act; deficiencies must be fixed before transfer (properties on wells)","Public sewer or water: give the account number with the application","Also: Tax, water, sewer and solid waste accounts paid; liens checked: The Resale Application has Tax Office and Public Works sign-off lines: liens checked, taxes paid, solid waste, water and sewer accounts paid, and sewer/water units billed.","Also: Septic inspection and well testing: Properties on septic must submit a report from a NJ licensed independent inspection company showing the system meets county/NJDEP standards; properties on private wells must comply with the Private Well Testing Act and fix any deficiencies before transfer. Properties on public sewer or water give the account number.","Also: Open permits, code violations and vacant property fees: Housing Office checks open construction permits, open code violations and vacant property registration fees before issuing.","Also: Buyer assuming the certificate: The buyer may take over the seller's duty to obtain the certificate with a written waiver filed with the Housing Officer before the certificate is issued."]$j$::jsonb, $j$[{"label":"Resale inspection (initial inspection)","amount":"$150.00"},{"label":"Each reinspection","amount":"$50.00"}]$j$::jsonb, $t$https://www.pemberton-twp.com/04.29.26%20Resale%20Application.pdf?t=202605041545530$t$, $t$https://www.pemberton-twp.com/departments/community_development/code_enforcement_division/index.php$t$, $j$[{"url":"https://www.pemberton-twp.com/04.29.26%20Resale%20Application.pdf?t=202605041545530","label":"Official source (pemberton-twp.com)"},{"url":"https://www.pemberton-twp.com/departments/community_development/code_enforcement_division/code_enforcement_forms.php","label":"Official source (pemberton-twp.com)"},{"url":"https://www.pemberton-twp.com/departments/community_development/code_enforcement_division/index.php","label":"Official source (pemberton-twp.com)"},{"url":"https://ecode360.com/37580800","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$A Certificate of Occupancy Transfer is required in the Township of Pemberton EACH time a residential dwelling unit changes occupant.$t$, $t$7d6ca9d08aed7b2a6d2a4e7e3d5242b9576646c218ea851e332ec12599b90400$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":20,"q_ok":13,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0329.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0329.json$t$, true),
  ($t$0329$t$, $t$Pemberton Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Not confirmed. Likely Pemberton Township Code Enforcement Division, which checks smoke alarms, CO alarms and the extinguisher under N.J.A.C. 5:70 during the Certificate of Occupancy Transfer…","Contact: Wendy Jones, Code Enforcement Division (title not published) · 609-894-3376 · wjones@pemberton-twp.com","How to apply: No separate smoke/CO certificate application was found. The township CO Transfer checklist covers smoke alarms, CO alarms and the extinguisher. Call Code Enforcement at 609-894-3376 to confirm whether the CO Transfer also serves as the state smoke/CO certificate.","Fire official in the NJ state directory (NJ DCA, state), updated 6/16/2026: Louis Kilmer · (609)633-6132","Smoke alarm on every level, in every bedroom and outside each sleeping area","Carbon monoxide alarm near sleeping areas (homes with a fuel-burning appliance or attached garage)","ABC fire extinguisher, 5 to 10 lb, mounted in a visible, convenient location (still on the April 2026 township checklist)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.pemberton-twp.com/departments/community_development/code_enforcement_division/index.php$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.pemberton-twp.com/04.29.26%20Resale%20Application.pdf?t=202605041545530","label":"Official source (pemberton-twp.com)"},{"url":"https://ecode360.com/37580800","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/11299114","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$S Pemberton Township$t$, $t$6631ef4cc93d2a6f5d9c409edbac0489ead1801d1306ee33e0d8461adbee9306$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":20,"q_ok":13,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0329.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0329.json$t$, true),
  ($t$0330$t$, $t$Riverside Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale Certificate of Occupancy$t$, $j$["Issued by: Riverside Township Housing Office (inspections arranged through the Construction Office; the Housing Office page lists Cinnaminson Fire Department as the inspectors)","Contact: 856-461-1460 · housing@riversidetwp.org","Apply: By ordinance the inspection is made within 10 business days of a complete application.","How to apply: Download the Application for Resale (April 2025 version) from the Housing Office page, fill it out, and email it to schedule the inspection. The Housing Office page says to arrange inspections through the Construction Office at housing@riversidetwp.org; the application form itself says inspection requests must be emailed to acosello@riversidetwp.org. The $125 per unit fee is printed on the form. Payment method is not stated.","Valid for: 60 days from the date of issuance (Housing Office page)","Exterior: driveway and walks without cracks or sinking sections; yard free of high grass, trash and debris","Windows not broken or cracked, able to open and stay up; screens in place without holes","Roof, siding, gutters, downspouts and foundation in good repair; peeling paint removed","Visible house number (and unit numbers on each unit)","Doors open and close properly; double-key deadbolts not permitted","Exterior wiring in good condition and GFI outlets near water","Converted garages may need permits; garage separation needs drywall and a fire-rated or solid door","Pools safeguarded and bonded; pool gates and fencing self-closing or self-latching","Interior walls, ceilings and floors in good condition; all lights, switches and outlets work with cover plates","Handrails on all staircases, including the open side","Working stove and oven with anti-tip device; range hood or exhaust fan","Hot and cold water without leaks; drains flow freely","Smoke alarms on each floor; smoke and CO alarms within 10 feet of bedrooms (10-year battery recommended)","Electric panel covered with working, labeled breakers; water heater with relief pipe","Fire extinguisher (checklist says \"210ABC\") mounted on the kitchen wall no higher than 5 feet (2019 checklist)","Also: Resale Affidavit if the buyer takes on repairs: A notarized Resale Affidavit lets the buyer accept responsibility for noted violations, but it is not a substitute for the Certificate of Occupancy: all repairs must be completed, reinspected and approved before the property can be occupied.","Also: Rental registration if the buyer will rent it out: The resale application asks the proposed use (owner occupy, rental, renovate to sell); rental and vacant properties must be registered (contact jransburgh@riversidetwp.org per the form)."]$j$::jsonb, $j$[{"label":"Resale inspection, per unit","amount":"$125.00"},{"label":"Second reinspection and later (third inspection overall)","amount":"$50"},{"label":"Fifth reinspection and later","amount":"$100"},{"label":"New inspection fee if more than 60 days pass between the first and second inspection, per unit","amount":"$125"}]$j$::jsonb, $t$https://riversidetwp.org/wp-content/uploads/2025/04/2APPLICATION-FOR-RESALE.pdf$t$, $t$https://riversidetwp.org/housing-office/$t$, $j$[{"url":"https://riversidetwp.org/housing-office/","label":"Official source (riversidetwp.org)"},{"url":"https://riversidetwp.org/wp-content/uploads/2025/04/2APPLICATION-FOR-RESALE.pdf","label":"Official source (riversidetwp.org)"},{"url":"https://riversidetwp.org/wp-content/uploads/2021/11/1HOUSING-INSPECTION-CHECKLIST-Copy.pdf","label":"Official source (riversidetwp.org)"},{"url":"https://ecode360.com/15633681","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/15622849","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$A Certificate of Occupancy is required prior to the sale of any property within the Township.$t$, $t$8fdc0e8e8a7f0c3675dade66582e6412747d7d520987d98fb247bfd2020a18f6$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":1,"fee_bad":0,"fee_unchecked":3,"quotes":18,"q_ok":12,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0330.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0330.json$t$, true),
  ($t$0330$t$, $t$Riverside Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Riverside Township Fire Official (municipal fire code enforcing agency) (town fire bureau)","Contact: Robert Yearly, Fire Official; Fire Subcode Official, Fire Inspector · 856-461-1460","How to apply: No separate smoke/CO certificate form or fee was found on the township website. The state directory lists Riverside Township, 237 S. Pavilion Ave, (856) 461-1460 for smoke detector compliance. The resale housing inspection also checks smoke alarms, CO alarms and the extinguisher. Call 856-461-1460 to confirm how the certificate is issued.","Fire official in the NJ state directory (town), updated 3/5/2026: Robert Yearly · (856) 461-1460 · robertyearly@comcast.net","Smoke alarms on each floor, and smoke and CO alarms within 10 feet of bedrooms; 10-year battery recommended (township 2019 housing checklist)","Fire extinguisher (checklist says \"210ABC\") mounted on the wall in the kitchen no higher than 5 feet (2019 checklist)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://riversidetwp.org/construction-and-zoning-office/$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://riversidetwp.org/construction-and-zoning-office/","label":"Official source (riversidetwp.org)"},{"url":"https://riversidetwp.org/wp-content/uploads/2021/11/1HOUSING-INSPECTION-CHECKLIST-Copy.pdf","label":"Official source (riversidetwp.org)"},{"url":"https://ecode360.com/11338343","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$M Riverside Township$t$, $t$c1c2ac34e73b04c2179c10c7a04abefdfc8c3b0cf5964db42417aad5cbb803e0$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":1,"fee_bad":0,"fee_unchecked":3,"quotes":18,"q_ok":12,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0330.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0330.json$t$, true),
  ($t$0332$t$, $t$Shamong Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Conformity (Residential Resale Certificate / property maintenance certificate)$t$, $j$["Issued by: Shamong Township Construction Office (Building Code, Construction Permits & Zoning)","Contact: Kevin Bagnell, Construction Permit/Resale Inspector · 609-268-2377 x305 · inspections@shamong.net","Apply: Give 14 days notice when scheduling the inspection. By ordinance the inspection is done and a certificate or violation notice issued within 10 days of the application. Inspections are done Tuesdays and Thursdays, 1:00 PM to 5:00 PM.","How to apply: Apply online with the township's Residential Resale/Rental Certificate application (GovPilot, linked from the Building Code page) and pay by credit card, or use the Residential Re-Sale Inspection PDF with a check payable to Township of Shamong, mailed or brought to the Construction Office, 105 Willow Grove Road, Shamong, NJ 08088. Give 14 days notice when scheduling. Questions go to inspections@shamong.net or (609) 268-2377 x305.","Valid for: If the ownership change does not happen within six months, a new application is required","Smoke alarm on each floor, including the basement (not unfinished attic or crawl space)","Smoke and carbon monoxide alarm within 10 feet of all bedrooms","House numbers on the front of the house or end of the driveway, at least 3 inches, lighted or reflective","Reflective house numbers on both sides of the mailbox","Pool and hot tub enclosures up to code","Steps and railings stable and secure","Chimney caps and spark arrestor installed","Visible, mounted 2A10BC fire extinguisher in the kitchen (January 2024 form)","All construction permits closed before the inspection is completed","Also: All construction permits closed: All construction permits must be closed before the resale inspection can be completed.","Also: Buyer purchasing \"as is\": If the buyer is purchasing the property as is, the township needs a notarized letter saying so; no certificate is issued without it."]$j$::jsonb, $j$[{"label":"Residential re-sale inspection","amount":"$50.00"},{"label":"Re-inspection","amount":"$25.00"}]$j$::jsonb, $t$https://main.govpilot.com/web/public/9198db8d-306_Rental-Resale-SHAMONG-TWP?uid=7741&ust=NJ&pu=1&id=0$t$, $t$https://www.shamong.net/department_contacts__hours/building_code_construction_permits__zoning/index.php$t$, $j$[{"url":"https://www.shamong.net/Documents/Department%20Contacts%20%20Hours/Building%20Code/Residential%20Re-Sale%20Inspection%20Form.pdf?t=202401051312280","label":"Official source (shamong.net)"},{"url":"https://www.shamong.net/department_contacts__hours/building_code_construction_permits__zoning/index.php","label":"Official source (shamong.net)"},{"url":"https://ecode360.com/11354302","label":"Official source (ecode360.com)"},{"url":"https://main.govpilot.com/web/public/9198db8d-306_Rental-Resale-SHAMONG-TWP?uid=7741&ust=NJ&pu=1&id=0","label":"Official source (main.govpilot.com)"}]$j$::jsonb, $t$RESIDENTIAL RE-SALE INSPECTION$t$, $t$55b752202e7e3bf81643ab27e8f99c7b3173cc503a19547715d5dae55a3b409c$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":22,"q_ok":17,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0332.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0332.json$t$, true),
  ($t$0332$t$, $t$Shamong Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Shamong Township Construction Office (designated for smoke detector compliance; NJ DCA is the fire code enforcing agency) (town fire bureau)","Contact: Kevin Bagnell, Construction Permit/Resale Inspector · 609-268-2377 x305 · inspections@shamong.net","Apply: Give 14 days notice when scheduling","How to apply: Smoke alarms, CO alarms and the extinguisher are checked during the resale certificate inspection ($50, see the resale certificate section). No separate smoke certificate form or fee was found. Email inspections@shamong.net.","Fire official in the NJ state directory (NJ DCA, state), updated 6/16/2026: Louis Kilmer · (609)633-6132","Smoke alarm on each floor, including the basement (not unfinished attic or crawl space)","Smoke and CO alarm within 10 feet of all bedrooms","Visible, mounted 2A:10BC fire extinguisher in the kitchen (township PDF and online form still list it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.shamong.net/Documents/Department%20Contacts%20%20Hours/Building%20Code/Residential%20Re-Sale%20Inspection%20Form.pdf?t=202401051312280$t$, $t$https://www.shamong.net/department_contacts__hours/building_code_construction_permits__zoning/index.php$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.shamong.net/Documents/Department%20Contacts%20%20Hours/Building%20Code/Residential%20Re-Sale%20Inspection%20Form.pdf?t=202401051312280","label":"Official source (shamong.net)"},{"url":"https://www.shamong.net/department_contacts__hours/building_code_construction_permits__zoning/index.php","label":"Official source (shamong.net)"},{"url":"https://ecode360.com/11354302","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$S Shamong Township$t$, $t$e14c19595c0b78733048e4f18029db69c83039e893d13f5965b3201fb3906808$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":22,"q_ok":17,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0332.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0332.json$t$, true),
  ($t$0333$t$, $t$Southampton Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Resale Inspection / Resale Certificate$t$, $j$["Issued by: Southampton Township Office of Construction, Zoning and Land Development","Contact: Tom Boyd, Construction Official, Building Subcode Official (handles resale inspections) · 609-859-2786 · tboyd@southamptonnj.org","Apply: Application and fee must be received at least 14 days before the settlement date","How to apply: Download the 2026 Residential Resale Inspection Application from the Construction & Zoning page and submit it with the fee to the Construction Office, 5 Retreat Road, at least 14 days before settlement. Questions and inspection requests go to construction@southamptonnj.org. Payment method is not stated on the form.","Valid for: Not stated","Smoke alarms on each level of the home and within 10 feet of any sleeping room","Carbon monoxide alarms within 10 feet of any sleeping room","House number at least 3 inches, visible from the street","All utilities on","Guard rails and handrails secure and steady, no missing spindles","Yard free of trash, grass cut, brush and weeds not overgrown","Siding, soffit and fascia secure","Doors and windows in good working condition","No open electric outlets, switches or lights; electric panel cover in place with no missing blanks","No open holes in walls or ceilings","Appliance venting in place and free of defects","Burlington County recycling receptacle stays at the property","Also: County recycling receptacle: The Burlington County recycling receptacle must stay at the property; contact the Recycling Coordinator (recyclingcoordinator@southamptonnj.org, 609-859-5574) if one is needed.","Also: Utilities on for inspection: All utilities must be on for the resale inspection."]$j$::jsonb, $j$[{"label":"Resale inspection, per unit","amount":"$50.00"},{"label":"Reinspection, per unit","amount":"$25.00"}]$j$::jsonb, $t$https://www.southamptonnj.org/Construction%20&%20Zoning/Forms/Resale%20Inspection%20Application%202026%20New.pdf?t=202607210900510$t$, $t$https://www.southamptonnj.org/government/construction___zoning.php$t$, $j$[{"url":"https://www.southamptonnj.org/Construction%20&%20Zoning/Forms/Resale%20Inspection%20Application%202026%20New.pdf?t=202607210900510","label":"Official source (southamptonnj.org)"},{"url":"https://www.southamptonnj.org/government/construction___zoning.php","label":"Official source (southamptonnj.org)"},{"url":"https://ecode360.com/29792304","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$RESIDENTIAL RESALE INSPECTION APPLICATION$t$, $t$4c38589be270eca81d0f54b598c600cc25b88c1b6c7659c23cd08c1bec2653f6$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":16,"q_ok":11,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0333.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0333.json$t$, true),
  ($t$0333$t$, $t$Southampton Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Southampton Township Construction Office (township building inspector issues the smoke alarm certificate under Township Code §8-8; NJ DCA is the fire code enforcing agency) (town fire bureau)","Contact: Tom Boyd, Construction Official, Building Subcode Official (handles resale inspections) · 609-859-2786 · tboyd@southamptonnj.org","Apply: At least 14 days before settlement","How to apply: Smoke and CO alarms are checked during the Residential Resale Inspection (one $50 per unit application, see the resale certificate section); file the application with the fee at least 14 days before settlement. No separate smoke certificate form or fee was found.","Fire official in the NJ state directory (NJ DCA, state), updated 6/25/2026: Louis Kilmer · (609)633-6132","Smoke alarms on each level and within 10 feet of any sleeping room","CO alarms within 10 feet of any sleeping room","The July 2026 township form does not list a fire extinguisher","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.southamptonnj.org/Construction%20&%20Zoning/Forms/Resale%20Inspection%20Application%202026%20New.pdf?t=202607210900510$t$, $t$https://www.southamptonnj.org/government/construction___zoning.php$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.southamptonnj.org/Construction%20&%20Zoning/Forms/Resale%20Inspection%20Application%202026%20New.pdf?t=202607210900510","label":"Official source (southamptonnj.org)"},{"url":"https://ecode360.com/29792304","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$S Southampton Township$t$, $t$eb26768c655ffc8eaee0b1bcad2189c15d2ebfd23cde2159b7dcd63692176f11$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":16,"q_ok":11,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0333.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0333.json$t$, true),
  ($t$0334$t$, $t$Springfield Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate for Change in Occupancy or Ownership (Resale/Rental Certificate)$t$, $j$["Issued by: Springfield Township Construction Office","Contact: Joseph LaRocca, Construction Official, Building and Fire Subcode Official · 609-723-2464 · jlarocca@springfieldtownshipnj.org","How to apply: Download the Resale/Rental Application (Rev. Mar 2025) from the Construction Office resources, check \"Sale\", sign it, and submit it with a check or money order for $150.00 payable to \"Springfield Township\" to the Construction Office, 2159 Jacksonville-Jobstown Road, Jobstown, NJ 08041. The town code (Chapter 66) also asks for a written request giving the date the buyer takes occupancy and the buyer's name, plus a statement from the Tax Collector. The fee is non-refundable. Inspection results and the certificate are sent by email.","Smoke alarms on every level and outside each sleeping area: 10-year sealed battery alarms, or hardwired where required","Basement alarm at the bottom of the stairwell on the ceiling (not between joists); hallway alarms close to all bedrooms","Smoke alarms less than 10 years old (or not past the maker's expiration date) and working","Hardwired smoke alarms required by the building code cannot be replaced with battery alarms","Homes with a monitored low-voltage fire alarm system: have it tested by the alarm company before the inspection and bring the certification","CO alarm in the hallway close to all bedrooms, less than 10 years old, UL listed and working","Fire extinguisher rated 2A-10B:C, no more than 10 lb, within 10 feet of the kitchen in the path of egress, top no more than 5 feet above the floor, on the maker's bracket, not in a closet or behind a door; leave the manual for the new occupant (March 2025 checklist)","House numbers at least 3 inches, contrasting, permanently fixed to the house and visible from the street","No open Springfield Township construction permits; all permitted work finalized and passed","Statement from the Tax Collector submitted with the application; no certificate is issued if Township real estate taxes are due (town code Chapter 66)","Also: Tax Collector statement: A statement from the Tax Collector must go in with the application; no certificate for change in occupancy or ownership is issued if Township real estate taxes are due and owing (town code §66-1A(1)).","Also: Open construction permits closed: No outstanding Springfield Township construction permits; all permitted work must be finalized and passed before the resale inspection passes.","Also: Rental registration deactivated: If the property was a rental, the landlord registration is deactivated on the resale application."]$j$::jsonb, $j$[{"label":"Resale inspection (includes two inspections)","amount":"$150.00"},{"label":"Each additional inspection after the first two","amount":"$65.00"}]$j$::jsonb, $t$https://www.springfieldtownshipnj.org/index?i=8EdLWBbrPaZMTUQGXRxGse9maokNtDsfLztEPHsUFaDvE4IuruYbYfb5tm5ilT4t&rf=i$t$, $t$https://www.springfieldtownshipnj.org/constructionoffice$t$, $j$[{"url":"https://www.springfieldtownshipnj.org/constructionoffice","label":"Official source (springfieldtownshipnj.org)"},{"url":"https://www.springfieldtownshipnj.org/api/blob/viewBlob?rf=t&i=8EdLWBbrPaZMTUQGXRxGse9maokNtDsfLztEPHsUFaD%2FkDxkTbO4b1PLWTCA07hN","label":"Official source (springfieldtownshipnj.org)"},{"url":"https://www.springfieldtownshipnj.org/api/blob/viewBlob?rf=t&i=8EdLWBbrPaZMTUQGXRxGse9maokNtDsfLztEPHsUFaDvE4IuruYbYfb5tm5ilT4t","label":"Official source (springfieldtownshipnj.org)"},{"url":"https://app.membershipware.com/api/public/mwjsPeople?et=Jfp%252B3K9fyAYWIble3%252BR4eQ%3d%3d&eb=0xG5h%252BICHBzdF1eDwLDXRA%3d%3d","label":"Official source (app.membershipware.com)"},{"url":"https://ecode360.com/49052339","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/6393376","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$The Springfield Construction Office is responsible for construction permits, plan reviews, inspections, and Resale / Rental Certificates as allowed by the State of New Jersey and the Springfield Township code.$t$, $t$982cbc876cf5e8b0430e878918b5553e10102b611669fadb47774c8b6b5e5c0c$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":20,"q_ok":14,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0334.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0334.json$t$, true),
  ($t$0334$t$, $t$Springfield Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Springfield Township Construction Office (designated for smoke detector compliance; NJ DCA is the fire code enforcing agency) (town fire bureau)","Contact: Joseph LaRocca, Construction Official, Building and Fire Subcode Official · 609-723-2464 · jlarocca@springfieldtownshipnj.org","How to apply: The smoke alarm, CO alarm and extinguisher checks are part of the $150 resale inspection by the Construction Office; see the resale certificate section. No separate smoke certificate form or fee was found. The NJ DCA smoke certificate portal marks Springfield Township (Burlington) as smoke-certificate exempt, so do not apply to the state.","Fire official in the NJ state directory (NJ DCA, state), updated n/a: Louis Kilmer · (609)633-6132","10-year sealed battery smoke alarms (or hardwired as required) on every level and near all bedrooms; alarms under 10 years old","Hardwired alarms cannot be replaced with battery alarms","CO alarms under 10 years old in the hallway near all bedrooms","Fire extinguisher 2A-10B:C, 10 lb maximum, mounted within 10 feet of the kitchen, top no higher than 5 feet (March 2025 township checklist still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.springfieldtownshipnj.org/index?i=8EdLWBbrPaZMTUQGXRxGse9maokNtDsfLztEPHsUFaDvE4IuruYbYfb5tm5ilT4t&rf=i$t$, $t$https://www.springfieldtownshipnj.org/constructionoffice$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.springfieldtownshipnj.org/api/blob/viewBlob?rf=t&i=8EdLWBbrPaZMTUQGXRxGse9maokNtDsfLztEPHsUFaD%2FkDxkTbO4b1PLWTCA07hN","label":"Official source (springfieldtownshipnj.org)"},{"url":"https://ecode360.com/49052339","label":"Official source (ecode360.com)"},{"url":"https://firesolutions.dca.nj.gov/_odata/firedistricts","label":"Official source (firesolutions.dca.nj.gov)"}]$j$::jsonb, $t$S Springfield Township$t$, $t$af16bb78128f50b13bd6fcfbecd6f3915a633b4b3987dffba1a339beeef6df7c$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":20,"q_ok":14,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0334.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0334.json$t$, true),
  ($t$0336$t$, $t$Washington Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale Inspection Certificate$t$, $j$["Issued by: Washington Township Code Enforcement","Contact: Robert Henchy, III, Code Enforcement Officer · 609-965-3242 x253 · codeenforcement@wtbcnj.org","How to apply: Fill out the township Re-Sale Form (Code Enforcement; owner, block and lot, agent and settlement date) and return it to the Municipal Building, 2436 Route 563, Green Bank, Egg Harbor City, NJ 08215, with the fee. Payment method is not stated. Contact Code Enforcement at 609-965-3242 x253.","House number in Arabic numerals, at least 3 inches high, at least 30 inches above ground, not blocked by trees or shrubs, visible from the street","Any fence, deck, shed, or above-ground or in-ground pool built without zoning or construction permits will delay the certificate until corrected","Sidewalks must not be raised or broken","The form refers to an attached sheet of more inspected items; that sheet is not posted online","Also: Unpermitted structures: Fences, decks, sheds or pools built without zoning or construction permits must be corrected or abated before the Resale Inspection Certificate is issued."]$j$::jsonb, $j$[{"label":"Resale inspection","amount":"$150.00"},{"label":"Each re-inspection","amount":"$50.00"}]$j$::jsonb, $t$https://wtbcnj.org/wp-content/uploads/2026/08/0535_001.pdf$t$, $t$https://wtbcnj.org/code-enforcement-officer/$t$, $j$[{"url":"https://wtbcnj.org/wp-content/uploads/2026/08/Ordinance-2026-07-Adoption-Washington-Twp.pdf","label":"Official source (wtbcnj.org)"},{"url":"https://wtbcnj.org/wp-content/uploads/2026/09/8.4.2026-Regular.pdf","label":"Official source (wtbcnj.org)"},{"url":"https://wtbcnj.org/forms-applications/","label":"Official source (wtbcnj.org)"},{"url":"https://wtbcnj.org/wp-content/uploads/2026/08/0535_001.pdf","label":"Official source (wtbcnj.org)"},{"url":"https://wtbcnj.org/code-enforcement-officer/","label":"Official source (wtbcnj.org)"}]$j$::jsonb, $t$AMENDING CHAPTER 145 OF THE CODE OF THE TOWNSHIP OF WASHINGTON TO CREATE AN ARTICLE V ENTITLED RESALE OF PROPERTY$t$, $t$442c9e12463079d6ec7087362447b42a74bc5f453b5bbf59ce6e0c1b316477f0$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":0,"fee_bad":0,"fee_unchecked":2,"quotes":10,"q_ok":8,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0336.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0336.json$t$, true),
  ($t$0336$t$, $t$Washington Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Not confirmed: Washington Township (NJ DCA is the fire code agency but does not issue smoke certificates here)","Contact: 609-965-3242","How to apply: Call the Municipal Building at 609-965-3242 to ask which office issues the smoke alarm and carbon monoxide alarm certificate for a sale. The NJ DCA online smoke certificate portal marks Washington Township (Burlington) as smoke-certificate exempt, so the state does not take these applications.","Fire official in the NJ state directory (NJ DCA, state), updated 6/17/2026: Louis Kilmer · (609)633-6132","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://wtbcnj.org/$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://firesolutions.dca.nj.gov/_odata/firedistricts","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$S Washington Township$t$, $t$cd5d80122198b583561d0eae0f3a739273b188d8de6e34999ed24ba2469602f7$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":0,"fee_bad":0,"fee_unchecked":2,"quotes":10,"q_ok":8,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0336.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0336.json$t$, true),
  ($t$0337$t$, $t$Westampton Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Westampton Township. Confirm with the office if the buyer's lender or title company asks.","Contact: (609) 267-1891 ext. 101"]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.westamptonnj.gov/construction-code-enforcement-inspections/pages/resalerental-home$t$, $j$[{"url":"https://web.archive.org/web/20260530112936/https://www.westamptonnj.gov/construction-code-enforcement-inspections/pages/resalerental-home","label":"Official source (web.archive.org)"}]$j$::jsonb, $t$There is no Certificate of Occupancy (CO) required in Westampton Township. What is required is a Smoke Detector/Carbon Monoxide/Fire Extinguisher Inspection.$t$, $t$140a8fdefc684e96459d3ee87fcc995153a8825880afe50e515ecdb336929fc6$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":7,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0337.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0337.json$t$, true),
  ($t$0337$t$, $t$Westampton Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Westampton Township Emergency Services Bureau of Fire Prevention (WTES) (town fire bureau)","Contact: Vincent M Knott, Fire Official · 609-267-2041 (option 3 for the Fire Marshal) · firemarshal@wtes.us","Apply: Submit the request 3 to 4 weeks before settlement. The lowest fee applies when the request is received 14 calendar days or more before settlement.","How to apply: Request the inspection online with the WTES Formstack form, or call 609-267-2041 to set an appointment. Pay by check or money order payable to 'Westampton Township Emergency Services Bureau of Fire Prevention' at the time of inspection. Certificates are valid for 90 days.","Fire official in the NJ state directory (town), updated 5/18/2026: Vincent M Knott · (609) 267-2041 · Vknott@wtes.us","House numbers at least 4 inches high, contrasting color, permanently fixed to the house and visible from the street (mailbox or lamp post numbers not accepted)","Smoke alarm on every level; basement alarm at the bottom of the stairwell on the ceiling (not between joists)","Hallway smoke alarms within 10 feet of all bedroom doors; smoke alarms on the ceiling in each bedroom if the home was built after 1991","Smoke and CO alarms must be less than 10 years old and working; battery smoke alarms must be the 10-year sealed type; hard-wired alarms cannot be replaced with battery alarms","CO alarm in the hallway within 10 feet of all bedrooms (plug-in, battery or hard-wired accepted; not in switched outlets)","Homes with a low-voltage fire alarm system need the system tested and certified by an alarm contractor before the inspection, with the certificate shown to the inspector","Fire extinguisher still listed on the WTES page (2026): mounted on a bracket within 10 feet of the kitchen in the path of egress, minimum rating 2A-10B:C, under 10 pounds","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received 14 calendar days before settlement","amount":"$70.00"},{"label":"Request received 13 calendar days or less before settlement","amount":"$140.00"},{"label":"Request received 4 calendar days or less before settlement","amount":"$165.00"},{"label":"Re-inspection","amount":"$70.00"}]$j$::jsonb, $t$https://westamptonfire.formstack.com/forms/smoke_detector_inspection_application$t$, $t$https://www.westamptonfire.org/content/certificate/$t$, $j$[{"url":"https://www.westamptonfire.org/content/certificate/","label":"Official source (westamptonfire.org)"},{"url":"https://web.archive.org/web/20260530112936/https://www.westamptonnj.gov/construction-code-enforcement-inspections/pages/resalerental-home","label":"Official source (web.archive.org)"},{"url":"https://www.westamptonfire.org/content/ordinances/","label":"Official source (westamptonfire.org)"},{"url":"https://www.westamptonfire.org/content/fireprevention/","label":"Official source (westamptonfire.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://ecode360.com/8750039","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Requests must be submitted 3 to 4 weeks prior to the settlement date. For questions and to set an appointment call 609-267-2041.$t$, $t$7c7763eeaba9af7509c5adeb32d376e87f413ec39c7a2e86f50f92680b285494$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":7,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0337.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0337.json$t$, true),
  ($t$0338$t$, $t$Willingboro Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy (resale housing inspection)$t$, $j$["Issued by: Willingboro Township Inspections Department (Department of Code Enforcement and Inspections)","Contact: Shaleen Bolling-Gonzalez, Housing / Rental / Resales · 609-877-2200 ext. 1033","Apply: Town code: schedule the inspection at least 15 calendar days before settlement; requests 4 calendar days or less before settlement pay an extra $80. The township packet also advises scheduling within 30 days of settlement because the CO is good for 30 days. Violations must be reinspected within 30 days of the first inspection.","How to apply: Fill out the Resale Inspection Housing Application in the township's 'Moving' packet and submit it with the $150 fee to the Inspections Department, 1 Rev. Dr. Martin Luther King Jr. Drive, Willingboro. The form's office section lists check, cash or credit card. The Inspections page says resale/rental applications can also be submitted and paid online (the portal link is not shown on the page). The seller or agent can schedule the inspection; a lock box number lets the inspector enter. Give 24 hours notice to cancel or reschedule or the fee is still charged.","Valid for: 30 days","Township housing inspection of the whole house, inside and out; all violations corrected before the CO is issued","Exterior: driveway and walks free of cracks or raised sections; lawn, trash and debris cleaned up; fence stable; screens in windows (May 1 to Oct 1)","Roof: no missing or broken shingles, maximum 2 layers; siding and gutters in repair; peeling paint scraped and repainted","House number: 6 inch numbers on the building","Interior: walls, ceilings and floors in good repair; working lights, outlets and switches with cover plates; windows open and stay up; no double-keyed deadbolts","Kitchen and bath: working burners, plumbing without leaks, exhaust fan or window, cabinets in good condition","Handrails on all staircases; garage conversions may need permits","Smoke and CO detectors within 10 feet of bedrooms; smoke alarms must be ten-year sealed battery type","Portable fire extinguisher (still listed on the township checklist): at least 2:A:10B:C, no more than 10 lbs, mounted within 10 ft of the kitchen and not more than 5 ft above the floor","Electric service panel with covers, working and labeled breakers; water heater with pressure relief pipe and bonding","Original heating certificate from a Willingboro-registered heating contractor (valid 30 days)","Private sewer lateral video inspection report from a master plumber showing no repairs needed (valid 6 months)","Open construction permits must be passed and closed; work done without permits must be permitted","Copy of a current property survey (still asked for in the 2026 packet, although the code rule requiring it was repealed in 2020)","Also: Heating certificate: Original heating system certificate from a heating contractor on the township registered list, made not more than 30 days before the CO is issued (town code §199-8B), must be brought in to get the CO.","Also: Private sewer lateral inspection: Seller must hire a master plumber or utility contractor for a video inspection and certified Private Sewer Lateral Inspection Report (Ordinance 2021-13, Chapter 291). Repairs must be done before the CO; a satisfactory report is good for 6 months. Start once the home is listed, no later than the agreement of sale.","Also: Open permits: Open construction permits are checked and must have final inspections; work done without permits must be permitted. The CO will not be issued until all permits are passed and closed out.","Also: Property survey: The 2026 resale packet still asks for a copy of a current survey for all resales, although the code section that required it was repealed in 2020 (Ord. No. 2020-5). Ask the office whether it is still needed.","Also: Flood hazard letter: The resale CO includes a flood hazard letter and certificate of housing code along with the smoke detector certification.","Also: Certified tax search and added assessment: Certified tax search request goes to the Tax Collector with a $10.00 fee (per the packet form); see the Tax Assessor about added assessments for improvements."]$j$::jsonb, $j$[{"label":"Resale housing inspection (includes one re-inspection within 30 days)","amount":"$150.00"},{"label":"Reinspection (third inspection within 30 days)","amount":"$150"},{"label":"Expedited resale inspection (request received 4 calendar days or less before settlement), added to the regular fee","amount":"$80"}]$j$::jsonb, $t$https://www.willingboronj.gov/DocumentCenter/View/307/Resale-Application-2026-PDF$t$, $t$https://www.willingboronj.gov/243/Inspections-Code-Enforcement$t$, $j$[{"url":"https://www.willingboronj.gov/DocumentCenter/View/307/Resale-Application-2026-PDF","label":"Official source (willingboronj.gov)"},{"url":"https://www.willingboronj.gov/243/Inspections-Code-Enforcement","label":"Official source (willingboronj.gov)"},{"url":"https://www.willingboronj.gov/m/directory/department?did=20","label":"Official source (willingboronj.gov)"},{"url":"https://ecode360.com/15565809","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/15566992","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Did you know Willingboro Township requires all homes to be transferred or sold to have an inspection done by a Willingboro Township Housing Inspector.$t$, $t$01213a09050fa96f3db371ef54c516beb826776e9fcee964e723c37d49190895$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":20,"q_ok":8,"q_bad":0,"q_unchecked":12},"source":"property/data/municipal-requirements/checked/0338.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0338.json$t$, true),
  ($t$0338$t$, $t$Willingboro Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Willingboro Township Inspections Department (town fire bureau)","Contact: Dennis Tunstall, Director, Inspections · 609-877-2200 ext. 1214","How to apply: For a sale, the township's resale Certificate of Occupancy includes the smoke detector certification, so the $150 resale housing inspection covers it. The township also posts a separate Application for Certificate of Compliance (smoke detectors, CO alarms, fire extinguisher; $150) inspected by a township inspector; submit it to the Inspections Department, 1 Rev. Dr. Martin Luther King Jr. Drive, and give 24 hours notice to cancel or reschedule or the fee is forfeited.","Fire official in the NJ state directory (NJ DCA, state), updated 6/16/2026: Louis Kilmer · (609) 633-6132","Smoke detector on each level including basements (not attics or crawl spaces)","Smoke detector and CO alarm outside each separate sleeping area and within 10 feet of bedrooms","Battery smoke alarms must be the ten-year sealed type (township checklist)","The township forms (2026 Certificate of Compliance and the resale checklist) still require a fire extinguisher within 10 feet of the kitchen, rated at least 2:A:10B:C and no more than 10 lbs, mounted with the manufacturer bracket not more than 5 ft above the floor","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of Compliance (smoke, CO alarms and fire extinguisher) inspection, when applied for separately","amount":"$150.00"}]$j$::jsonb, $t$https://www.willingboronj.gov/DocumentCenter/View/308/Certificate-of-Compliance-2026-PDF$t$, $t$https://www.willingboronj.gov/245/Inspection-Forms$t$, $j$[{"url":"https://www.willingboronj.gov/DocumentCenter/View/308/Certificate-of-Compliance-2026-PDF","label":"Official source (willingboronj.gov)"},{"url":"https://www.willingboronj.gov/DocumentCenter/View/307/Resale-Application-2026-PDF","label":"Official source (willingboronj.gov)"},{"url":"https://www.willingboronj.gov/243/Inspections-Code-Enforcement","label":"Official source (willingboronj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://firesolutions.dca.nj.gov/_odata/firedistricts","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$A CERTIFICATE OF COMPLIANCE IS REQUIRED ON ALL HOMES BEING TRANSFERRED OR SOLD PRIOR TO OCCUPANCY$t$, $t$ebb230fc0c3d7b0b948ee1e8c9e1e96cb1ad7da5ad4696acd3d25cdef79daa26$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":20,"q_ok":8,"q_bad":0,"q_unchecked":12},"source":"property/data/municipal-requirements/checked/0338.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0338.json$t$, true),
  ($t$1312$t$, $t$Eatontown Borough$t$, $t$MONMOUTH$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy / Certificate of Continued Use (combined certificate of smoke alarm, carbon monoxide alarm and compliance, CSDCMAC)$t$, $j$["Issued by: Borough of Eatontown inspector (Housing Official, Code Enforcement Officer, Fire Marshal or Fire Inspector)","Contact: Nicholas Cosentino, Housing Officer · 732-389-7616 · housing@eatontownnj.com","Apply: Fees rise when the request is made 10 or fewer business days before the change of occupancy. All fees are paid with the application before any inspection.","How to apply: Apply in writing to the Borough inspector (Housing Division, 47 Broad Street, Eatontown) with the buyer's information and pay the fee with the application. The inspector issues the certificate if no violations exist; otherwise the owner is told in writing what must be fixed. No online application form was found; the Borough's new 'Thinking of Selling Your House?' page says 'Coming soon!'. Housing email: housing@eatontownnj.com.","Valid for: 60 days (Code §116-6B); the code also says CSDCMAC inspections are valid for six months","Inspection for fitness for habitation under Borough Code §116-8 before the home is sold","Any outstanding permit issues must be closed; Zoning Officer certifies compliance","Smoke detectors on each level and within 10 feet of sleeping quarters, working and under 10 years old; 10-year sealed battery units; AC powered units cannot be swapped for battery units","Carbon monoxide detectors within 10 feet of sleeping quarters, working, under 7 years old (standalone) or 10 years (combination)","Monitored fire alarm systems must be made available for testing, with a certificate of inspection","Checklist items include working doors and keyless deadbolts, GFCI in bathrooms, covered electrical boxes and plates, 4-inch house numbers, handrails on stairs over four risers, unbroken operable windows, safe sidewalk/driveway/apron/foundation, heating system and flue, water heater overflow pipe, metal dryer vent, minimum 60 amp service, sump pump on a dedicated receptacle","Application states the future owner's name and address and who will allow entry","Also: Open permits and zoning: Outstanding permit issues must be closed and the Zoning Officer must certify compliance before the certificate is issued. The Building / Construction page also asks that no closings be scheduled before final building inspections on open permits."]$j$::jsonb, $j$[{"label":"Certificate of occupancy and inspection (combined with smoke/CO certificate), one and two family, more than 10 business days before the change of occupancy","amount":"$100"},{"label":"One and two family, 4 to 10 business days before","amount":"$135"},{"label":"One and two family, fewer than 4 business days before","amount":"$200"},{"label":"Reinspection, each","amount":"$35"},{"label":"Transfer of residential properties (lawful two-family homes charged separately)","amount":"$200"},{"label":"Buyer backs out and a new buyer purchases before occupancy (updated application)","amount":"$35"}]$j$::jsonb, null, $t$https://www.eatontownnj.com/departments/building-construction$t$, $j$[{"url":"https://ecode360.com/7639663","label":"Official source (ecode360.com)"},{"url":"https://www.eatontownnj.com/departments/building-construction","label":"Official source (eatontownnj.com)"},{"url":"https://www.eatontownnj.com/thinking-of-selling-your-house","label":"Official source (eatontownnj.com)"}]$j$::jsonb, $t$Eatontown Borough shall perform inspections in accordance with the New Jersey Uniform Fire Code before any one- and two-family or attached single-family structure is sold, leased, or otherwise made subject to a change of occupancy for residential purposes.$t$, $t$f360123712b2c6b4808b120ba08cb37f8c46b86c86a23b0cca1a39eb0d5c3624$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":0,"fee_bad":0,"fee_unchecked":10,"quotes":15,"q_ok":7,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/1312.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1312.json$t$, true),
  ($t$1312$t$, $t$Eatontown Borough$t$, $t$MONMOUTH$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Eatontown Housing Division and Fire Prevention Bureau (combined certificate of occupancy and CSDCMAC) (town fire bureau)","Contact: Patrick A. Renaldi, Fire Marshal · 732-389-7620 · prenaldi@eatontownnj.com","Apply: Combined with the certificate of occupancy inspection; fee depends on business days before the change of occupancy.","How to apply: The smoke/CO certificate is not applied for separately: Eatontown issues one combined certificate after its habitability inspection (see resale certificate).","Fire official in the NJ state directory, updated 10/2/2024: Patrick Renaldi · (732) 389-7621 · prenaldi@eatontownnj.com","Smoke detectors on each level and within 10 feet of sleeping quarters, working and less than 10 years old","10-year sealed battery single station smoke alarms (ANSI/UL 217); AC powered alarms from original construction or rehabilitation stay AC powered","Carbon monoxide detectors within 10 feet of sleeping quarters, working, under 7 years old (standalone) or 10 years (combination)","No fire extinguisher for owner sales; the code lists extinguishers for rental and apartment units only","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of occupancy and inspection (combined with smoke/CO certificate), one and two family, more than 10 business days before the change of occupancy","amount":"$100"},{"label":"One and two family, 4 to 10 business days before","amount":"$135"},{"label":"One and two family, fewer than 4 business days before","amount":"$200"},{"label":"Reinspection, each","amount":"$35"}]$j$::jsonb, null, $t$https://www.eatontownnj.com/departments/fire-prevention-bureau$t$, $j$[{"url":"https://ecode360.com/7639663","label":"Official source (ecode360.com)"},{"url":"https://www.eatontownnj.com/departments/fire-prevention-bureau","label":"Official source (eatontownnj.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$To protect the health, safety, and wellness of all residents and first responders, the owner shall obtain a combined certificate of smoke alarm, carbon monoxide alarm, and compliance.$t$, $t$685fecb4b79b377d72774251f0217a3cca9721058def57e7a3d0163d9ebbd303$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":0,"fee_bad":0,"fee_unchecked":10,"quotes":15,"q_ok":7,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/1312.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1312.json$t$, true),
  ($t$1504$t$, $t$Beach Haven Borough$t$, $t$OCEAN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale Certificate of Occupancy (resale inspection)$t$, $j$["Issued by: Borough of Beach Haven Zoning Department (Construction and Zoning)","Contact: Vivienne “Veev” Washburn, Assistant Zoning Officer · 609-492-0111 x224 · vwashburn@beachhaven-nj.gov","Apply: Allow 2 weeks to schedule the inspection; resale inspections are done Tuesday and Thursday afternoons","How to apply: Bring the completed Resale Certificate of Occupancy form, the other listed paperwork (current plot plan and elevation certificate, filed deed restriction, condominium certification if a condo), a check made out to the Borough of Beach Haven and property access information to the Construction and Zoning office, 300 Engleside Avenue (the form also lists cash). The deed restriction must be filed with the Ocean County Clerk's Office in Toms River.","Visual inspection only, not a structural inspection","General condition of the lot, exterior and interior","Porch, deck and stair condition","Smoke alarms and carbon monoxide alarm(s)","Acceptable electrical and plumbing systems","Proper venting of heating equipment","Relief valves on water heaters and boilers piped down to within 6 inches of the floor (no plastic or galvanized pipe); water heater cabinets open for the inspection","Proper fire separation between an attached garage and living areas","Bedroom windows open easily for escape","House numbers on the building (3 inch numbers for homes)","Door locks on exit doors work and are not double-keyed","Portable fire extinguisher (2A:10B:C, no more than 10 lbs) mounted within 10 feet of the kitchen and no more than 5 feet above the floor (still listed on the Borough's 2024 sheet)","Current plot plan survey and flood elevation certificate with raised seals in the buyer's name","No open permits: all open permits must be finaled before the resale inspection","Property must be unoccupied, alarm systems disabled and dogs removed or crated at the inspection","Also: Deed restriction: A Declaration of Deed Restriction (FEMA flood regulations) must be filed with the Ocean County Clerk's Office in Toms River (or fees paid, per the form) for the resale certificate.","Also: Plot plan survey and flood elevation certificate: Current plot plan survey and flood elevation certificate with raised seals in the buyer's name.","Also: Open permits: All open permits must be finaled before the resale inspection.","Also: Condominium certification: Condo units use the Borough's Condominium Certification form listed with the resale paperwork.","Also: Emergency access placard: Resident Emergency Access Placards (non-condo owners) must be visible at the inspection and left in the property for the new owner."]$j$::jsonb, $j$[{"label":"Resale Certificate of Occupancy, each residential unit","amount":"$75.00"},{"label":"Resale Certificate of Occupancy, reinspection","amount":"$20.00"},{"label":"Resale Certificate of Occupancy, duplex (form)","amount":"$150.00"}]$j$::jsonb, $t$https://beachhaven-nj.gov/wp-content/uploads/2023/09/Resale-Form-2023.pdf$t$, $t$https://beachhaven-nj.gov/departments/construction-zoning/$t$, $j$[{"url":"https://beachhaven-nj.gov/departments/construction-zoning/","label":"Official source (beachhaven-nj.gov)"},{"url":"https://beachhaven-nj.gov/wp-content/uploads/2023/09/Resale-Form-2023.pdf","label":"Official source (beachhaven-nj.gov)"},{"url":"https://beachhaven-nj.gov/wp-content/uploads/2024/09/CURRENT-Resale-Inspection-Requirements.pdf","label":"Official source (beachhaven-nj.gov)"}]$j$::jsonb, $t$Resale inspections will be done on Tuesday & Thursday afternoons. The property must be unoccupied, alarm systems must be disabled, and dogs must be removed or crated. Please allow 2 weeks to schedule inspection.$t$, $t$9e275008ad1ecc37a6845e5d02f39eabd16fa62be2d9ac8c105243fcbef5e751$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":2,"fee_bad":0,"fee_unchecked":3,"quotes":24,"q_ok":18,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/1504.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/1504.json$t$, true),
  ($t$1504$t$, $t$Beach Haven Borough$t$, $t$OCEAN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Beach Haven Fire Inspector (Borough CSACMAPFEC inspections under Chapter 95, Article XIV) (town fire bureau)","Contact: 609-492-0111","Apply: The posted $35 fee covers applications received more than 10 working days before settlement; fees for shorter notice are not published. The certificate is not transferable.","How to apply: The Borough now issues the smoke/CO certificate for sales. The Construction and Zoning page says an online link to schedule the Smoke/CO Inspection with the Beach Haven Fire Inspector is 'COMING SOON', so for now call Borough Hall (609-492-0111; Municipal Clerk ext. 216 or 210, Construction and Zoning ext. 223 or 224) to apply and schedule. Review the Borough's Inspection Information Sheet (September 2026) before the inspection.","Fire official in the NJ state directory (county fire marshal), updated 7/14/2026: Dennis Allen · (732) 370-7360 · dallen@co.ocean.nj.us","Borough certificate of smoke alarm and carbon monoxide alarm compliance (CSACMAPFEC) on the sale of any property (Borough Code Chapter 95, Article XIV, adopted July 13, 2026)","Smoke alarms on every living level including the basement, and within 10 feet of bedrooms on levels with bedrooms","All smoke alarms, including hardwired, must be under 10 years old","Homes built before 1978: at least one 10-year sealed battery smoke alarm on each level; 1978 to 1983: hardwired alarms on each level; 1984 to 1990: interconnected hardwired alarms with battery backup on each level; 1991 and later: also in every bedroom","Hardwired alarms that need replacing must be replaced with hardwired alarms, not battery alarms","Carbon monoxide alarm in the immediate vicinity of the sleeping areas if the home has a fuel-burning device or an attached garage; battery and plug-in CO alarms should be under 5 years old, combination smoke/CO alarms under 10","Portable fire extinguishers are no longer required (as of February 3, 2025)","Do not mount alarms in unfinished attics, garages, stairwells, the top of basement stairs or kitchens","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO (CSACMAPFEC) inspection for a sale, application received more than 10 working days before settlement","amount":"$35"},{"label":"Reinspection, third and each later reinspection","amount":"$35"}]$j$::jsonb, null, $t$https://beachhaven-nj.gov/departments/construction-zoning/$t$, $j$[{"url":"https://ecode360.com/51420052","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/51420053","label":"Official source (ecode360.com)"},{"url":"https://beachhaven-nj.gov/introduced-ordinance-2026-10c/","label":"Official source (beachhaven-nj.gov)"},{"url":"https://beachhaven-nj.gov/ordinance-2026-10c-finally-adopted/","label":"Official source (beachhaven-nj.gov)"},{"url":"https://beachhaven-nj.gov/departments/construction-zoning/","label":"Official source (beachhaven-nj.gov)"},{"url":"https://beachhaven-nj.gov/departments/municipal-clerk/","label":"Official source (beachhaven-nj.gov)"},{"url":"https://beachhaven-nj.gov/wp-content/uploads/2026/09/UPDATED-Fire-Inspection-Requirements.pdf","label":"Official source (beachhaven-nj.gov)"},{"url":"https://co.ocean.nj.us/OC/FireMarshal/frmSmokeDetector.aspx","label":"Official source (co.ocean.nj.us)"}]$j$::jsonb, $t$All properties shall be inspected for CSACMAPFEC compliance upon the sale of property and rental properties upon the change of tenant for long-term rentals and one-time annually prior to May 31 for seasonal rentals pursuant to the provisions of N.J.A.C. 5:70-2.3.$t$, $t$54c77d87a9395d6dcb46221f46421c84236282d393d498ad43e86f8d34232cd0$t$, $t$2026-10-13T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-13","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":2,"fee_bad":0,"fee_unchecked":3,"quotes":24,"q_ok":18,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/1504.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-13 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/1504.json$t$, true)
